-- WiseWatts EMS pre-production baseline
-- Generated from the verified historical migration sequence.
--
-- Canonical DDL creates the original database foundation.
-- This baseline applies the later platform evolution from migration 82
-- through migration 179.
--
-- Excluded:
--   97_mqtt_staging_timestamptz.sql
--     Obsolete table conversion; mqtt_staging is now a compatibility view.
--   157_relationship_type_config_schema_permission.sql
--     Repository file absent from the production migration ledger.


-- ====================================================================
-- Historical migration: 82_admin_hierarchy_lookup_views.sql
-- ====================================================================

-- ============================================================================
-- File: 82_admin_hierarchy_lookup_views.sql
-- Purpose:
--   Provide controlled, read-only hierarchy catalogs for the progressive
--   EMS onboarding wizard.
--
-- Hierarchy:
--   Organization
--       -> Site
--           -> Gateway
--               -> Device
--
-- Security:
--   * Views are created with PostgreSQL security barriers.
--   * PUBLIC receives no privileges.
--   * ems_app receives SELECT only.
--   * Direct writes continue through the controlled onboarding function.
-- ============================================================================




-- ============================================================================
-- 1. ORGANIZATIONS
-- ============================================================================

CREATE OR REPLACE VIEW admin.v_organizations
WITH
(
    security_barrier = TRUE
)
AS
SELECT
    o.id,
    o.code AS organization_code,
    o.name AS organization_name,
    o.description,
    o.is_active,
    o.created_at,
    o.updated_at
FROM metadata.organizations o
WHERE o.is_active = TRUE;


COMMENT ON VIEW admin.v_organizations IS
'Active organizations available for explicit selection in the EMS onboarding wizard.';


-- ============================================================================
-- 2. SITES
-- ============================================================================

CREATE OR REPLACE VIEW admin.v_sites
WITH
(
    security_barrier = TRUE
)
AS
SELECT
    s.id,
    s.organization_id,
    o.code AS organization_code,
    o.name AS organization_name,
    s.code AS site_code,
    s.name AS site_name,
    s.timezone,
    s.address,
    s.is_active,
    s.created_at,
    s.updated_at
FROM metadata.sites s
JOIN metadata.organizations o
  ON o.id = s.organization_id
WHERE s.is_active = TRUE
  AND o.is_active = TRUE;


COMMENT ON VIEW admin.v_sites IS
'Active sites with organization ownership for dependent onboarding selection.';


-- ============================================================================
-- 3. GATEWAYS
-- ============================================================================

CREATE OR REPLACE VIEW admin.v_gateways
WITH
(
    security_barrier = TRUE
)
AS
SELECT
    g.id,
    g.organization_id,
    o.code AS organization_code,
    o.name AS organization_name,

    g.site_id,
    s.code AS site_code,
    s.name AS site_name,

    g.space_id,
    sp.code AS space_code,
    sp.name AS space_name,

    g.gateway_model_id,
    gm.vendor AS gateway_vendor,
    gm.model AS gateway_model,
    gm.protocol AS gateway_protocol,

    g.external_id,
    g.name AS gateway_name,
    g.created_at

FROM metadata.gateways g

JOIN metadata.organizations o
  ON o.id = g.organization_id

JOIN metadata.sites s
  ON s.id = g.site_id
 AND s.organization_id = g.organization_id

LEFT JOIN metadata.spaces sp
  ON sp.id = g.space_id
 AND sp.organization_id = g.organization_id

LEFT JOIN metadata.gateway_models gm
  ON gm.id = g.gateway_model_id

WHERE o.is_active = TRUE
  AND s.is_active = TRUE;


COMMENT ON VIEW admin.v_gateways IS
'Gateways with organization, site, optional space, and gateway-model ownership for dependent onboarding selection.';


-- ============================================================================
-- 4. DEVICES
-- ============================================================================

CREATE OR REPLACE VIEW admin.v_devices
WITH
(
    security_barrier = TRUE
)
AS
SELECT
    d.id,
    d.organization_id,
    o.code AS organization_code,
    o.name AS organization_name,

    d.gateway_id,
    g.site_id,
    s.code AS site_code,
    s.name AS site_name,
    g.external_id AS gateway_external_id,
    g.name AS gateway_name,

    d.device_model_id,
    dm.vendor AS device_vendor,
    dm.model AS device_model,
    dm.device_category_id,
    dc.name AS device_category_name,

    d.profile_id,
    dp.profile_code,
    dp.profile_name,

    d.external_id,
    d.name AS device_name,
    d.serial_number,
    d.firmware_version,
    d.protocol,
    d.created_at,
    d.updated_at

FROM metadata.devices d

JOIN metadata.organizations o
  ON o.id = d.organization_id

LEFT JOIN metadata.gateways g
  ON g.id = d.gateway_id
 AND g.organization_id = d.organization_id

LEFT JOIN metadata.sites s
  ON s.id = g.site_id
 AND s.organization_id = d.organization_id

LEFT JOIN metadata.device_models dm
  ON dm.id = d.device_model_id

LEFT JOIN config.device_categories dc
  ON dc.id = dm.device_category_id

LEFT JOIN config.device_profiles dp
  ON dp.id = d.profile_id

WHERE o.is_active = TRUE;


COMMENT ON VIEW admin.v_devices IS
'Devices with organization, gateway, site, model, category, and profile ownership for dependent onboarding selection.';


-- ============================================================================
-- 5. LEAST-PRIVILEGE ACCESS
-- ============================================================================

REVOKE ALL ON admin.v_organizations FROM PUBLIC;
REVOKE ALL ON admin.v_sites FROM PUBLIC;
REVOKE ALL ON admin.v_gateways FROM PUBLIC;
REVOKE ALL ON admin.v_devices FROM PUBLIC;

GRANT USAGE ON SCHEMA admin TO ems_app;

GRANT SELECT ON admin.v_organizations TO ems_app;
GRANT SELECT ON admin.v_sites TO ems_app;
GRANT SELECT ON admin.v_gateways TO ems_app;
GRANT SELECT ON admin.v_devices TO ems_app;


-- ====================================================================
-- Historical migration: 83_onboarding_explicit_hierarchy_modes.sql
-- ====================================================================

-- ============================================================================
-- File: 83_onboarding_explicit_hierarchy_modes.sql
-- Purpose:
--   Upgrade the EMS onboarding contract to support a progressive wizard with
--   explicit CREATE_NEW and USE_EXISTING behavior at each hierarchy level.
--
-- Supported hierarchy modes:
--   organization.mode = CREATE_NEW | USE_EXISTING
--   site.mode         = CREATE_NEW | USE_EXISTING
--   location.mode     = SITE_ONLY | CREATE_LOCATION | USE_EXISTING_SPACE
--   gateway.mode      = CREATE_NEW | USE_EXISTING
--   device.mode       = CREATE_NEW | USE_EXISTING
--   asset.mode        = CREATE_NEW | USE_EXISTING
--
-- Safety:
--   * Existing objects are never silently moved or overwritten when
--     USE_EXISTING is selected.
--   * Every selected object is validated against its parent hierarchy.
--   * The function remains SECURITY DEFINER with a fixed search_path.
-- ============================================================================



CREATE OR REPLACE FUNCTION admin.onboard_energy_asset(p_request jsonb, p_requested_by text DEFAULT CURRENT_USER)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'admin', 'metadata', 'config'
AS $function$
DECLARE
    v_organization_mode        TEXT;
    v_existing_organization_id UUID;
    v_organization_name        TEXT;
    v_organization_code        TEXT;
    v_organization_description TEXT;

    v_site_mode                TEXT;
    v_existing_site_id         UUID;
    v_site_name                TEXT;
    v_site_code                TEXT;
    v_site_timezone            TEXT;
    v_site_address             JSONB;

    v_location_mode            TEXT;
    v_existing_space_id        UUID;

    v_building_name            TEXT;
    v_building_code            TEXT;
    v_building_id              UUID;

    v_floor_name               TEXT;
    v_floor_code               TEXT;
    v_floor_id                 UUID;

    v_space_name               TEXT;
    v_space_code               TEXT;
    v_space_id                 UUID;

    v_gateway_mode             TEXT;
    v_existing_gateway_id      UUID;
    v_gateway_name             TEXT;
    v_gateway_external_id      TEXT;
    v_gateway_vendor           TEXT;
    v_gateway_model            TEXT;
    v_gateway_protocol         TEXT;

    v_device_mode              TEXT;
    v_existing_device_id       UUID;
    v_device_name              TEXT;
    v_device_external_id       TEXT;
    v_device_model_vendor      TEXT;
    v_device_model             TEXT;

    -- device_type is retained temporarily for backward compatibility.
    v_device_type              TEXT;
    v_device_category_id       UUID;
    v_device_category_name     TEXT;
    v_existing_model_category_id UUID;

    v_device_firmware_version  TEXT;
    v_device_protocol          TEXT;
    v_profile_code             TEXT;

    v_identifier_type          TEXT;
    v_identifier_value         TEXT;

    v_asset_mode               TEXT;
    v_existing_asset_id        UUID;
    v_asset_name               TEXT;
    v_asset_type_id            UUID;
    v_relationship_type        TEXT;
    v_asset_metadata           JSONB;

    v_grafana_org_id           BIGINT;

    v_organization_id          UUID;
    v_site_id                  UUID;
    v_gateway_model_id         UUID;
    v_gateway_id               UUID;
    v_device_model_id          UUID;
    v_profile_id               UUID;
    v_device_id                UUID;
    v_asset_id                 UUID;

    v_existing_identifier_device_id UUID;
    v_existing_primary_asset_id     UUID;
    v_existing_grafana_org_id       BIGINT;
    v_existing_grafana_org_owner    UUID;

    v_result                    JSONB;
BEGIN
    --------------------------------------------------------------------------
    -- Validate request container.
    --------------------------------------------------------------------------

    IF p_request IS NULL
       OR jsonb_typeof(p_request) <> 'object'
    THEN
        RAISE EXCEPTION
            'Onboarding request must be a JSON object';
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize organization fields.
    --------------------------------------------------------------------------

    v_organization_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(
                    btrim(
                        p_request #>> '{organization,mode}'
                    ),
                    ''
                ),
                'CREATE_NEW'
            )
        );

    IF v_organization_mode NOT IN
    (
        'CREATE_NEW',
        'USE_EXISTING'
    )
    THEN
        RAISE EXCEPTION
            'organization.mode must be CREATE_NEW or USE_EXISTING';
    END IF;

    BEGIN
        v_existing_organization_id :=
            NULLIF
            (
                btrim(
                    p_request #>>
                    '{organization,existing_organization_id}'
                ),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'organization.existing_organization_id must be a valid UUID';
    END;

    v_organization_name :=
        NULLIF(
            btrim(
                p_request #>> '{organization,name}'
            ),
            ''
        );

    v_organization_code :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{organization,code}'
                ),
                ''
            )
        );

    v_organization_description :=
        NULLIF
        (
            btrim(
                p_request #>> '{organization,description}'
            ),
            ''
        );

    IF v_organization_mode = 'CREATE_NEW' THEN
        IF v_organization_name IS NULL THEN
            RAISE EXCEPTION
                'organization.name is required for CREATE_NEW';
        END IF;

        IF v_organization_code IS NULL THEN
            RAISE EXCEPTION
                'organization.code is required for CREATE_NEW';
        END IF;

        IF v_organization_code !~ '^[A-Z0-9_]+$' THEN
            RAISE EXCEPTION
                'organization.code must contain only A-Z, 0-9, and underscore';
        END IF;

    ELSE
        IF v_existing_organization_id IS NULL THEN
            RAISE EXCEPTION
                'organization.existing_organization_id is required for USE_EXISTING';
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize site fields.
    --------------------------------------------------------------------------

    v_site_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(
                    btrim(
                        p_request #>> '{site,mode}'
                    ),
                    ''
                ),
                'CREATE_NEW'
            )
        );

    IF v_site_mode NOT IN
    (
        'CREATE_NEW',
        'USE_EXISTING'
    )
    THEN
        RAISE EXCEPTION
            'site.mode must be CREATE_NEW or USE_EXISTING';
    END IF;

    BEGIN
        v_existing_site_id :=
            NULLIF
            (
                btrim(
                    p_request #>>
                    '{site,existing_site_id}'
                ),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'site.existing_site_id must be a valid UUID';
    END;

    v_site_name :=
        NULLIF(
            btrim(
                p_request #>> '{site,name}'
            ),
            ''
        );

    v_site_code :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{site,code}'
                ),
                ''
            )
        );

    v_site_timezone :=
        COALESCE
        (
            NULLIF(
                btrim(
                    p_request #>> '{site,timezone}'
                ),
                ''
            ),
            'Asia/Kolkata'
        );

    v_site_address :=
        COALESCE(
            p_request #> '{site,address}',
            '{}'::JSONB
        );

    IF v_site_mode = 'CREATE_NEW' THEN
        IF v_site_name IS NULL THEN
            RAISE EXCEPTION
                'site.name is required for CREATE_NEW';
        END IF;

        IF v_site_code IS NULL THEN
            RAISE EXCEPTION
                'site.code is required for CREATE_NEW';
        END IF;

        IF v_site_code !~ '^[A-Z0-9_]+$' THEN
            RAISE EXCEPTION
                'site.code must contain only A-Z, 0-9, and underscore';
        END IF;

        IF jsonb_typeof(v_site_address) <> 'object' THEN
            RAISE EXCEPTION
                'site.address must be a JSON object';
        END IF;

        IF NOT EXISTS
        (
            SELECT 1
            FROM pg_timezone_names
            WHERE name = v_site_timezone
        )
        THEN
            RAISE EXCEPTION
                'Unknown IANA timezone: %',
                v_site_timezone;
        END IF;

    ELSE
        IF v_existing_site_id IS NULL THEN
            RAISE EXCEPTION
                'site.existing_site_id is required for USE_EXISTING';
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize optional physical-location fields.
    --------------------------------------------------------------------------

    v_location_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(btrim(p_request #>> '{location,mode}'), ''),
                'SITE_ONLY'
            )
        );

    IF v_location_mode NOT IN
    (
        'SITE_ONLY',
        'CREATE_LOCATION',
        'USE_EXISTING_SPACE'
    )
    THEN
        RAISE EXCEPTION
            'location.mode must be SITE_ONLY, CREATE_LOCATION, or USE_EXISTING_SPACE';
    END IF;

    BEGIN
        v_existing_space_id :=
            NULLIF(
                btrim(p_request #>> '{location,existing_space_id}'),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'location.existing_space_id must be a valid UUID';
    END;

    v_building_name :=
        NULLIF(btrim(p_request #>> '{location,building_name}'), '');

    v_building_code :=
        upper(NULLIF(btrim(p_request #>> '{location,building_code}'), ''));

    v_floor_name :=
        NULLIF(btrim(p_request #>> '{location,floor_name}'), '');

    v_floor_code :=
        upper(NULLIF(btrim(p_request #>> '{location,floor_code}'), ''));

    v_space_name :=
        NULLIF(btrim(p_request #>> '{location,space_name}'), '');

    v_space_code :=
        upper(NULLIF(btrim(p_request #>> '{location,space_code}'), ''));

    IF v_location_mode = 'CREATE_LOCATION' THEN
        IF v_building_name IS NULL OR v_building_code IS NULL THEN
            RAISE EXCEPTION
                'location building name and code are required for CREATE_LOCATION';
        END IF;

        IF v_floor_name IS NULL OR v_floor_code IS NULL THEN
            RAISE EXCEPTION
                'location floor name and code are required for CREATE_LOCATION';
        END IF;

        IF v_space_name IS NULL OR v_space_code IS NULL THEN
            RAISE EXCEPTION
                'location space name and code are required for CREATE_LOCATION';
        END IF;

        IF v_building_code !~ '^[A-Z][A-Z0-9_]*$' THEN
            RAISE EXCEPTION
                'location.building_code must contain only A-Z, 0-9, and underscore';
        END IF;

        IF v_floor_code !~ '^[A-Z][A-Z0-9_]*$' THEN
            RAISE EXCEPTION
                'location.floor_code must contain only A-Z, 0-9, and underscore';
        END IF;

        IF v_space_code !~ '^[A-Z][A-Z0-9_]*$' THEN
            RAISE EXCEPTION
                'location.space_code must contain only A-Z, 0-9, and underscore';
        END IF;

    ELSIF v_location_mode = 'USE_EXISTING_SPACE' THEN
        IF v_existing_space_id IS NULL THEN
            RAISE EXCEPTION
                'location.existing_space_id is required for USE_EXISTING_SPACE';
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize gateway fields.
    --------------------------------------------------------------------------

    v_gateway_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(
                    btrim(
                        p_request #>> '{gateway,mode}'
                    ),
                    ''
                ),
                'CREATE_NEW'
            )
        );

    IF v_gateway_mode NOT IN
    (
        'CREATE_NEW',
        'USE_EXISTING'
    )
    THEN
        RAISE EXCEPTION
            'gateway.mode must be CREATE_NEW or USE_EXISTING';
    END IF;

    BEGIN
        v_existing_gateway_id :=
            NULLIF
            (
                btrim(
                    p_request #>>
                    '{gateway,existing_gateway_id}'
                ),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'gateway.existing_gateway_id must be a valid UUID';
    END;

    v_gateway_name :=
        NULLIF(
            btrim(
                p_request #>> '{gateway,name}'
            ),
            ''
        );

    v_gateway_external_id :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{gateway,external_id}'
                ),
                ''
            )
        );

    v_gateway_vendor :=
        NULLIF(
            btrim(
                p_request #>> '{gateway,vendor}'
            ),
            ''
        );

    v_gateway_model :=
        NULLIF(
            btrim(
                p_request #>> '{gateway,model}'
            ),
            ''
        );

    v_gateway_protocol :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{gateway,protocol}'
                ),
                ''
            )
        );

    IF v_gateway_mode = 'CREATE_NEW' THEN
        IF v_gateway_name IS NULL THEN
            RAISE EXCEPTION
                'gateway.name is required for CREATE_NEW';
        END IF;

        IF v_gateway_external_id IS NULL THEN
            RAISE EXCEPTION
                'gateway.external_id is required for CREATE_NEW';
        END IF;

        IF v_gateway_vendor IS NULL THEN
            RAISE EXCEPTION
                'gateway.vendor is required for CREATE_NEW';
        END IF;

        IF v_gateway_model IS NULL THEN
            RAISE EXCEPTION
                'gateway.model is required for CREATE_NEW';
        END IF;

        IF v_gateway_protocol IS NULL THEN
            RAISE EXCEPTION
                'gateway.protocol is required for CREATE_NEW';
        END IF;

    ELSE
        IF v_existing_gateway_id IS NULL THEN
            RAISE EXCEPTION
                'gateway.existing_gateway_id is required for USE_EXISTING';
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize device fields.
    --------------------------------------------------------------------------

    v_device_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(
                    btrim(
                        p_request #>> '{device,mode}'
                    ),
                    ''
                ),
                'CREATE_NEW'
            )
        );

    IF v_device_mode NOT IN
    (
        'CREATE_NEW',
        'USE_EXISTING'
    )
    THEN
        RAISE EXCEPTION
            'device.mode must be CREATE_NEW or USE_EXISTING';
    END IF;

    BEGIN
        v_existing_device_id :=
            NULLIF
            (
                btrim(
                    p_request #>>
                    '{device,existing_device_id}'
                ),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'device.existing_device_id must be a valid UUID';
    END;

    v_device_name :=
        NULLIF(
            btrim(
                p_request #>> '{device,name}'
            ),
            ''
        );

    v_device_external_id :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{device,external_id}'
                ),
                ''
            )
        );

    v_device_model_vendor :=
        NULLIF(
            btrim(
                p_request #>> '{device,model_vendor}'
            ),
            ''
        );

    v_device_model :=
        NULLIF(
            btrim(
                p_request #>> '{device,model}'
            ),
            ''
        );

    v_device_type :=
        NULLIF(
            btrim(
                p_request #>> '{device,device_type}'
            ),
            ''
        );

    BEGIN
        v_device_category_id :=
            NULLIF
            (
                btrim(
                    p_request #>>
                    '{device,device_category_id}'
                ),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'device.device_category_id must be a valid UUID';
    END;

    v_device_firmware_version :=
        NULLIF(
            btrim(
                p_request #>> '{device,firmware_version}'
            ),
            ''
        );

    v_device_protocol :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{device,protocol}'
                ),
                ''
            )
        );

    v_profile_code :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{device,profile_code}'
                ),
                ''
            )
        );

    IF v_device_mode = 'CREATE_NEW' THEN
        IF v_device_name IS NULL THEN
            RAISE EXCEPTION
                'device.name is required for CREATE_NEW';
        END IF;

        IF v_device_external_id IS NULL THEN
            RAISE EXCEPTION
                'device.external_id is required for CREATE_NEW';
        END IF;

        IF v_device_model_vendor IS NULL THEN
            RAISE EXCEPTION
                'device.model_vendor is required for CREATE_NEW';
        END IF;

        IF v_device_model IS NULL THEN
            RAISE EXCEPTION
                'device.model is required for CREATE_NEW';
        END IF;

        IF v_device_category_id IS NULL
           AND v_device_type IS NULL
        THEN
            RAISE EXCEPTION
                'device.device_category_id is required for CREATE_NEW';
        END IF;

        IF v_device_protocol IS NULL THEN
            RAISE EXCEPTION
                'device.protocol is required for CREATE_NEW';
        END IF;

        IF v_profile_code IS NULL THEN
            RAISE EXCEPTION
                'device.profile_code is required for CREATE_NEW';
        END IF;

    ELSE
        IF v_existing_device_id IS NULL THEN
            RAISE EXCEPTION
                'device.existing_device_id is required for USE_EXISTING';
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize external identifier fields.
    --
    -- CREATE_NEW device:
    --   Identifier type and value are mandatory.
    --
    -- USE_EXISTING device:
    --   Identifier fields are optional. When supplied, they are used only
    --   to verify an existing identifier already belongs to the selected
    --   device. They are never created, changed, or transferred.
    --------------------------------------------------------------------------

    v_identifier_type :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{identifier,type}'
                ),
                ''
            )
        );

    v_identifier_value :=
        NULLIF
        (
            btrim(
                p_request #>> '{identifier,value}'
            ),
            ''
        );

    IF
    (
        v_identifier_type IS NULL
        AND v_identifier_value IS NOT NULL
    )
    OR
    (
        v_identifier_type IS NOT NULL
        AND v_identifier_value IS NULL
    )
    THEN
        RAISE EXCEPTION
            'identifier.type and identifier.value must be supplied together';
    END IF;

    IF v_device_mode = 'CREATE_NEW' THEN
        IF v_identifier_type IS NULL THEN
            RAISE EXCEPTION
                'identifier.type is required for a new device';
        END IF;

        IF v_identifier_value IS NULL THEN
            RAISE EXCEPTION
                'identifier.value is required for a new device';
        END IF;
    END IF;

    IF v_identifier_type = 'MQTT_UID' THEN
        v_identifier_value := lower(v_identifier_value);
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize asset fields.
    --------------------------------------------------------------------------

    v_asset_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(btrim(p_request #>> '{asset,mode}'), ''),
                'CREATE_NEW'
            )
        );

    IF v_asset_mode NOT IN ('CREATE_NEW', 'USE_EXISTING') THEN
        RAISE EXCEPTION
            'asset.mode must be CREATE_NEW or USE_EXISTING';
    END IF;

    BEGIN
        v_existing_asset_id :=
            NULLIF(
                btrim(p_request #>> '{asset,existing_asset_id}'),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'asset.existing_asset_id must be a valid UUID';
    END;

    v_asset_name :=
        NULLIF(btrim(p_request #>> '{asset,name}'), '');

    BEGIN
        v_asset_type_id :=
            NULLIF(
                btrim(p_request #>> '{asset,asset_type_id}'),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION 'asset.asset_type_id must be a valid UUID';
    END;

    v_relationship_type :=
        upper
        (
            COALESCE
            (
                NULLIF
                (
                    btrim
                    (
                        p_request #>> '{asset,relationship_type}'
                    ),
                    ''
                ),
                'PRIMARY_METER'
            )
        );

    v_asset_metadata :=
        COALESCE(p_request #> '{asset,metadata}', '{}'::JSONB);

    IF v_asset_mode = 'CREATE_NEW' THEN
        IF v_asset_name IS NULL THEN
            RAISE EXCEPTION
                'asset.name is required for CREATE_NEW';
        END IF;

        IF v_asset_type_id IS NULL THEN
            RAISE EXCEPTION
                'asset.asset_type_id is required for CREATE_NEW';
        END IF;

        IF NOT EXISTS
        (
            SELECT 1
            FROM metadata.asset_types at
            WHERE at.id = v_asset_type_id
        )
        THEN
            RAISE EXCEPTION
                'Unknown asset type UUID: %',
                v_asset_type_id;
        END IF;
    ELSE
        IF v_existing_asset_id IS NULL THEN
            RAISE EXCEPTION
                'asset.existing_asset_id is required for USE_EXISTING';
        END IF;
    END IF;

    IF jsonb_typeof(v_asset_metadata) <> 'object' THEN
        RAISE EXCEPTION 'asset.metadata must be a JSON object';
    END IF;


    --------------------------------------------------------------------------
    -- Optional Grafana organization ID.
    --------------------------------------------------------------------------

    BEGIN
        v_grafana_org_id :=
            NULLIF(p_request ->> 'grafana_org_id', '')::BIGINT;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION 'grafana_org_id must be a positive integer';
    END;

    IF v_grafana_org_id IS NOT NULL
       AND v_grafana_org_id <= 0
    THEN
        RAISE EXCEPTION 'grafana_org_id must be greater than zero';
    END IF;


    --------------------------------------------------------------------------
    -- Organization selection or creation.
    --
    -- CREATE_NEW:
    --   Inserts a genuinely new organization and rejects an existing code.
    --
    -- USE_EXISTING:
    --   Loads the selected active organization without modifying it.
    --------------------------------------------------------------------------

    IF v_organization_mode = 'USE_EXISTING' THEN

        -- Serialize concurrent operations against the same organization UUID.
        PERFORM pg_advisory_xact_lock
        (
            hashtext(v_existing_organization_id::TEXT)
        );

        SELECT
            o.id,
            o.name,
            o.code,
            o.description
        INTO
            v_organization_id,
            v_organization_name,
            v_organization_code,
            v_organization_description
        FROM metadata.organizations o
        WHERE o.id = v_existing_organization_id
          AND o.is_active = TRUE;

        IF v_organization_id IS NULL THEN
            RAISE EXCEPTION
                'Existing active organization % was not found',
                v_existing_organization_id;
        END IF;

    ELSE

        -- Serialize concurrent creation attempts using the organization code.
        PERFORM pg_advisory_xact_lock
        (
            hashtext(v_organization_code)
        );

        BEGIN
            INSERT INTO metadata.organizations
            (
                name,
                code,
                description,
                is_active
            )
            VALUES
            (
                v_organization_name,
                v_organization_code,
                v_organization_description,
                TRUE
            )
            RETURNING id
            INTO v_organization_id;

        EXCEPTION
            WHEN unique_violation THEN
                RAISE EXCEPTION
                    'Organization code % already exists; use USE_EXISTING instead',
                    v_organization_code;
        END;
    END IF;


    --------------------------------------------------------------------------
    -- Site selection or creation.
    --
    -- CREATE_NEW:
    --   Inserts a new site under the resolved organization.
    --
    -- USE_EXISTING:
    --   Validates that the selected active site belongs to the resolved
    --   organization and preserves all stored site attributes.
    --------------------------------------------------------------------------

    IF v_site_mode = 'USE_EXISTING' THEN

        SELECT
            s.id,
            s.name,
            s.code,
            s.timezone,
            s.address
        INTO
            v_site_id,
            v_site_name,
            v_site_code,
            v_site_timezone,
            v_site_address
        FROM metadata.sites s
        WHERE s.id = v_existing_site_id
          AND s.organization_id = v_organization_id
          AND s.is_active = TRUE;

        IF v_site_id IS NULL THEN
            RAISE EXCEPTION
                'Existing active site % was not found under organization %',
                v_existing_site_id,
                v_organization_id;
        END IF;

    ELSE

        BEGIN
            INSERT INTO metadata.sites
            (
                organization_id,
                name,
                code,
                timezone,
                address,
                is_active
            )
            VALUES
            (
                v_organization_id,
                v_site_name,
                v_site_code,
                v_site_timezone,
                v_site_address,
                TRUE
            )
            RETURNING id
            INTO v_site_id;

        EXCEPTION
            WHEN unique_violation THEN
                RAISE EXCEPTION
                    'Site code % already exists under organization %; use USE_EXISTING instead',
                    v_site_code,
                    v_organization_id;
        END;
    END IF;


    --------------------------------------------------------------------------
    -- Optional physical hierarchy.
    --------------------------------------------------------------------------

    v_space_id := NULL;

    IF v_location_mode = 'USE_EXISTING_SPACE' THEN
        SELECT
            sp.id,
            f.id,
            b.id
        INTO
            v_space_id,
            v_floor_id,
            v_building_id
        FROM metadata.spaces sp
        JOIN metadata.floors f
          ON f.id = sp.floor_id
        JOIN metadata.buildings b
          ON b.id = f.building_id
        WHERE sp.id = v_existing_space_id
          AND sp.organization_id = v_organization_id
          AND b.site_id = v_site_id;

        IF v_space_id IS NULL THEN
            RAISE EXCEPTION
                'Existing space % was not found in organization % and site %',
                v_existing_space_id,
                v_organization_code,
                v_site_code;
        END IF;

    ELSIF v_location_mode = 'CREATE_LOCATION' THEN
        INSERT INTO metadata.buildings
        (
            organization_id,
            site_id,
            name,
            code
        )
        VALUES
        (
            v_organization_id,
            v_site_id,
            v_building_name,
            v_building_code
        )
        ON CONFLICT (site_id, code)
        DO UPDATE SET
            organization_id = EXCLUDED.organization_id,
            name            = EXCLUDED.name,
            updated_at      = now()
        RETURNING id
        INTO v_building_id;

        INSERT INTO metadata.floors
        (
            organization_id,
            building_id,
            name,
            code
        )
        VALUES
        (
            v_organization_id,
            v_building_id,
            v_floor_name,
            v_floor_code
        )
        ON CONFLICT (building_id, code)
        DO UPDATE SET
            organization_id = EXCLUDED.organization_id,
            name            = EXCLUDED.name,
            updated_at      = now()
        RETURNING id
        INTO v_floor_id;

        INSERT INTO metadata.spaces
        (
            organization_id,
            floor_id,
            name,
            code
        )
        VALUES
        (
            v_organization_id,
            v_floor_id,
            v_space_name,
            v_space_code
        )
        ON CONFLICT (floor_id, code)
        DO UPDATE SET
            organization_id = EXCLUDED.organization_id,
            name            = EXCLUDED.name,
            updated_at      = now()
        RETURNING id
        INTO v_space_id;
    END IF;


    --------------------------------------------------------------------------
    -- Gateway selection or creation.
    --
    -- CREATE_NEW:
    --   Resolves or creates the gateway model, then inserts a new gateway.
    --   The resolved physical space is assigned to gateway.space_id.
    --
    -- USE_EXISTING:
    --   Validates that the selected gateway belongs to the resolved
    --   organization and site. Existing gateway attributes are preserved.
    --------------------------------------------------------------------------

    IF v_gateway_mode = 'USE_EXISTING' THEN

        SELECT
            g.id,
            g.name,
            g.external_id,
            g.gateway_model_id
        INTO
            v_gateway_id,
            v_gateway_name,
            v_gateway_external_id,
            v_gateway_model_id
        FROM metadata.gateways g
        WHERE g.id = v_existing_gateway_id
          AND g.organization_id = v_organization_id
          AND g.site_id = v_site_id;

        IF v_gateway_id IS NULL THEN
            RAISE EXCEPTION
                'Existing gateway % was not found under organization % and site %',
                v_existing_gateway_id,
                v_organization_id,
                v_site_id;
        END IF;

    ELSE

        ----------------------------------------------------------------------
        -- Gateway model resolution.
        ----------------------------------------------------------------------

        SELECT gm.id
        INTO v_gateway_model_id
        FROM metadata.gateway_models gm
        WHERE lower(COALESCE(gm.vendor, '')) =
              lower(v_gateway_vendor)
          AND lower(gm.model) =
              lower(v_gateway_model)
        ORDER BY gm.created_at, gm.id
        LIMIT 1;

        IF v_gateway_model_id IS NULL THEN
            INSERT INTO metadata.gateway_models
            (
                vendor,
                model,
                protocol
            )
            VALUES
            (
                v_gateway_vendor,
                v_gateway_model,
                v_gateway_protocol
            )
            RETURNING id
            INTO v_gateway_model_id;
        END IF;

        BEGIN
            INSERT INTO metadata.gateways
            (
                organization_id,
                site_id,
                gateway_model_id,
                name,
                external_id,
                space_id
            )
            VALUES
            (
                v_organization_id,
                v_site_id,
                v_gateway_model_id,
                v_gateway_name,
                v_gateway_external_id,
                v_space_id
            )
            RETURNING id
            INTO v_gateway_id;

        EXCEPTION
            WHEN unique_violation THEN
                RAISE EXCEPTION
                    'Gateway external ID % already exists under organization %; use USE_EXISTING instead',
                    v_gateway_external_id,
                    v_organization_id;
        END;
    END IF;


    --------------------------------------------------------------------------
    -- Device selection or creation.
    --
    -- CREATE_NEW:
    --   Resolves the controlled category, relationship compatibility,
    --   device model, and active compatible profile before inserting.
    --
    -- USE_EXISTING:
    --   Validates that the selected device belongs to the resolved
    --   organization and gateway. Existing device attributes are preserved.
    --------------------------------------------------------------------------

    IF v_device_mode = 'USE_EXISTING' THEN

        SELECT
            d.id,
            d.name,
            d.external_id,
            d.device_model_id,
            d.firmware_version,
            d.protocol,
            d.profile_id,
            dm.device_category_id,
            dc.name,
            dp.profile_code
        INTO
            v_device_id,
            v_device_name,
            v_device_external_id,
            v_device_model_id,
            v_device_firmware_version,
            v_device_protocol,
            v_profile_id,
            v_device_category_id,
            v_device_category_name,
            v_profile_code
        FROM metadata.devices d
        LEFT JOIN metadata.device_models dm
          ON dm.id = d.device_model_id
        LEFT JOIN config.device_categories dc
          ON dc.id = dm.device_category_id
        LEFT JOIN config.device_profiles dp
          ON dp.id = d.profile_id
        WHERE d.id = v_existing_device_id
          AND d.organization_id = v_organization_id
          AND d.gateway_id = v_gateway_id;

        IF v_device_id IS NULL THEN
            RAISE EXCEPTION
                'Existing device % was not found under organization % and gateway %',
                v_existing_device_id,
                v_organization_id,
                v_gateway_id;
        END IF;

        IF v_device_category_id IS NULL
           OR v_device_category_name IS NULL
        THEN
            RAISE EXCEPTION
                'Existing device % does not have a controlled device category',
                v_existing_device_id;
        END IF;

        IF v_profile_id IS NULL
           OR v_profile_code IS NULL
        THEN
            RAISE EXCEPTION
                'Existing device % does not have an active onboarding profile',
                v_existing_device_id;
        END IF;

    ELSE

        ----------------------------------------------------------------------
        -- Controlled device category.
        ----------------------------------------------------------------------

        IF v_device_category_id IS NOT NULL THEN
            SELECT
                dc.id,
                dc.name
            INTO
                v_device_category_id,
                v_device_category_name
            FROM config.device_categories dc
            WHERE dc.id = v_device_category_id;
        ELSE
            SELECT
                dc.id,
                dc.name
            INTO
                v_device_category_id,
                v_device_category_name
            FROM config.device_categories dc
            WHERE lower(dc.name) = lower(v_device_type)
            ORDER BY dc.created_at, dc.id
            LIMIT 1;
        END IF;

        IF v_device_category_id IS NULL THEN
            RAISE EXCEPTION
                'Controlled device category was not found';
        END IF;

        -- Keep the legacy text value synchronized during the transition.
        v_device_type := v_device_category_name;


        ----------------------------------------------------------------------
        -- Controlled category-to-asset relationship compatibility.
        ----------------------------------------------------------------------

        IF v_device_category_name = 'Energy Meter' THEN
            IF v_relationship_type NOT IN
            (
                'PRIMARY_METER',
                'SECONDARY_METER',
                'SECONDARY_METER'
            )
            THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Environmental Sensor' THEN
            IF v_relationship_type NOT IN
            (
                'TEMPERATURE_SENSOR',
                'HUMIDITY_SENSOR'
            )
            THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Temperature Sensor' THEN
            IF v_relationship_type <> 'TEMPERATURE_SENSOR' THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Flow Meter' THEN
            IF v_relationship_type <> 'FLOW_SENSOR' THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Pressure Sensor' THEN
            IF v_relationship_type <> 'PRESSURE_SENSOR' THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Digital Input Module' THEN
            IF v_relationship_type NOT IN
            (
                'STATUS_INPUT',
                'RUN_STATUS',
                'FAULT_STATUS'
            )
            THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'BMS Controller' THEN
            IF v_relationship_type <> 'CONTROLLER' THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'PLC' THEN
            IF v_relationship_type NOT IN
            (
                'CONTROLLER',
                'STATUS_INPUT',
                'RUN_STATUS',
                'FAULT_STATUS'
            )
            THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Gateway' THEN
            RAISE EXCEPTION
                'Device category Gateway cannot be attached directly to an asset';

        ELSE
            RAISE EXCEPTION
                'No asset relationship rules are configured for device category %',
                v_device_category_name;
        END IF;


        ----------------------------------------------------------------------
        -- Device model.
        ----------------------------------------------------------------------

        SELECT
            dm.id,
            dm.device_category_id
        INTO
            v_device_model_id,
            v_existing_model_category_id
        FROM metadata.device_models dm
        WHERE lower(COALESCE(dm.vendor, '')) =
              lower(v_device_model_vendor)
          AND lower(dm.model) =
              lower(v_device_model)
        ORDER BY dm.created_at, dm.id
        LIMIT 1;

        IF v_device_model_id IS NULL THEN
            INSERT INTO metadata.device_models
            (
                vendor,
                model,
                device_type,
                device_category_id
            )
            VALUES
            (
                v_device_model_vendor,
                v_device_model,
                v_device_type,
                v_device_category_id
            )
            RETURNING id
            INTO v_device_model_id;
        ELSE
            IF v_existing_model_category_id <> v_device_category_id THEN
                RAISE EXCEPTION
                    'Device model % / % already belongs to a different category',
                    v_device_model_vendor,
                    v_device_model;
            END IF;

            UPDATE metadata.device_models
            SET device_type = v_device_category_name
            WHERE id = v_device_model_id
              AND device_type IS DISTINCT FROM v_device_category_name;
        END IF;


        ----------------------------------------------------------------------
        -- Active payload profile.
        ----------------------------------------------------------------------

        SELECT dp.id
        INTO v_profile_id
        FROM config.device_profiles dp
        WHERE dp.profile_code = v_profile_code
          AND dp.is_active = TRUE;

        IF v_profile_id IS NULL THEN
            RAISE EXCEPTION
                'Active device profile not found: %',
                v_profile_code;
        END IF;

        IF NOT EXISTS
        (
            SELECT 1
            FROM config.device_profile_categories dpc
            WHERE dpc.profile_id = v_profile_id
              AND dpc.device_category_id = v_device_category_id
        )
        THEN
            RAISE EXCEPTION
                'Device profile % is not compatible with device category %',
                v_profile_code,
                v_device_category_name;
        END IF;


        ----------------------------------------------------------------------
        -- Insert new device.
        ----------------------------------------------------------------------

        BEGIN
            INSERT INTO metadata.devices
            (
                organization_id,
                gateway_id,
                device_model_id,
                name,
                external_id,
                serial_number,
                firmware_version,
                protocol,
                profile_id
            )
            VALUES
            (
                v_organization_id,
                v_gateway_id,
                v_device_model_id,
                v_device_name,
                v_device_external_id,
                NULL,
                v_device_firmware_version,
                v_device_protocol,
                v_profile_id
            )
            RETURNING id
            INTO v_device_id;

        EXCEPTION
            WHEN unique_violation THEN
                RAISE EXCEPTION
                    'Device external ID % already exists under organization %; use USE_EXISTING instead',
                    v_device_external_id,
                    v_organization_id;
        END;
    END IF;


    --------------------------------------------------------------------------
    -- Validate relationship compatibility for both new and existing devices.
    --------------------------------------------------------------------------

    IF v_device_category_name = 'Energy Meter' THEN
        IF v_relationship_type NOT IN
        (
            'PRIMARY_METER',
            'SECONDARY_METER',
            'SECONDARY_METER'
        )
        THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Environmental Sensor' THEN
        IF v_relationship_type NOT IN
        (
            'TEMPERATURE_SENSOR',
            'HUMIDITY_SENSOR'
        )
        THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Temperature Sensor' THEN
        IF v_relationship_type <> 'TEMPERATURE_SENSOR' THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Flow Meter' THEN
        IF v_relationship_type <> 'FLOW_SENSOR' THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Pressure Sensor' THEN
        IF v_relationship_type <> 'PRESSURE_SENSOR' THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Digital Input Module' THEN
        IF v_relationship_type NOT IN
        (
            'STATUS_INPUT',
            'RUN_STATUS',
            'FAULT_STATUS'
        )
        THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'BMS Controller' THEN
        IF v_relationship_type <> 'CONTROLLER' THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'PLC' THEN
        IF v_relationship_type NOT IN
        (
            'CONTROLLER',
            'STATUS_INPUT',
            'RUN_STATUS',
            'FAULT_STATUS'
        )
        THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Gateway' THEN
        RAISE EXCEPTION
            'Device category Gateway cannot be attached directly to an asset';

    ELSE
        RAISE EXCEPTION
            'No asset relationship rules are configured for device category %',
            v_device_category_name;
    END IF;


    --------------------------------------------------------------------------
    -- External device identifier.
    --
    -- CREATE_NEW:
    --   Creates the required external identifier only when it is not already
    --   owned by another device.
    --
    -- USE_EXISTING:
    --   Preserves all identifiers. Optional supplied values are verification
    --   inputs only and must already belong to the selected device.
    --------------------------------------------------------------------------

    IF v_device_mode = 'CREATE_NEW' THEN

        SELECT di.device_id
        INTO v_existing_identifier_device_id
        FROM metadata.device_identifiers di
        WHERE di.identifier_type = v_identifier_type
          AND
          (
              CASE
                  WHEN v_identifier_type = 'MQTT_UID'
                  THEN lower(di.identifier_value)
                  ELSE di.identifier_value
              END
          ) = v_identifier_value
        ORDER BY di.created_at, di.id
        LIMIT 1;

        IF v_existing_identifier_device_id IS NOT NULL THEN
            RAISE EXCEPTION
                'Identifier %:% is already assigned to device %',
                v_identifier_type,
                v_identifier_value,
                v_existing_identifier_device_id;
        END IF;

        INSERT INTO metadata.device_identifiers
        (
            device_id,
            identifier_type,
            identifier_value
        )
        VALUES
        (
            v_device_id,
            v_identifier_type,
            v_identifier_value
        );

    ELSIF v_identifier_type IS NOT NULL THEN

        SELECT di.device_id
        INTO v_existing_identifier_device_id
        FROM metadata.device_identifiers di
        WHERE di.identifier_type = v_identifier_type
          AND
          (
              CASE
                  WHEN v_identifier_type = 'MQTT_UID'
                  THEN lower(di.identifier_value)
                  ELSE di.identifier_value
              END
          ) = v_identifier_value
        ORDER BY di.created_at, di.id
        LIMIT 1;

        IF v_existing_identifier_device_id IS NULL THEN
            RAISE EXCEPTION
                'Identifier %:% does not exist for the selected device',
                v_identifier_type,
                v_identifier_value;
        END IF;

        IF v_existing_identifier_device_id <> v_device_id THEN
            RAISE EXCEPTION
                'Identifier %:% belongs to device %, not selected device %',
                v_identifier_type,
                v_identifier_value,
                v_existing_identifier_device_id,
                v_device_id;
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Asset selection or creation.
    --------------------------------------------------------------------------

    IF v_asset_mode = 'USE_EXISTING' THEN
        SELECT
            a.id,
            a.name,
            a.asset_type_id
        INTO
            v_asset_id,
            v_asset_name,
            v_asset_type_id
        FROM metadata.assets a
        WHERE a.id = v_existing_asset_id
          AND a.organization_id = v_organization_id
          AND a.site_id = v_site_id;

        IF v_asset_id IS NULL THEN
            RAISE EXCEPTION
                'Existing asset % was not found in organization % and site %',
                v_existing_asset_id,
                v_organization_code,
                v_site_code;
        END IF;

    ELSE
        SELECT a.id
        INTO v_asset_id
        FROM metadata.assets a
        WHERE a.organization_id = v_organization_id
          AND a.site_id = v_site_id
          AND a.parent_asset_id IS NULL
          AND a.name = v_asset_name
          AND a.space_id IS NOT DISTINCT FROM v_space_id
        ORDER BY a.created_at, a.id
        LIMIT 1;

        IF v_asset_id IS NULL THEN
            INSERT INTO metadata.assets
            (
                organization_id,
                site_id,
                asset_type_id,
                parent_asset_id,
                name,
                manufacturer,
                model,
                serial_number,
                status,
                metadata,
                space_id
            )
            VALUES
            (
                v_organization_id,
                v_site_id,
                v_asset_type_id,
                NULL,
                v_asset_name,
                NULL,
                NULL,
                NULL,
                'active',
                v_asset_metadata,
                v_space_id
            )
            RETURNING id
            INTO v_asset_id;
        ELSE
            UPDATE metadata.assets
            SET
                asset_type_id = v_asset_type_id,
                status        = 'active',
                metadata      = v_asset_metadata,
                space_id      = v_space_id,
                updated_at    = now()
            WHERE id = v_asset_id;
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Asset-device relationship.
    --
    -- The canonical partial unique index allows a device to be PRIMARY_METER
    -- for at most one asset.
    --------------------------------------------------------------------------

    IF v_relationship_type = 'PRIMARY_METER' THEN
        SELECT ad.asset_id
        INTO v_existing_primary_asset_id
        FROM metadata.asset_devices ad
        WHERE ad.device_id = v_device_id
          AND ad.relationship_type = 'PRIMARY_METER'
        ORDER BY ad.created_at, ad.id
        LIMIT 1;

        IF v_existing_primary_asset_id IS NOT NULL
           AND v_existing_primary_asset_id <> v_asset_id
        THEN
            RAISE EXCEPTION
                'Device % is already PRIMARY_METER for asset %',
                v_device_id,
                v_existing_primary_asset_id;
        END IF;

        IF EXISTS
        (
            SELECT 1
            FROM metadata.asset_devices ad
            WHERE ad.asset_id = v_asset_id
              AND ad.relationship_type = 'PRIMARY_METER'
              AND ad.device_id <> v_device_id
        )
        THEN
            RAISE EXCEPTION
                'Asset % already has a different PRIMARY_METER',
                v_asset_id;
        END IF;
    END IF;

    INSERT INTO metadata.asset_devices
    (
        asset_id,
        device_id,
        relationship_type
    )
    VALUES
    (
        v_asset_id,
        v_device_id,
        v_relationship_type
    )
    ON CONFLICT
        (asset_id, device_id, relationship_type)
    DO NOTHING;


    --------------------------------------------------------------------------
    -- Optional Grafana organization mapping.
    --
    -- Reject both forms of cross-tenant reassignment:
    --
    --   1. EMS organization already mapped to a different Grafana org.
    --   2. Grafana org already mapped to a different EMS organization.
    --------------------------------------------------------------------------

    IF v_grafana_org_id IS NOT NULL THEN
        SELECT gom.grafana_org_id
        INTO v_existing_grafana_org_id
        FROM metadata.grafana_organization_map gom
        WHERE gom.organization_id = v_organization_id;

        IF v_existing_grafana_org_id IS NOT NULL
           AND v_existing_grafana_org_id <> v_grafana_org_id
        THEN
            RAISE EXCEPTION
                'EMS organization % is already mapped to Grafana org %',
                v_organization_id,
                v_existing_grafana_org_id;
        END IF;

        SELECT gom.organization_id
        INTO v_existing_grafana_org_owner
        FROM metadata.grafana_organization_map gom
        WHERE gom.grafana_org_id = v_grafana_org_id;

        IF v_existing_grafana_org_owner IS NOT NULL
           AND v_existing_grafana_org_owner <> v_organization_id
        THEN
            RAISE EXCEPTION
                'Grafana org % is already mapped to EMS organization %',
                v_grafana_org_id,
                v_existing_grafana_org_owner;
        END IF;

        INSERT INTO metadata.grafana_organization_map
        (
            grafana_org_id,
            organization_id,
            is_active
        )
        VALUES
        (
            v_grafana_org_id,
            v_organization_id,
            TRUE
        )
        ON CONFLICT (grafana_org_id)
        DO UPDATE SET
            organization_id = EXCLUDED.organization_id,
            is_active        = TRUE,
            updated_at       = now();
    END IF;


    --------------------------------------------------------------------------
    -- Build result and audit successful completion.
    --------------------------------------------------------------------------

    v_result :=
        jsonb_build_object
        (
            'organization_id',  v_organization_id,
            'organization_code', v_organization_code,
            'site_id',          v_site_id,
            'site_code',        v_site_code,
            'location_mode',    v_location_mode,
            'building_id',      v_building_id,
            'floor_id',         v_floor_id,
            'space_id',         v_space_id,
            'gateway_model_id', v_gateway_model_id,
            'gateway_id',       v_gateway_id,
            'device_model_id',  v_device_model_id,
            'device_category_id', v_device_category_id,
            'device_category_name', v_device_category_name,
            'profile_id',       v_profile_id,
            'profile_code',     v_profile_code,
            'device_id',        v_device_id,
            'device_external_id', v_device_external_id,
            'identifier_type',  v_identifier_type,
            'identifier_value', v_identifier_value,
            'asset_mode',       v_asset_mode,
            'asset_id',         v_asset_id,
            'asset_name',       v_asset_name,
            'relationship_type', v_relationship_type,
            'grafana_org_id',   v_grafana_org_id
        );

    INSERT INTO admin.onboarding_audit
    (
        requested_by,
        request_payload,
        result_payload
    )
    VALUES
    (
        COALESCE(NULLIF(btrim(p_requested_by), ''), current_user),
        p_request,
        v_result
    );

    RETURN v_result;
END;
$function$;

COMMENT ON FUNCTION admin.onboard_energy_asset(JSONB, TEXT) IS
'Atomically executes explicit create-or-select EMS onboarding across organization, site, location, gateway, device, identifier, asset, and asset-device relationship.';

ALTER FUNCTION admin.onboard_energy_asset(JSONB, TEXT)
    OWNER TO ems_admin;

REVOKE ALL
    ON FUNCTION admin.onboard_energy_asset(JSONB, TEXT)
    FROM PUBLIC;

GRANT EXECUTE
    ON FUNCTION admin.onboard_energy_asset(JSONB, TEXT)
    TO ems_app;


-- ====================================================================
-- Historical migration: 84_onboarding_drafts.sql
-- ====================================================================



-- ============================================================================
-- Durable multi-page onboarding drafts
--
-- Each step writes only to this draft record. Production metadata is created
-- atomically later by admin.onboard_energy_asset().
-- ============================================================================

CREATE TABLE IF NOT EXISTS admin.onboarding_drafts
(
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),

    -- Browser-safe opaque identifier used between wizard pages.
    draft_token uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),

    -- Current wizard position.
    current_step text NOT NULL DEFAULT 'organization',

    -- DRAFT, SUBMITTED, CANCELLED, or EXPIRED.
    status text NOT NULL DEFAULT 'DRAFT',

    -- Accumulated validated wizard data.
    payload jsonb NOT NULL DEFAULT '{}'::jsonb,

    requested_by text NOT NULL,

    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),

    -- Prevent abandoned drafts from living forever.
    expires_at timestamptz NOT NULL
        DEFAULT clock_timestamp() + interval '7 days',

    CONSTRAINT onboarding_drafts_current_step_check
        CHECK
        (
            current_step IN
            (
                'organization',
                'site',
                'location',
                'gateway',
                'device',
                'asset',
                'review'
            )
        ),

    CONSTRAINT onboarding_drafts_status_check
        CHECK
        (
            status IN
            (
                'DRAFT',
                'SUBMITTED',
                'CANCELLED',
                'EXPIRED'
            )
        ),

    CONSTRAINT onboarding_drafts_payload_object_check
        CHECK (jsonb_typeof(payload) = 'object')
);

CREATE INDEX IF NOT EXISTS onboarding_drafts_status_expiry_idx
    ON admin.onboarding_drafts
    (
        status,
        expires_at
    );

COMMENT ON TABLE admin.onboarding_drafts IS
    'Durable server-side state for the multi-page EMS onboarding wizard.';

COMMENT ON COLUMN admin.onboarding_drafts.payload IS
    'Validated partial onboarding request accumulated across wizard steps.';


-- ============================================================================
-- Read one active draft
-- ============================================================================

CREATE OR REPLACE FUNCTION admin.get_onboarding_draft(
    p_draft_token uuid
)
RETURNS TABLE
(
    draft_token uuid,
    current_step text,
    status text,
    payload jsonb,
    created_at timestamptz,
    updated_at timestamptz,
    expires_at timestamptz
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = pg_catalog, admin
AS $function$
    SELECT
        draft.draft_token,
        draft.current_step,
        draft.status,
        draft.payload,
        draft.created_at,
        draft.updated_at,
        draft.expires_at
    FROM admin.onboarding_drafts AS draft
    WHERE draft.draft_token = p_draft_token
      AND draft.status = 'DRAFT'
      AND draft.expires_at > clock_timestamp();
$function$;


-- ============================================================================
-- Create or update a draft step
--
-- jsonb_set replaces one top-level wizard module while preserving all other
-- completed modules.
-- ============================================================================

CREATE OR REPLACE FUNCTION admin.save_onboarding_draft_step(
    p_draft_token uuid,
    p_step text,
    p_step_payload jsonb,
    p_next_step text,
    p_requested_by text
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, admin
AS $function$
DECLARE
    v_draft_token uuid;
BEGIN
    IF p_step NOT IN
    (
        'organization',
        'site',
        'location',
        'gateway',
        'device',
        'asset',
        'review'
    ) THEN
        RAISE EXCEPTION 'Unsupported onboarding step: %', p_step;
    END IF;

    IF p_next_step NOT IN
    (
        'organization',
        'site',
        'location',
        'gateway',
        'device',
        'asset',
        'review'
    ) THEN
        RAISE EXCEPTION 'Unsupported next onboarding step: %', p_next_step;
    END IF;

    IF p_step_payload IS NULL
       OR jsonb_typeof(p_step_payload) <> 'object'
    THEN
        RAISE EXCEPTION
            'Onboarding step payload must be a JSON object.';
    END IF;

    IF p_draft_token IS NULL THEN
        INSERT INTO admin.onboarding_drafts
        (
            current_step,
            payload,
            requested_by
        )
        VALUES
        (
            p_next_step,
            jsonb_build_object(p_step, p_step_payload),
            btrim(p_requested_by)
        )
        RETURNING onboarding_drafts.draft_token
        INTO v_draft_token;
    ELSE
        UPDATE admin.onboarding_drafts AS draft
        SET
            payload = jsonb_set(
                draft.payload,
                ARRAY[p_step],
                p_step_payload,
                TRUE
            ),
            current_step = p_next_step,
            requested_by = btrim(p_requested_by),
            updated_at = clock_timestamp(),
            expires_at = clock_timestamp() + interval '7 days'
        WHERE draft.draft_token = p_draft_token
          AND draft.status = 'DRAFT'
          AND draft.expires_at > clock_timestamp()
        RETURNING draft.draft_token
        INTO v_draft_token;

        IF v_draft_token IS NULL THEN
            RAISE EXCEPTION
                'Onboarding draft was not found or has expired.';
        END IF;
    END IF;

    RETURN v_draft_token;
END;
$function$;


-- ============================================================================
-- Least-privilege grants
-- ============================================================================

REVOKE ALL ON TABLE admin.onboarding_drafts FROM PUBLIC;
REVOKE ALL ON FUNCTION admin.get_onboarding_draft(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION admin.save_onboarding_draft_step(
    uuid,
    text,
    jsonb,
    text,
    text
) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION admin.get_onboarding_draft(uuid)
    TO ems_app;

GRANT EXECUTE ON FUNCTION admin.save_onboarding_draft_step(
    uuid,
    text,
    jsonb,
    text,
    text
) TO ems_app;


-- ====================================================================
-- Historical migration: 85_submit_onboarding_draft.sql
-- ====================================================================



-- ============================================================================
-- Finalize one completed onboarding draft atomically.
--
-- Guarantees:
--   1. The draft row is locked against concurrent submissions.
--   2. Only active DRAFT records at the review step may be submitted.
--   3. All required wizard modules must exist.
--   4. device.identifier is promoted to the top-level identifier object
--      expected by admin.onboard_energy_asset().
--   5. Production metadata creation and draft status update occur in the
--      same PostgreSQL transaction.
--   6. A second submission attempt is rejected.
-- ============================================================================

CREATE OR REPLACE FUNCTION admin.submit_onboarding_draft
(
    p_draft_token uuid,
    p_requested_by text DEFAULT current_user
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO pg_catalog, admin
AS $function$
DECLARE
    v_draft_payload jsonb;
    v_device_payload jsonb;
    v_identifier_payload jsonb;
    v_request_payload jsonb;
    v_result jsonb;
    v_requested_by text;
BEGIN
    IF p_draft_token IS NULL THEN
        RAISE EXCEPTION
            'Onboarding draft token is required.';
    END IF;

    v_requested_by :=
        COALESCE(
            NULLIF(btrim(p_requested_by), ''),
            current_user
        );

    --------------------------------------------------------------------------
    -- Lock the draft so two browser requests cannot submit it concurrently.
    --------------------------------------------------------------------------

    SELECT draft.payload
    INTO v_draft_payload
    FROM admin.onboarding_drafts AS draft
    WHERE draft.draft_token = p_draft_token
      AND draft.status = 'DRAFT'
      AND draft.current_step = 'review'
      AND draft.expires_at > clock_timestamp()
    FOR UPDATE;

    IF v_draft_payload IS NULL THEN
        RAISE EXCEPTION
            'Onboarding draft was not found, has expired, is incomplete, or was already submitted.';
    END IF;

    --------------------------------------------------------------------------
    -- Require every wizard module before production execution.
    --------------------------------------------------------------------------

    IF NOT (
        v_draft_payload ? 'organization'
        AND v_draft_payload ? 'site'
        AND v_draft_payload ? 'location'
        AND v_draft_payload ? 'gateway'
        AND v_draft_payload ? 'device'
        AND v_draft_payload ? 'asset'
    ) THEN
        RAISE EXCEPTION
            'Onboarding draft is missing one or more required modules.';
    END IF;

    v_device_payload :=
        COALESCE(
            v_draft_payload -> 'device',
            '{}'::jsonb
        );

    v_identifier_payload :=
        COALESCE(
            v_device_payload -> 'identifier',
            '{}'::jsonb
        );

    IF jsonb_typeof(v_identifier_payload) <> 'object' THEN
        RAISE EXCEPTION
            'Draft device identifier must be a JSON object.';
    END IF;

    --------------------------------------------------------------------------
    -- Build the canonical request expected by admin.onboard_energy_asset().
    --
    -- Remove the nested identifier from device and promote it to:
    --
    --   {
    --     "device": {...},
    --     "identifier": {
    --       "type": "...",
    --       "value": "..."
    --     }
    --   }
    --------------------------------------------------------------------------

    v_request_payload :=
        jsonb_set(
            v_draft_payload,
            '{device}',
            v_device_payload - 'identifier',
            true
        );

    v_request_payload :=
        jsonb_set(
            v_request_payload,
            '{identifier}',
            v_identifier_payload,
            true
        );

    -- Review information is audit metadata, not production onboarding input.
    v_request_payload :=
        v_request_payload - 'review';

    --------------------------------------------------------------------------
    -- Execute the existing production-grade onboarding function.
    --------------------------------------------------------------------------

    v_result :=
        admin.onboard_energy_asset(
            v_request_payload,
            v_requested_by
        );

    --------------------------------------------------------------------------
    -- Mark the draft submitted only after production onboarding succeeds.
    --------------------------------------------------------------------------

    UPDATE admin.onboarding_drafts AS draft
    SET
        status = 'SUBMITTED',
        current_step = 'review',
        payload = jsonb_set(
            draft.payload,
            '{review}',
            jsonb_build_object(
                'submitted_at',
                clock_timestamp(),
                'submitted_by',
                v_requested_by,
                'result',
                v_result
            ),
            true
        ),
        requested_by = v_requested_by,
        updated_at = clock_timestamp()
    WHERE draft.draft_token = p_draft_token
      AND draft.status = 'DRAFT';

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Onboarding draft status changed during submission.';
    END IF;

    RETURN v_result;
END;
$function$;

REVOKE ALL
ON FUNCTION admin.submit_onboarding_draft(uuid, text)
FROM PUBLIC;

GRANT EXECUTE
ON FUNCTION admin.submit_onboarding_draft(uuid, text)
TO ems_app;


-- ====================================================================
-- Historical migration: 86_get_submitted_onboarding_result.sql
-- ====================================================================



-- ============================================================================
-- Read one completed onboarding result.
--
-- This function is intentionally separate from admin.get_onboarding_draft().
-- Draft editing remains restricted to active DRAFT records, while submitted
-- results can be viewed through a read-only result page.
-- ============================================================================

CREATE OR REPLACE FUNCTION admin.get_submitted_onboarding_result
(
    p_draft_token uuid
)
RETURNS TABLE
(
    draft_token uuid,
    status text,
    requested_by text,
    created_at timestamptz,
    submitted_at timestamptz,
    payload jsonb,
    result jsonb
)
LANGUAGE sql
SECURITY DEFINER
SET search_path TO pg_catalog, admin
AS $function$
    SELECT
        draft.draft_token,
        draft.status,
        draft.requested_by,
        draft.created_at,
        NULLIF(
            draft.payload #>> '{review,submitted_at}',
            ''
        )::timestamptz AS submitted_at,
        draft.payload,
        draft.payload #> '{review,result}' AS result
    FROM admin.onboarding_drafts AS draft
    WHERE draft.draft_token = p_draft_token
      AND draft.status = 'SUBMITTED'
      AND draft.payload #> '{review,result}' IS NOT NULL;
$function$;

REVOKE ALL
ON FUNCTION admin.get_submitted_onboarding_result(uuid)
FROM PUBLIC;

GRANT EXECUTE
ON FUNCTION admin.get_submitted_onboarding_result(uuid)
TO ems_app;


-- ====================================================================
-- Historical migration: 87_onboarding_event_audit.sql
-- ====================================================================



-- ============================================================================
-- Append-only onboarding wizard event log.
--
-- This table complements admin.onboarding_audit:
--
--   admin.onboarding_audit
--       Records successful production onboarding requests and results.
--
--   admin.onboarding_event_audit
--       Records wizard lifecycle events such as draft creation, step saves,
--       submission success, and submission failure.
--
-- The application role receives no direct table privileges.
-- All writes occur through SECURITY DEFINER functions.
-- ============================================================================

CREATE TABLE IF NOT EXISTS admin.onboarding_event_audit
(
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),

    draft_token uuid,

    event_type text NOT NULL,

    step_name text,

    actor text NOT NULL,

    event_context jsonb NOT NULL DEFAULT '{}'::jsonb,

    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),

    CONSTRAINT onboarding_event_audit_event_type_check
        CHECK
        (
            event_type IN
            (
                'DRAFT_CREATED',
                'STEP_SAVED',
                'SUBMISSION_SUCCEEDED',
                'SUBMISSION_FAILED'
            )
        ),

    CONSTRAINT onboarding_event_audit_step_name_check
        CHECK
        (
            step_name IS NULL
            OR step_name IN
            (
                'organization',
                'site',
                'location',
                'gateway',
                'device',
                'asset',
                'review'
            )
        ),

    CONSTRAINT onboarding_event_audit_context_object_check
        CHECK
        (
            jsonb_typeof(event_context) = 'object'
        )
);

CREATE INDEX IF NOT EXISTS
    idx_onboarding_event_audit_draft_created
ON admin.onboarding_event_audit
(
    draft_token,
    created_at DESC
);

CREATE INDEX IF NOT EXISTS
    idx_onboarding_event_audit_type_created
ON admin.onboarding_event_audit
(
    event_type,
    created_at DESC
);

-- ============================================================================
-- Controlled append function.
-- ============================================================================

CREATE OR REPLACE FUNCTION admin.log_onboarding_event
(
    p_draft_token uuid,
    p_event_type text,
    p_step_name text,
    p_actor text,
    p_event_context jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO pg_catalog, admin
AS $function$
DECLARE
    v_event_id uuid;
    v_event_type text;
    v_step_name text;
    v_actor text;
    v_context jsonb;
BEGIN
    v_event_type := upper(btrim(p_event_type));
    v_step_name := lower(NULLIF(btrim(p_step_name), ''));
    v_actor := COALESCE(
        NULLIF(btrim(p_actor), ''),
        current_user
    );
    v_context := COALESCE(
        p_event_context,
        '{}'::jsonb
    );

    IF v_event_type NOT IN
    (
        'DRAFT_CREATED',
        'STEP_SAVED',
        'SUBMISSION_SUCCEEDED',
        'SUBMISSION_FAILED'
    ) THEN
        RAISE EXCEPTION
            'Unsupported onboarding event type: %',
            v_event_type;
    END IF;

    IF v_step_name IS NOT NULL
       AND v_step_name NOT IN
       (
           'organization',
           'site',
           'location',
           'gateway',
           'device',
           'asset',
           'review'
       )
    THEN
        RAISE EXCEPTION
            'Unsupported onboarding step name: %',
            v_step_name;
    END IF;

    IF jsonb_typeof(v_context) <> 'object' THEN
        RAISE EXCEPTION
            'Onboarding event context must be a JSON object.';
    END IF;

    INSERT INTO admin.onboarding_event_audit
    (
        draft_token,
        event_type,
        step_name,
        actor,
        event_context
    )
    VALUES
    (
        p_draft_token,
        v_event_type,
        v_step_name,
        v_actor,
        v_context
    )
    RETURNING id
    INTO v_event_id;

    RETURN v_event_id;
END;
$function$;

REVOKE ALL
ON TABLE admin.onboarding_event_audit
FROM PUBLIC;

REVOKE ALL
ON TABLE admin.onboarding_event_audit
FROM ems_app;

REVOKE ALL
ON FUNCTION admin.log_onboarding_event(
    uuid,
    text,
    text,
    text,
    jsonb
)
FROM PUBLIC;

GRANT EXECUTE
ON FUNCTION admin.log_onboarding_event(
    uuid,
    text,
    text,
    text,
    jsonb
)
TO ems_app;

-- ============================================================================
-- Read-only administrative view.
-- The application role is not granted access yet. This will be used by the
-- future onboarding history page after authenticated RBAC is implemented.
-- ============================================================================

CREATE OR REPLACE VIEW admin.v_onboarding_event_audit
AS
SELECT
    event.id,
    event.draft_token,
    event.event_type,
    event.step_name,
    event.actor,
    event.event_context,
    event.created_at
FROM admin.onboarding_event_audit AS event;

REVOKE ALL
ON admin.v_onboarding_event_audit
FROM PUBLIC;


-- ====================================================================
-- Historical migration: 88_audit_draft_step_events.sql
-- ====================================================================



CREATE OR REPLACE FUNCTION admin.save_onboarding_draft_step
(
    p_draft_token uuid,
    p_step text,
    p_step_payload jsonb,
    p_next_step text,
    p_requested_by text
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO pg_catalog, admin
AS $function$
DECLARE
    v_draft_token uuid;
    v_event_type text;
    v_actor text;
BEGIN
    IF p_step NOT IN
    (
        'organization',
        'site',
        'location',
        'gateway',
        'device',
        'asset',
        'review'
    ) THEN
        RAISE EXCEPTION
            'Unsupported onboarding step: %',
            p_step;
    END IF;

    IF p_next_step NOT IN
    (
        'organization',
        'site',
        'location',
        'gateway',
        'device',
        'asset',
        'review'
    ) THEN
        RAISE EXCEPTION
            'Unsupported next onboarding step: %',
            p_next_step;
    END IF;

    IF p_step_payload IS NULL
       OR jsonb_typeof(p_step_payload) <> 'object'
    THEN
        RAISE EXCEPTION
            'Onboarding step payload must be a JSON object.';
    END IF;

    v_actor := COALESCE(
        NULLIF(btrim(p_requested_by), ''),
        current_user
    );

    IF p_draft_token IS NULL THEN
        INSERT INTO admin.onboarding_drafts
        (
            current_step,
            payload,
            requested_by
        )
        VALUES
        (
            p_next_step,
            jsonb_build_object(
                p_step,
                p_step_payload
            ),
            v_actor
        )
        RETURNING onboarding_drafts.draft_token
        INTO v_draft_token;

        v_event_type := 'DRAFT_CREATED';

    ELSE
        UPDATE admin.onboarding_drafts AS draft
        SET
            payload = jsonb_set(
                draft.payload,
                ARRAY[p_step],
                p_step_payload,
                true
            ),
            current_step = p_next_step,
            requested_by = v_actor,
            updated_at = clock_timestamp(),
            expires_at =
                clock_timestamp() + interval '7 days'
        WHERE draft.draft_token = p_draft_token
          AND draft.status = 'DRAFT'
          AND draft.expires_at > clock_timestamp()
        RETURNING draft.draft_token
        INTO v_draft_token;

        IF v_draft_token IS NULL THEN
            RAISE EXCEPTION
                'Onboarding draft was not found or has expired.';
        END IF;

        v_event_type := 'STEP_SAVED';
    END IF;

    PERFORM admin.log_onboarding_event(
        v_draft_token,
        v_event_type,
        p_step,
        v_actor,
        jsonb_build_object(
            'next_step',
            p_next_step,
            'saved_keys',
            COALESCE(
                (
                    SELECT jsonb_agg(key ORDER BY key)
                    FROM jsonb_object_keys(
                        p_step_payload
                    ) AS keys(key)
                ),
                '[]'::jsonb
            )
        )
    );

    RETURN v_draft_token;
END;
$function$;

REVOKE ALL
ON FUNCTION admin.save_onboarding_draft_step(
    uuid,
    text,
    jsonb,
    text,
    text
)
FROM PUBLIC;

GRANT EXECUTE
ON FUNCTION admin.save_onboarding_draft_step(
    uuid,
    text,
    jsonb,
    text,
    text
)
TO ems_app;


-- ====================================================================
-- Historical migration: 89_audit_submission_success.sql
-- ====================================================================



CREATE OR REPLACE FUNCTION admin.submit_onboarding_draft
(
    p_draft_token uuid,
    p_requested_by text DEFAULT current_user
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO pg_catalog, admin
AS $function$
DECLARE
    v_draft_payload jsonb;
    v_device_payload jsonb;
    v_identifier_payload jsonb;
    v_request_payload jsonb;
    v_result jsonb;
    v_requested_by text;
BEGIN
    IF p_draft_token IS NULL THEN
        RAISE EXCEPTION
            'Onboarding draft token is required.';
    END IF;

    v_requested_by :=
        COALESCE(
            NULLIF(btrim(p_requested_by), ''),
            current_user
        );

    SELECT draft.payload
    INTO v_draft_payload
    FROM admin.onboarding_drafts AS draft
    WHERE draft.draft_token = p_draft_token
      AND draft.status = 'DRAFT'
      AND draft.current_step = 'review'
      AND draft.expires_at > clock_timestamp()
    FOR UPDATE;

    IF v_draft_payload IS NULL THEN
        RAISE EXCEPTION
            'Onboarding draft was not found, has expired, is incomplete, or was already submitted.';
    END IF;

    IF NOT (
        v_draft_payload ? 'organization'
        AND v_draft_payload ? 'site'
        AND v_draft_payload ? 'location'
        AND v_draft_payload ? 'gateway'
        AND v_draft_payload ? 'device'
        AND v_draft_payload ? 'asset'
    ) THEN
        RAISE EXCEPTION
            'Onboarding draft is missing one or more required modules.';
    END IF;

    v_device_payload :=
        COALESCE(
            v_draft_payload -> 'device',
            '{}'::jsonb
        );

    v_identifier_payload :=
        COALESCE(
            v_device_payload -> 'identifier',
            '{}'::jsonb
        );

    IF jsonb_typeof(v_identifier_payload) <> 'object' THEN
        RAISE EXCEPTION
            'Draft device identifier must be a JSON object.';
    END IF;

    v_request_payload :=
        jsonb_set(
            v_draft_payload,
            '{device}',
            v_device_payload - 'identifier',
            true
        );

    v_request_payload :=
        jsonb_set(
            v_request_payload,
            '{identifier}',
            v_identifier_payload,
            true
        );

    v_request_payload :=
        v_request_payload - 'review';

    v_result :=
        admin.onboard_energy_asset(
            v_request_payload,
            v_requested_by
        );

    UPDATE admin.onboarding_drafts AS draft
    SET
        status = 'SUBMITTED',
        current_step = 'review',
        payload = jsonb_set(
            draft.payload,
            '{review}',
            jsonb_build_object(
                'submitted_at',
                clock_timestamp(),
                'submitted_by',
                v_requested_by,
                'result',
                v_result
            ),
            true
        ),
        requested_by = v_requested_by,
        updated_at = clock_timestamp()
    WHERE draft.draft_token = p_draft_token
      AND draft.status = 'DRAFT';

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Onboarding draft status changed during submission.';
    END IF;

    PERFORM admin.log_onboarding_event(
        p_draft_token,
        'SUBMISSION_SUCCEEDED',
        'review',
        v_requested_by,
        jsonb_build_object(
            'organization_id',
            v_result ->> 'organization_id',
            'site_id',
            v_result ->> 'site_id',
            'gateway_id',
            v_result ->> 'gateway_id',
            'device_id',
            v_result ->> 'device_id',
            'asset_id',
            v_result ->> 'asset_id',
            'relationship_type',
            v_result ->> 'relationship_type'
        )
    );

    RETURN v_result;
END;
$function$;

REVOKE ALL
ON FUNCTION admin.submit_onboarding_draft(uuid, text)
FROM PUBLIC;

GRANT EXECUTE
ON FUNCTION admin.submit_onboarding_draft(uuid, text)
TO ems_app;


