-- ====================================================================
-- Historical migration: 91_portal_users.sql
-- ====================================================================



-- ============================================================================
-- Portal authentication identities
--
-- This table stores administrative portal users separately from PostgreSQL
-- database roles. A portal user represents a human identity. The FastAPI
-- service continues to connect to PostgreSQL using the restricted ems_app
-- database role.
--
-- Passwords must never be stored directly. password_hash contains an Argon2id
-- encoded hash generated and verified by the application.
-- ============================================================================

CREATE TABLE IF NOT EXISTS admin.portal_users
(
    portal_user_id bigint
        GENERATED ALWAYS AS IDENTITY
        PRIMARY KEY,

    username text
        NOT NULL,

    display_name text
        NOT NULL,

    email text,

    password_hash text
        NOT NULL,

    role_code text
        NOT NULL
        DEFAULT 'OPERATOR',

    is_active boolean
        NOT NULL
        DEFAULT true,

    failed_login_count integer
        NOT NULL
        DEFAULT 0,

    locked_until timestamptz,

    last_login_at timestamptz,

    password_changed_at timestamptz
        NOT NULL
        DEFAULT clock_timestamp(),

    created_at timestamptz
        NOT NULL
        DEFAULT clock_timestamp(),

    updated_at timestamptz
        NOT NULL
        DEFAULT clock_timestamp(),

    created_by text
        NOT NULL,

    CONSTRAINT portal_users_username_not_blank
        CHECK (btrim(username) <> ''),

    CONSTRAINT portal_users_display_name_not_blank
        CHECK (btrim(display_name) <> ''),

    CONSTRAINT portal_users_username_normalized
        CHECK (username = lower(btrim(username))),

    CONSTRAINT portal_users_role_code_valid
        CHECK (
            role_code IN (
                'SUPER_ADMIN',
                'OPERATOR',
                'VIEWER'
            )
        ),

    CONSTRAINT portal_users_failed_login_count_valid
        CHECK (failed_login_count >= 0),

    CONSTRAINT portal_users_email_not_blank
        CHECK (
            email IS NULL
            OR btrim(email) <> ''
        )
);

-- Username matching is case-insensitive at the boundary because usernames are
-- stored normalized to lowercase.
CREATE UNIQUE INDEX IF NOT EXISTS ux_portal_users_username
    ON admin.portal_users (username);

CREATE UNIQUE INDEX IF NOT EXISTS ux_portal_users_email
    ON admin.portal_users (lower(email))
    WHERE email IS NOT NULL;

COMMENT ON TABLE admin.portal_users IS
    'Human identities authorized to use the EMS administration portal.';

COMMENT ON COLUMN admin.portal_users.password_hash IS
    'Argon2id encoded password hash. Plaintext passwords must never be stored.';

COMMENT ON COLUMN admin.portal_users.role_code IS
    'Portal authorization role: SUPER_ADMIN, OPERATOR, or VIEWER.';

COMMENT ON COLUMN admin.portal_users.locked_until IS
    'Temporary authentication lockout expiration timestamp.';

-- ============================================================================
-- Authentication lookup
--
-- SECURITY DEFINER allows ems_app to request one authentication record without
-- receiving direct SELECT access to the portal_users table.
--
-- The function intentionally returns the password hash because FastAPI must
-- verify the submitted password with Argon2. It returns only one normalized
-- username match and exposes no list operation.
-- ============================================================================

CREATE OR REPLACE FUNCTION admin.get_portal_user_for_authentication
(
    p_username text
)
RETURNS TABLE
(
    portal_user_id bigint,
    username text,
    display_name text,
    password_hash text,
    role_code text,
    is_active boolean,
    failed_login_count integer,
    locked_until timestamptz
)
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path TO pg_catalog, admin
AS $function$
    SELECT
        portal_user.portal_user_id,
        portal_user.username,
        portal_user.display_name,
        portal_user.password_hash,
        portal_user.role_code,
        portal_user.is_active,
        portal_user.failed_login_count,
        portal_user.locked_until
    FROM admin.portal_users AS portal_user
    WHERE portal_user.username =
        lower(btrim(p_username))
    LIMIT 1;
$function$;

-- ============================================================================
-- Successful-login recorder
-- ============================================================================

CREATE OR REPLACE FUNCTION admin.record_portal_login_success
(
    p_portal_user_id bigint
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO pg_catalog, admin
AS $function$
BEGIN
    UPDATE admin.portal_users AS portal_user
    SET
        failed_login_count = 0,
        locked_until = NULL,
        last_login_at = clock_timestamp(),
        updated_at = clock_timestamp()
    WHERE portal_user.portal_user_id = p_portal_user_id
      AND portal_user.is_active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Active portal user was not found.';
    END IF;
END;
$function$;

-- ============================================================================
-- Failed-login recorder
--
-- Five consecutive failed attempts cause a fifteen-minute lockout.
-- Successful authentication resets the counter through
-- record_portal_login_success().
-- ============================================================================

CREATE OR REPLACE FUNCTION admin.record_portal_login_failure
(
    p_portal_user_id bigint
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO pg_catalog, admin
AS $function$
BEGIN
    UPDATE admin.portal_users AS portal_user
    SET
        failed_login_count =
            portal_user.failed_login_count + 1,

        locked_until =
            CASE
                WHEN portal_user.failed_login_count + 1 >= 5
                THEN clock_timestamp() + interval '15 minutes'
                ELSE portal_user.locked_until
            END,

        updated_at = clock_timestamp()
    WHERE portal_user.portal_user_id = p_portal_user_id
      AND portal_user.is_active = true;

    -- Do not reveal whether a supplied username exists to the HTTP client.
    -- The application will always return the same generic login error.
END;
$function$;

-- ============================================================================
-- Permission boundary
-- ============================================================================

REVOKE ALL
ON TABLE admin.portal_users
FROM PUBLIC;

REVOKE ALL
ON TABLE admin.portal_users
FROM ems_app;

REVOKE ALL
ON SEQUENCE admin.portal_users_portal_user_id_seq
FROM PUBLIC;

REVOKE ALL
ON SEQUENCE admin.portal_users_portal_user_id_seq
FROM ems_app;

REVOKE ALL
ON FUNCTION admin.get_portal_user_for_authentication(text)
FROM PUBLIC;

REVOKE ALL
ON FUNCTION admin.record_portal_login_success(bigint)
FROM PUBLIC;

REVOKE ALL
ON FUNCTION admin.record_portal_login_failure(bigint)
FROM PUBLIC;

GRANT EXECUTE
ON FUNCTION admin.get_portal_user_for_authentication(text)
TO ems_app;

GRANT EXECUTE
ON FUNCTION admin.record_portal_login_success(bigint)
TO ems_app;

GRANT EXECUTE
ON FUNCTION admin.record_portal_login_failure(bigint)
TO ems_app;


-- ====================================================================
-- Historical migration: 92_onboarding_draft_ownership.sql
-- ====================================================================



-- ============================================================================
-- Stable onboarding draft ownership
--
-- requested_by currently stores a username string and has historically been
-- updated when a draft is saved. It is useful as an audit-friendly actor
-- snapshot, but it is not a stable ownership key because usernames can change.
--
-- owner_portal_user_id identifies the human portal account that created and
-- owns the draft. Existing historical and test drafts may remain NULL when no
-- matching portal account exists.
-- ============================================================================

ALTER TABLE admin.onboarding_drafts
ADD COLUMN IF NOT EXISTS owner_portal_user_id bigint;

COMMENT ON COLUMN admin.onboarding_drafts.owner_portal_user_id IS
    'Stable portal-user identity that owns the onboarding draft. '
    'NULL is permitted for historical drafts created before authenticated '
    'ownership enforcement or when the original portal account was deleted.';

-- Backfill drafts where the recorded username still matches an existing portal
-- account. Historical actors such as portal-v0.3, manual-test, and deleted test
-- users intentionally remain NULL.
UPDATE admin.onboarding_drafts AS draft
SET owner_portal_user_id = portal_user.portal_user_id
FROM admin.portal_users AS portal_user
WHERE draft.owner_portal_user_id IS NULL
  AND lower(btrim(draft.requested_by)) = portal_user.username;

-- Add the foreign key only when it does not already exist. ON DELETE SET NULL
-- preserves draft and audit history if a portal account is later removed.
DO $block$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname =
            'onboarding_drafts_owner_portal_user_id_fkey'
          AND conrelid =
            'admin.onboarding_drafts'::regclass
    ) THEN
        ALTER TABLE admin.onboarding_drafts
        ADD CONSTRAINT onboarding_drafts_owner_portal_user_id_fkey
        FOREIGN KEY (owner_portal_user_id)
        REFERENCES admin.portal_users(portal_user_id)
        ON DELETE SET NULL;
    END IF;
END;
$block$;

-- Supports ownership-filtered draft lookup and future draft listing.
CREATE INDEX IF NOT EXISTS ix_onboarding_drafts_owner_status_updated
ON admin.onboarding_drafts
(
    owner_portal_user_id,
    status,
    updated_at DESC
);


-- ====================================================================
-- Historical migration: 93_ownership_aware_draft_reads.sql
-- ====================================================================



-- ============================================================================
-- Ownership-aware active draft lookup
--
-- The caller supplies the authenticated portal user ID and role captured in
-- the signed session. The function independently verifies both against the
-- current portal_users row. This causes deactivated accounts and stale role
-- sessions to fail closed.
--
-- SUPER_ADMIN may access all drafts. Other authenticated roles may access only
-- drafts whose stable owner_portal_user_id matches their portal identity.
-- ============================================================================

CREATE OR REPLACE FUNCTION admin.get_onboarding_draft
(
    p_draft_token uuid,
    p_portal_user_id bigint,
    p_role_code text
)
RETURNS TABLE
(
    draft_token uuid,
    current_step text,
    status text,
    payload jsonb,
    requested_by text,
    owner_portal_user_id bigint,
    created_at timestamptz,
    updated_at timestamptz,
    expires_at timestamptz
)
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path TO pg_catalog, admin
AS $function$
    SELECT
        draft.draft_token,
        draft.current_step,
        draft.status,
        draft.payload,
        draft.requested_by,
        draft.owner_portal_user_id,
        draft.created_at,
        draft.updated_at,
        draft.expires_at
    FROM admin.onboarding_drafts AS draft
    JOIN admin.portal_users AS portal_user
      ON portal_user.portal_user_id = p_portal_user_id
     AND portal_user.is_active = true
     AND portal_user.role_code = p_role_code
    WHERE draft.draft_token = p_draft_token
      AND draft.status = 'DRAFT'
      AND draft.expires_at > clock_timestamp()
      AND (
          portal_user.role_code = 'SUPER_ADMIN'
          OR draft.owner_portal_user_id =
             portal_user.portal_user_id
      );
$function$;


-- ============================================================================
-- Ownership-aware submitted result lookup
--
-- Submitted results follow the same ownership rule. This prevents an operator
-- from retrieving another operator's immutable result using only its UUID.
-- ============================================================================

CREATE OR REPLACE FUNCTION admin.get_submitted_onboarding_result
(
    p_draft_token uuid,
    p_portal_user_id bigint,
    p_role_code text
)
RETURNS TABLE
(
    draft_token uuid,
    status text,
    requested_by text,
    owner_portal_user_id bigint,
    created_at timestamptz,
    submitted_at timestamptz,
    payload jsonb,
    result jsonb
)
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path TO pg_catalog, admin
AS $function$
    SELECT
        draft.draft_token,
        draft.status,
        draft.requested_by,
        draft.owner_portal_user_id,
        draft.created_at,
        NULLIF(
            draft.payload #>> '{review,submitted_at}',
            ''
        )::timestamptz AS submitted_at,
        draft.payload,
        draft.payload #> '{review,result}' AS result
    FROM admin.onboarding_drafts AS draft
    JOIN admin.portal_users AS portal_user
      ON portal_user.portal_user_id = p_portal_user_id
     AND portal_user.is_active = true
     AND portal_user.role_code = p_role_code
    WHERE draft.draft_token = p_draft_token
      AND draft.status = 'SUBMITTED'
      AND draft.payload #> '{review,result}' IS NOT NULL
      AND (
          portal_user.role_code = 'SUPER_ADMIN'
          OR draft.owner_portal_user_id =
             portal_user.portal_user_id
      );
$function$;


-- ============================================================================
-- Permission boundary
--
-- The legacy one-argument functions remain temporarily executable while the
-- FastAPI repository is migrated. They will be revoked after cutover.
-- ============================================================================

REVOKE ALL
ON FUNCTION admin.get_onboarding_draft(
    uuid,
    bigint,
    text
)
FROM PUBLIC;

REVOKE ALL
ON FUNCTION admin.get_submitted_onboarding_result(
    uuid,
    bigint,
    text
)
FROM PUBLIC;

GRANT EXECUTE
ON FUNCTION admin.get_onboarding_draft(
    uuid,
    bigint,
    text
)
TO ems_app;

GRANT EXECUTE
ON FUNCTION admin.get_submitted_onboarding_result(
    uuid,
    bigint,
    text
)
TO ems_app;


