(
    audit_id UUID
        PRIMARY KEY
        DEFAULT gen_random_uuid(),

    actor_portal_user_id BIGINT
        NOT NULL,

    target_portal_user_id BIGINT,

    organization_id UUID,

    event_type TEXT
        NOT NULL,

    previous_role_code TEXT,

