            'parent_asset_id', p_parent_asset_id,
            'building_id', p_building_id,
            'floor_id', p_floor_id,
            'space_id', p_space_id,
            'name', v_name,
            'lifecycle_status', v_lifecycle,
            'metering_requirement', v_metering
        ),
