ALTER FUNCTION admin.commission_asset(BIGINT, UUID) OWNER TO ems_admin;
REVOKE ALL ON FUNCTION admin.list_accessible_commissioning_readiness(BIGINT, TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION admin.commission_asset(BIGINT, UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION admin.list_accessible_commissioning_readiness(BIGINT, TEXT) TO ems_app;
GRANT EXECUTE ON FUNCTION admin.commission_asset(BIGINT, UUID) TO ems_app;


