    OWNER TO ems_admin;

REVOKE ALL ON FUNCTION admin.submit_onboarding_draft(
    uuid, bigint, text, text
) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION admin.submit_onboarding_draft(
    uuid, bigint, text, text
) TO ems_app;


