CREATE OR REPLACE FUNCTION admin.validate_onboarding_field(
    p_actor_portal_user_id bigint,
    p_draft_token uuid,
    p_step text,
    p_field text,
    p_value text,
    p_form jsonb DEFAULT '{}'::jsonb
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, admin, metadata, config
AS $$
DECLARE
    v_actor admin.portal_users%ROWTYPE;
    v_payload jsonb := '{}'::jsonb;
    v_org_id uuid;
    v_site_id uuid;
    v_gateway_id uuid;
    v_building_id uuid;
    v_floor_id uuid;
    v_id uuid;
    v_exists boolean;
    v_category uuid;
    v_org_code text;
    v_org_name text;
    v_site_code text;
    v_site_name text;
    v_gateway_external_id text;
BEGIN
    SELECT * INTO v_actor
    FROM admin.portal_users
    WHERE portal_user_id = p_actor_portal_user_id AND is_active;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('valid',false,'field',p_field,'code','NOT_AUTHORIZED','message','Your session is no longer authorized.');
    END IF;

    IF p_draft_token IS NOT NULL THEN
        SELECT payload INTO v_payload
        FROM admin.onboarding_drafts
        WHERE draft_token = p_draft_token
          AND owner_portal_user_id = p_actor_portal_user_id
          AND status = 'DRAFT';
        IF NOT FOUND THEN
            RETURN jsonb_build_object('valid',false,'field',p_field,'code','DRAFT_NOT_FOUND','message','The onboarding draft is no longer available.');
        END IF;
    END IF;

    BEGIN
        v_org_id := coalesce(
            nullif(v_payload#>>'{organization,existing_organization_id}','')::uuid,
            nullif(p_form->>'existing_organization_id','')::uuid
        );
        v_site_id := coalesce(
            nullif(v_payload#>>'{site,existing_site_id}','')::uuid,
            nullif(p_form->>'existing_site_id','')::uuid
        );
        v_gateway_id := coalesce(
            nullif(v_payload#>>'{gateway,existing_gateway_id}','')::uuid,
            nullif(p_form->>'existing_gateway_id','')::uuid
        );
    EXCEPTION WHEN invalid_text_representation THEN
        RETURN jsonb_build_object('valid',false,'field',p_field,'code','INVALID_SELECTION','message','Select a valid record.');
    END;

    -- Resolve CREATE_NEW parent scopes against existing canonical rows solely
    -- for duplicate detection. This never converts CREATE_NEW into USE_EXISTING.
    v_org_code := upper(nullif(btrim(coalesce(p_form->>'organization_code', v_payload#>>'{organization,code}')),''));
    v_org_name := lower(nullif(btrim(coalesce(p_form->>'organization_name', v_payload#>>'{organization,name}')),''));
    IF v_org_id IS NULL THEN
        SELECT o.id INTO v_org_id
        FROM metadata.organizations o
        WHERE (v_org_code IS NOT NULL AND upper(btrim(o.code)) = v_org_code)
           OR (v_org_name IS NOT NULL AND lower(btrim(o.name)) = v_org_name)
        ORDER BY CASE WHEN v_org_code IS NOT NULL AND upper(btrim(o.code)) = v_org_code THEN 0 ELSE 1 END, o.created_at
        LIMIT 1;
    END IF;

    IF v_actor.role_code <> 'PLATFORM_ADMIN' AND v_org_id IS DISTINCT FROM v_actor.organization_id THEN
        v_org_id := v_actor.organization_id;
    END IF;

    v_site_code := upper(nullif(btrim(coalesce(p_form->>'site_code', v_payload#>>'{site,code}')),''));
    v_site_name := lower(nullif(btrim(coalesce(p_form->>'site_name', v_payload#>>'{site,name}')),''));
    IF v_site_id IS NULL AND v_org_id IS NOT NULL THEN
        SELECT s.id INTO v_site_id
        FROM metadata.sites s
        WHERE s.organization_id = v_org_id
          AND ((v_site_code IS NOT NULL AND upper(btrim(s.code)) = v_site_code)
            OR (v_site_name IS NOT NULL AND lower(btrim(s.name)) = v_site_name))
        ORDER BY CASE WHEN v_site_code IS NOT NULL AND upper(btrim(s.code)) = v_site_code THEN 0 ELSE 1 END, s.created_at
        LIMIT 1;
    END IF;

    v_gateway_external_id := upper(nullif(btrim(coalesce(p_form->>'gateway_external_id', v_payload#>>'{gateway,external_id}')),''));
    IF v_gateway_id IS NULL AND v_org_id IS NOT NULL AND v_gateway_external_id IS NOT NULL THEN
        SELECT g.id INTO v_gateway_id
        FROM metadata.gateways g
        WHERE g.organization_id = v_org_id
          AND upper(btrim(g.external_id)) = v_gateway_external_id
        ORDER BY g.created_at
        LIMIT 1;
    END IF;

    IF p_field IN ('organization_name','site_name','building_name','floor_name','space_name','gateway_name','device_name','asset_name')
       AND btrim(coalesce(p_value,'')) = '' THEN
        RETURN jsonb_build_object('valid',false,'field',p_field,'code','REQUIRED','message','This field is required.');
    END IF;

    IF p_field = 'existing_organization_id' THEN
        BEGIN v_id := p_value::uuid; EXCEPTION WHEN invalid_text_representation THEN v_id := NULL; END;
        SELECT EXISTS(SELECT 1 FROM metadata.organizations o WHERE o.id=v_id AND o.is_active AND (v_actor.role_code='PLATFORM_ADMIN' OR v_actor.organization_id=o.id)) INTO v_exists;
        IF NOT v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','INVALID_ORGANIZATION','message','Select an active organization within your access scope.'); END IF;
    ELSIF p_field = 'organization_code' THEN
        SELECT EXISTS(SELECT 1 FROM metadata.organizations o WHERE upper(btrim(o.code))=upper(btrim(p_value))) INTO v_exists;
        IF v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','DUPLICATE_CODE','message','This organization code already exists. Choose Use existing organization.'); END IF;
    ELSIF p_field = 'organization_name' THEN
        SELECT EXISTS(SELECT 1 FROM metadata.organizations o WHERE lower(btrim(o.name))=lower(btrim(p_value))) INTO v_exists;
        IF v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','DUPLICATE_NAME','message','This organization name already exists. Choose Use existing organization.'); END IF;
    ELSIF p_field = 'existing_site_id' THEN
        BEGIN v_id := p_value::uuid; EXCEPTION WHEN invalid_text_representation THEN v_id := NULL; END;
        SELECT EXISTS(SELECT 1 FROM metadata.sites s WHERE s.id=v_id AND s.organization_id=v_org_id AND s.is_active) INTO v_exists;
        IF NOT v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','INVALID_SITE','message','Select an active site belonging to the chosen organization.'); END IF;
    ELSIF p_field = 'site_code' AND v_org_id IS NOT NULL THEN
        SELECT EXISTS(SELECT 1 FROM metadata.sites s WHERE s.organization_id=v_org_id AND upper(btrim(s.code))=upper(btrim(p_value))) INTO v_exists;
        IF v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','DUPLICATE_CODE','message','This site code already exists. Choose Use existing site.'); END IF;
    ELSIF p_field = 'site_name' AND v_org_id IS NOT NULL THEN
        SELECT EXISTS(SELECT 1 FROM metadata.sites s WHERE s.organization_id=v_org_id AND lower(btrim(s.name))=lower(btrim(p_value))) INTO v_exists;
        IF v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','DUPLICATE_NAME','message','This site name already exists. Choose Use existing site.'); END IF;
    ELSIF p_field = 'existing_space_id' THEN
        BEGIN v_id := p_value::uuid; EXCEPTION WHEN invalid_text_representation THEN v_id := NULL; END;
        SELECT EXISTS(
            SELECT 1 FROM metadata.spaces sp
            JOIN metadata.floors f ON f.id=sp.floor_id
            JOIN metadata.buildings b ON b.id=f.building_id
            WHERE sp.id=v_id AND sp.organization_id=v_org_id AND b.site_id=v_site_id
        ) INTO v_exists;
        IF NOT v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','INVALID_LOCATION','message','Select a space belonging to the chosen site.'); END IF;
    ELSIF p_field = 'building_code' AND v_site_id IS NOT NULL THEN
        SELECT EXISTS(SELECT 1 FROM metadata.buildings b WHERE b.site_id=v_site_id AND upper(btrim(b.code))=upper(btrim(p_value))) INTO v_exists;
        IF v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','DUPLICATE_CODE','message','This building code already exists in the selected site.'); END IF;
    ELSIF p_field = 'floor_code' AND v_site_id IS NOT NULL THEN
        SELECT b.id INTO v_building_id FROM metadata.buildings b WHERE b.site_id=v_site_id AND upper(btrim(b.code))=upper(btrim(coalesce(p_form->>'building_code',''))) LIMIT 1;
        IF v_building_id IS NOT NULL THEN
            SELECT EXISTS(SELECT 1 FROM metadata.floors f WHERE f.building_id=v_building_id AND upper(btrim(f.code))=upper(btrim(p_value))) INTO v_exists;
            IF v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','DUPLICATE_CODE','message','This floor code already exists in the selected building.'); END IF;
        END IF;
    ELSIF p_field = 'space_code' AND v_site_id IS NOT NULL THEN
        SELECT b.id INTO v_building_id FROM metadata.buildings b WHERE b.site_id=v_site_id AND upper(btrim(b.code))=upper(btrim(coalesce(p_form->>'building_code',''))) LIMIT 1;
        SELECT f.id INTO v_floor_id FROM metadata.floors f WHERE f.building_id=v_building_id AND upper(btrim(f.code))=upper(btrim(coalesce(p_form->>'floor_code',''))) LIMIT 1;
        IF v_floor_id IS NOT NULL THEN
            SELECT EXISTS(SELECT 1 FROM metadata.spaces sp WHERE sp.floor_id=v_floor_id AND upper(btrim(sp.code))=upper(btrim(p_value))) INTO v_exists;
            IF v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','DUPLICATE_CODE','message','This space code already exists on the selected floor.'); END IF;
        END IF;
    ELSIF p_field = 'gateway_external_id' THEN
        SELECT EXISTS(SELECT 1 FROM metadata.gateways g WHERE (v_org_id IS NULL OR g.organization_id=v_org_id) AND upper(btrim(g.external_id))=upper(btrim(p_value))) INTO v_exists;
        IF v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','DUPLICATE_EXTERNAL_ID','message','This gateway external ID already exists. Choose Use existing gateway.'); END IF;
    ELSIF p_field = 'existing_gateway_id' THEN
        BEGIN v_id := p_value::uuid; EXCEPTION WHEN invalid_text_representation THEN v_id := NULL; END;
        SELECT EXISTS(SELECT 1 FROM metadata.gateways g WHERE g.id=v_id AND g.organization_id=v_org_id AND g.site_id=v_site_id AND g.lifecycle_status NOT IN ('INACTIVE','DECOMMISSIONED')) INTO v_exists;
        IF NOT v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','INVALID_GATEWAY','message','Select an active gateway belonging to the chosen site.'); END IF;
    ELSIF p_field = 'device_external_id' THEN
        SELECT EXISTS(SELECT 1 FROM metadata.devices d WHERE (v_org_id IS NULL OR d.organization_id=v_org_id) AND upper(btrim(d.external_id))=upper(btrim(p_value))) INTO v_exists;
        IF v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','DUPLICATE_EXTERNAL_ID','message','This device external ID already exists. Choose Use existing device.'); END IF;
    ELSIF p_field IN ('new_identifier_value', 'identifier_value') THEN
        SELECT EXISTS(SELECT 1 FROM metadata.device_identifiers di WHERE upper(di.identifier_type)=upper(coalesce(p_form->>'identifier_type','MQTT_UID')) AND (CASE WHEN upper(coalesce(p_form->>'identifier_type','MQTT_UID'))='MQTT_UID' THEN lower(di.identifier_value) ELSE di.identifier_value END)=(CASE WHEN upper(coalesce(p_form->>'identifier_type','MQTT_UID'))='MQTT_UID' THEN lower(btrim(p_value)) ELSE btrim(p_value) END)) INTO v_exists;
        IF v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','DUPLICATE_IDENTIFIER','message','This device identifier already exists. Choose Use existing device.'); END IF;
    ELSIF p_field = 'existing_device_id' THEN
        BEGIN v_id := p_value::uuid; EXCEPTION WHEN invalid_text_representation THEN v_id := NULL; END;
        SELECT EXISTS(SELECT 1 FROM metadata.devices d WHERE d.id=v_id AND d.organization_id=v_org_id AND d.gateway_id=v_gateway_id AND d.lifecycle_status NOT IN ('INACTIVE','DECOMMISSIONED')) INTO v_exists;
        IF NOT v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','INVALID_DEVICE','message','Select an active device belonging to the chosen gateway.'); END IF;
    ELSIF p_field = 'profile_code' THEN
        BEGIN v_category := nullif(p_form->>'device_category_id','')::uuid; EXCEPTION WHEN invalid_text_representation THEN v_category := NULL; END;
        SELECT EXISTS(SELECT 1 FROM admin.v_active_device_profiles p WHERE p.profile_code=p_value AND (v_category IS NULL OR v_category=ANY(p.device_category_ids))) INTO v_exists;
        IF NOT v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','INCOMPATIBLE_PROFILE','message','Choose a profile compatible with the selected device category.'); END IF;
    ELSIF p_field = 'existing_asset_id' THEN
        BEGIN v_id := p_value::uuid; EXCEPTION WHEN invalid_text_representation THEN v_id := NULL; END;
        SELECT EXISTS(SELECT 1 FROM metadata.assets a WHERE a.id=v_id AND a.organization_id=v_org_id AND a.site_id=v_site_id AND lower(coalesce(a.status,'active'))='active') INTO v_exists;
        IF NOT v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','INVALID_ASSET','message','Select an active asset belonging to the chosen site.'); END IF;
    ELSIF p_field = 'asset_name' AND v_org_id IS NOT NULL AND v_site_id IS NOT NULL THEN
        SELECT EXISTS(SELECT 1 FROM metadata.assets a WHERE a.organization_id=v_org_id AND a.site_id=v_site_id AND a.parent_asset_id IS NULL AND lower(btrim(a.name))=lower(btrim(p_value))) INTO v_exists;
        IF v_exists THEN RETURN jsonb_build_object('valid',false,'field',p_field,'code','DUPLICATE_NAME','message','This asset already exists in the selected site. Choose Use existing asset.'); END IF;
    END IF;

    RETURN jsonb_build_object('valid',true,'field',p_field,'code','OK','message','');
END;
$$;

ALTER FUNCTION admin.validate_onboarding_field(bigint,uuid,text,text,text,jsonb) OWNER TO ems_admin;
REVOKE ALL ON FUNCTION admin.validate_onboarding_field(bigint,uuid,text,text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION admin.validate_onboarding_field(bigint,uuid,text,text,text,jsonb) TO ems_app;


-- ====================================================================
-- Historical migration: 140_fix_onboarding_asset_location_hierarchy.sql
-- ====================================================================

-- Migration 140
-- Preserve the complete physical location hierarchy during asset onboarding.
--
-- A selected or newly created space requires its matching floor and building.
-- The previous onboarding writer passed only space_id to metadata.assets.


CREATE OR REPLACE FUNCTION admin.onboard_energy_asset_legacy_upsert(p_request jsonb, p_requested_by text DEFAULT CURRENT_USER)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'admin', 'metadata', 'config'
AS $function$
DECLARE
    v_organization_mode        TEXT;
    v_existing_organization_id UUID;
    v_organization_name        TEXT;
    v_organization_code        TEXT;
    v_organization_description TEXT;

    v_site_mode                TEXT;
    v_existing_site_id         UUID;
    v_site_name                TEXT;
    v_site_code                TEXT;
    v_site_timezone            TEXT;
    v_site_address             JSONB;

    v_location_mode            TEXT;
    v_existing_space_id        UUID;

    v_building_name            TEXT;
    v_building_code            TEXT;
    v_building_id              UUID;

    v_floor_name               TEXT;
    v_floor_code               TEXT;
    v_floor_id                 UUID;

    v_space_name               TEXT;
    v_space_code               TEXT;
    v_space_id                 UUID;

    v_gateway_mode             TEXT;
    v_existing_gateway_id      UUID;
    v_gateway_name             TEXT;
    v_gateway_external_id      TEXT;
    v_gateway_vendor           TEXT;
    v_gateway_model            TEXT;
    v_gateway_protocol         TEXT;

    v_device_mode              TEXT;
    v_existing_device_id       UUID;
    v_device_name              TEXT;
    v_device_external_id       TEXT;
    v_device_model_vendor      TEXT;
    v_device_model             TEXT;

    -- device_type is retained temporarily for backward compatibility.
    v_device_type              TEXT;
    v_device_category_id       UUID;
    v_device_category_name     TEXT;
    v_existing_model_category_id UUID;

    v_device_firmware_version  TEXT;
    v_device_protocol          TEXT;
    v_profile_code             TEXT;

    v_identifier_type          TEXT;
    v_identifier_value         TEXT;

    v_asset_mode               TEXT;
    v_existing_asset_id        UUID;
    v_asset_name               TEXT;
    v_asset_type_id            UUID;
    v_relationship_type        TEXT;
    v_asset_metadata           JSONB;

    v_grafana_org_id           BIGINT;

    v_organization_id          UUID;
    v_site_id                  UUID;
    v_gateway_model_id         UUID;
    v_gateway_id               UUID;
    v_device_model_id          UUID;
    v_profile_id               UUID;
    v_device_id                UUID;
    v_asset_id                 UUID;

    v_existing_identifier_device_id UUID;
    v_existing_primary_asset_id     UUID;
    v_existing_grafana_org_id       BIGINT;
    v_existing_grafana_org_owner    UUID;

    v_result                    JSONB;
BEGIN
    --------------------------------------------------------------------------
    -- Validate request container.
    --------------------------------------------------------------------------

    IF p_request IS NULL
       OR jsonb_typeof(p_request) <> 'object'
    THEN
        RAISE EXCEPTION
            'Onboarding request must be a JSON object';
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize organization fields.
    --------------------------------------------------------------------------

    v_organization_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(
                    btrim(
                        p_request #>> '{organization,mode}'
                    ),
                    ''
                ),
                'CREATE_NEW'
            )
        );

    IF v_organization_mode NOT IN
    (
        'CREATE_NEW',
        'USE_EXISTING'
    )
    THEN
        RAISE EXCEPTION
            'organization.mode must be CREATE_NEW or USE_EXISTING';
    END IF;

    BEGIN
        v_existing_organization_id :=
            NULLIF
            (
                btrim(
                    p_request #>>
                    '{organization,existing_organization_id}'
                ),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'organization.existing_organization_id must be a valid UUID';
    END;

    v_organization_name :=
        NULLIF(
            btrim(
                p_request #>> '{organization,name}'
            ),
            ''
        );

    v_organization_code :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{organization,code}'
                ),
                ''
            )
        );

    v_organization_description :=
        NULLIF
        (
            btrim(
                p_request #>> '{organization,description}'
            ),
            ''
        );

    IF v_organization_mode = 'CREATE_NEW' THEN
        IF v_organization_name IS NULL THEN
            RAISE EXCEPTION
                'organization.name is required for CREATE_NEW';
        END IF;

        IF v_organization_code IS NULL THEN
            RAISE EXCEPTION
                'organization.code is required for CREATE_NEW';
        END IF;

        IF v_organization_code !~ '^[A-Z0-9_]+$' THEN
            RAISE EXCEPTION
                'organization.code must contain only A-Z, 0-9, and underscore';
        END IF;

    ELSE
        IF v_existing_organization_id IS NULL THEN
            RAISE EXCEPTION
                'organization.existing_organization_id is required for USE_EXISTING';
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize site fields.
    --------------------------------------------------------------------------

    v_site_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(
                    btrim(
                        p_request #>> '{site,mode}'
                    ),
                    ''
                ),
                'CREATE_NEW'
            )
        );

    IF v_site_mode NOT IN
    (
        'CREATE_NEW',
        'USE_EXISTING'
    )
    THEN
        RAISE EXCEPTION
            'site.mode must be CREATE_NEW or USE_EXISTING';
    END IF;

    BEGIN
        v_existing_site_id :=
            NULLIF
            (
                btrim(
                    p_request #>>
                    '{site,existing_site_id}'
                ),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'site.existing_site_id must be a valid UUID';
    END;

    v_site_name :=
        NULLIF(
            btrim(
                p_request #>> '{site,name}'
            ),
            ''
        );

    v_site_code :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{site,code}'
                ),
                ''
            )
        );

    v_site_timezone :=
        COALESCE
        (
            NULLIF(
                btrim(
                    p_request #>> '{site,timezone}'
                ),
                ''
            ),
            'Asia/Kolkata'
        );

    v_site_address :=
        COALESCE(
            p_request #> '{site,address}',
            '{}'::JSONB
        );

    IF v_site_mode = 'CREATE_NEW' THEN
        IF v_site_name IS NULL THEN
            RAISE EXCEPTION
                'site.name is required for CREATE_NEW';
        END IF;

        IF v_site_code IS NULL THEN
            RAISE EXCEPTION
                'site.code is required for CREATE_NEW';
        END IF;

        IF v_site_code !~ '^[A-Z0-9_]+$' THEN
            RAISE EXCEPTION
                'site.code must contain only A-Z, 0-9, and underscore';
        END IF;

        IF jsonb_typeof(v_site_address) <> 'object' THEN
            RAISE EXCEPTION
                'site.address must be a JSON object';
        END IF;

        IF NOT EXISTS
        (
            SELECT 1
            FROM pg_timezone_names
            WHERE name = v_site_timezone
        )
        THEN
            RAISE EXCEPTION
                'Unknown IANA timezone: %',
                v_site_timezone;
        END IF;

    ELSE
        IF v_existing_site_id IS NULL THEN
            RAISE EXCEPTION
                'site.existing_site_id is required for USE_EXISTING';
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize optional physical-location fields.
    --------------------------------------------------------------------------

    v_location_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(btrim(p_request #>> '{location,mode}'), ''),
                'SITE_ONLY'
            )
        );

    IF v_location_mode NOT IN
    (
        'SITE_ONLY',
        'CREATE_LOCATION',
        'USE_EXISTING_SPACE'
    )
    THEN
        RAISE EXCEPTION
            'location.mode must be SITE_ONLY, CREATE_LOCATION, or USE_EXISTING_SPACE';
    END IF;

    BEGIN
        v_existing_space_id :=
            NULLIF(
                btrim(p_request #>> '{location,existing_space_id}'),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'location.existing_space_id must be a valid UUID';
    END;

    v_building_name :=
        NULLIF(btrim(p_request #>> '{location,building_name}'), '');

    v_building_code :=
        upper(NULLIF(btrim(p_request #>> '{location,building_code}'), ''));

    v_floor_name :=
        NULLIF(btrim(p_request #>> '{location,floor_name}'), '');

    v_floor_code :=
        upper(NULLIF(btrim(p_request #>> '{location,floor_code}'), ''));

    v_space_name :=
        NULLIF(btrim(p_request #>> '{location,space_name}'), '');

    v_space_code :=
        upper(NULLIF(btrim(p_request #>> '{location,space_code}'), ''));

    IF v_location_mode = 'CREATE_LOCATION' THEN
        IF v_building_name IS NULL OR v_building_code IS NULL THEN
            RAISE EXCEPTION
                'location building name and code are required for CREATE_LOCATION';
        END IF;

        IF v_floor_name IS NULL OR v_floor_code IS NULL THEN
            RAISE EXCEPTION
                'location floor name and code are required for CREATE_LOCATION';
        END IF;

        IF v_space_name IS NULL OR v_space_code IS NULL THEN
            RAISE EXCEPTION
                'location space name and code are required for CREATE_LOCATION';
        END IF;

        IF v_building_code !~ '^[A-Z][A-Z0-9_]*$' THEN
            RAISE EXCEPTION
                'location.building_code must contain only A-Z, 0-9, and underscore';
        END IF;

        IF v_floor_code !~ '^[A-Z][A-Z0-9_]*$' THEN
            RAISE EXCEPTION
                'location.floor_code must contain only A-Z, 0-9, and underscore';
        END IF;

        IF v_space_code !~ '^[A-Z][A-Z0-9_]*$' THEN
            RAISE EXCEPTION
                'location.space_code must contain only A-Z, 0-9, and underscore';
        END IF;

    ELSIF v_location_mode = 'USE_EXISTING_SPACE' THEN
        IF v_existing_space_id IS NULL THEN
            RAISE EXCEPTION
                'location.existing_space_id is required for USE_EXISTING_SPACE';
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize gateway fields.
    --------------------------------------------------------------------------

    v_gateway_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(
                    btrim(
                        p_request #>> '{gateway,mode}'
                    ),
                    ''
                ),
                'CREATE_NEW'
            )
        );

    IF v_gateway_mode NOT IN
    (
        'CREATE_NEW',
        'USE_EXISTING'
    )
    THEN
        RAISE EXCEPTION
            'gateway.mode must be CREATE_NEW or USE_EXISTING';
    END IF;

    BEGIN
        v_existing_gateway_id :=
            NULLIF
            (
                btrim(
                    p_request #>>
                    '{gateway,existing_gateway_id}'
                ),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'gateway.existing_gateway_id must be a valid UUID';
    END;

    v_gateway_name :=
        NULLIF(
            btrim(
                p_request #>> '{gateway,name}'
            ),
            ''
        );

    v_gateway_external_id :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{gateway,external_id}'
                ),
                ''
            )
        );

    v_gateway_vendor :=
        NULLIF(
            btrim(
                p_request #>> '{gateway,vendor}'
            ),
            ''
        );

    v_gateway_model :=
        NULLIF(
            btrim(
                p_request #>> '{gateway,model}'
            ),
            ''
        );

    v_gateway_protocol :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{gateway,protocol}'
                ),
                ''
            )
        );

    IF v_gateway_mode = 'CREATE_NEW' THEN
        IF v_gateway_name IS NULL THEN
            RAISE EXCEPTION
                'gateway.name is required for CREATE_NEW';
        END IF;

        IF v_gateway_external_id IS NULL THEN
            RAISE EXCEPTION
                'gateway.external_id is required for CREATE_NEW';
        END IF;

        IF v_gateway_vendor IS NULL THEN
            RAISE EXCEPTION
                'gateway.vendor is required for CREATE_NEW';
        END IF;

        IF v_gateway_model IS NULL THEN
            RAISE EXCEPTION
                'gateway.model is required for CREATE_NEW';
        END IF;

        IF v_gateway_protocol IS NULL THEN
            RAISE EXCEPTION
                'gateway.protocol is required for CREATE_NEW';
        END IF;

    ELSE
        IF v_existing_gateway_id IS NULL THEN
            RAISE EXCEPTION
                'gateway.existing_gateway_id is required for USE_EXISTING';
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize device fields.
    --------------------------------------------------------------------------

    v_device_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(
                    btrim(
                        p_request #>> '{device,mode}'
                    ),
                    ''
                ),
                'CREATE_NEW'
            )
        );

    IF v_device_mode NOT IN
    (
        'CREATE_NEW',
        'USE_EXISTING'
    )
    THEN
        RAISE EXCEPTION
            'device.mode must be CREATE_NEW or USE_EXISTING';
    END IF;

    BEGIN
        v_existing_device_id :=
            NULLIF
            (
                btrim(
                    p_request #>>
                    '{device,existing_device_id}'
                ),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'device.existing_device_id must be a valid UUID';
    END;

    v_device_name :=
        NULLIF(
            btrim(
                p_request #>> '{device,name}'
            ),
            ''
        );

    v_device_external_id :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{device,external_id}'
                ),
                ''
            )
        );

    v_device_model_vendor :=
        NULLIF(
            btrim(
                p_request #>> '{device,model_vendor}'
            ),
            ''
        );

    v_device_model :=
        NULLIF(
            btrim(
                p_request #>> '{device,model}'
            ),
            ''
        );

    v_device_type :=
        NULLIF(
            btrim(
                p_request #>> '{device,device_type}'
            ),
            ''
        );

    BEGIN
        v_device_category_id :=
            NULLIF
            (
                btrim(
                    p_request #>>
                    '{device,device_category_id}'
                ),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'device.device_category_id must be a valid UUID';
    END;

    v_device_firmware_version :=
        NULLIF(
            btrim(
                p_request #>> '{device,firmware_version}'
            ),
            ''
        );

    v_device_protocol :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{device,protocol}'
                ),
                ''
            )
        );

    v_profile_code :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{device,profile_code}'
                ),
                ''
            )
        );

    IF v_device_mode = 'CREATE_NEW' THEN
        IF v_device_name IS NULL THEN
            RAISE EXCEPTION
                'device.name is required for CREATE_NEW';
        END IF;

        IF v_device_external_id IS NULL THEN
            RAISE EXCEPTION
                'device.external_id is required for CREATE_NEW';
        END IF;

        IF v_device_model_vendor IS NULL THEN
            RAISE EXCEPTION
                'device.model_vendor is required for CREATE_NEW';
        END IF;

        IF v_device_model IS NULL THEN
            RAISE EXCEPTION
                'device.model is required for CREATE_NEW';
        END IF;

        IF v_device_category_id IS NULL
           AND v_device_type IS NULL
        THEN
            RAISE EXCEPTION
                'device.device_category_id is required for CREATE_NEW';
        END IF;

        IF v_device_protocol IS NULL THEN
            RAISE EXCEPTION
                'device.protocol is required for CREATE_NEW';
        END IF;

        IF v_profile_code IS NULL THEN
            RAISE EXCEPTION
                'device.profile_code is required for CREATE_NEW';
        END IF;

    ELSE
        IF v_existing_device_id IS NULL THEN
            RAISE EXCEPTION
                'device.existing_device_id is required for USE_EXISTING';
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize external identifier fields.
    --
    -- CREATE_NEW device:
    --   Identifier type and value are mandatory.
    --
    -- USE_EXISTING device:
    --   Identifier fields are optional. When supplied, they are used only
    --   to verify an existing identifier already belongs to the selected
    --   device. They are never created, changed, or transferred.
    --------------------------------------------------------------------------

    v_identifier_type :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{identifier,type}'
                ),
                ''
            )
        );

    v_identifier_value :=
        NULLIF
        (
            btrim(
                p_request #>> '{identifier,value}'
            ),
            ''
        );

    IF
    (
        v_identifier_type IS NULL
        AND v_identifier_value IS NOT NULL
    )
    OR
    (
        v_identifier_type IS NOT NULL
        AND v_identifier_value IS NULL
    )
    THEN
        RAISE EXCEPTION
            'identifier.type and identifier.value must be supplied together';
    END IF;

    IF v_device_mode = 'CREATE_NEW' THEN
        IF v_identifier_type IS NULL THEN
            RAISE EXCEPTION
                'identifier.type is required for a new device';
        END IF;

        IF v_identifier_value IS NULL THEN
            RAISE EXCEPTION
                'identifier.value is required for a new device';
        END IF;
    END IF;

    IF v_identifier_type = 'MQTT_UID' THEN
        v_identifier_value := lower(v_identifier_value);
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize asset fields.
    --------------------------------------------------------------------------

    v_asset_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(btrim(p_request #>> '{asset,mode}'), ''),
                'CREATE_NEW'
            )
        );

    IF v_asset_mode NOT IN ('CREATE_NEW', 'USE_EXISTING') THEN
        RAISE EXCEPTION
            'asset.mode must be CREATE_NEW or USE_EXISTING';
    END IF;

    BEGIN
        v_existing_asset_id :=
            NULLIF(
                btrim(p_request #>> '{asset,existing_asset_id}'),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'asset.existing_asset_id must be a valid UUID';
    END;

    v_asset_name :=
        NULLIF(btrim(p_request #>> '{asset,name}'), '');

    BEGIN
        v_asset_type_id :=
            NULLIF(
                btrim(p_request #>> '{asset,asset_type_id}'),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION 'asset.asset_type_id must be a valid UUID';
    END;

    v_relationship_type :=
        upper
        (
            COALESCE
            (
                NULLIF
                (
                    btrim
                    (
                        p_request #>> '{asset,relationship_type}'
                    ),
                    ''
                ),
                'PRIMARY_METER'
            )
        );

    v_asset_metadata :=
        COALESCE(p_request #> '{asset,metadata}', '{}'::JSONB);

    IF v_asset_mode = 'CREATE_NEW' THEN
        IF v_asset_name IS NULL THEN
            RAISE EXCEPTION
                'asset.name is required for CREATE_NEW';
        END IF;

        IF v_asset_type_id IS NULL THEN
            RAISE EXCEPTION
                'asset.asset_type_id is required for CREATE_NEW';
        END IF;

        IF NOT EXISTS
        (
            SELECT 1
            FROM metadata.asset_types at
            WHERE at.id = v_asset_type_id
        )
        THEN
            RAISE EXCEPTION
                'Unknown asset type UUID: %',
                v_asset_type_id;
        END IF;
    ELSE
        IF v_existing_asset_id IS NULL THEN
            RAISE EXCEPTION
                'asset.existing_asset_id is required for USE_EXISTING';
        END IF;
    END IF;

    IF jsonb_typeof(v_asset_metadata) <> 'object' THEN
        RAISE EXCEPTION 'asset.metadata must be a JSON object';
    END IF;


    --------------------------------------------------------------------------
    -- Optional Grafana organization ID.
    --------------------------------------------------------------------------

    BEGIN
        v_grafana_org_id :=
            NULLIF(p_request ->> 'grafana_org_id', '')::BIGINT;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION 'grafana_org_id must be a positive integer';
    END;

    IF v_grafana_org_id IS NOT NULL
       AND v_grafana_org_id <= 0
    THEN
        RAISE EXCEPTION 'grafana_org_id must be greater than zero';
    END IF;


    --------------------------------------------------------------------------
    -- Organization selection or creation.
    --
    -- CREATE_NEW:
    --   Inserts a genuinely new organization and rejects an existing code.
    --
    -- USE_EXISTING:
    --   Loads the selected active organization without modifying it.
    --------------------------------------------------------------------------

    IF v_organization_mode = 'USE_EXISTING' THEN

        -- Serialize concurrent operations against the same organization UUID.
        PERFORM pg_advisory_xact_lock
        (
            hashtext(v_existing_organization_id::TEXT)
        );

        SELECT
            o.id,
            o.name,
            o.code,
            o.description
        INTO
            v_organization_id,
            v_organization_name,
            v_organization_code,
            v_organization_description
        FROM metadata.organizations o
        WHERE o.id = v_existing_organization_id
          AND o.is_active = TRUE;

        IF v_organization_id IS NULL THEN
            RAISE EXCEPTION
                'Existing active organization % was not found',
                v_existing_organization_id;
        END IF;

    ELSE

        -- Serialize concurrent creation attempts using the organization code.
        PERFORM pg_advisory_xact_lock
        (
            hashtext(v_organization_code)
        );

        BEGIN
            INSERT INTO metadata.organizations
            (
                name,
                code,
                description,
                is_active
            )
            VALUES
            (
                v_organization_name,
                v_organization_code,
                v_organization_description,
                TRUE
            )
            RETURNING id
            INTO v_organization_id;

        EXCEPTION
            WHEN unique_violation THEN
                RAISE EXCEPTION
                    'Organization code % already exists; use USE_EXISTING instead',
                    v_organization_code;
        END;
    END IF;


    --------------------------------------------------------------------------
    -- Site selection or creation.
    --
    -- CREATE_NEW:
    --   Inserts a new site under the resolved organization.
    --
    -- USE_EXISTING:
    --   Validates that the selected active site belongs to the resolved
    --   organization and preserves all stored site attributes.
    --------------------------------------------------------------------------

    IF v_site_mode = 'USE_EXISTING' THEN

        SELECT
            s.id,
            s.name,
            s.code,
            s.timezone,
            s.address
        INTO
            v_site_id,
            v_site_name,
            v_site_code,
            v_site_timezone,
            v_site_address
        FROM metadata.sites s
        WHERE s.id = v_existing_site_id
          AND s.organization_id = v_organization_id
          AND s.is_active = TRUE;

        IF v_site_id IS NULL THEN
            RAISE EXCEPTION
                'Existing active site % was not found under organization %',
                v_existing_site_id,
                v_organization_id;
        END IF;

    ELSE

        BEGIN
            INSERT INTO metadata.sites
            (
                organization_id,
                name,
                code,
                timezone,
                address,
                is_active
            )
            VALUES
            (
                v_organization_id,
                v_site_name,
                v_site_code,
                v_site_timezone,
                v_site_address,
                TRUE
            )
            RETURNING id
            INTO v_site_id;

        EXCEPTION
            WHEN unique_violation THEN
                RAISE EXCEPTION
                    'Site code % already exists under organization %; use USE_EXISTING instead',
                    v_site_code,
                    v_organization_id;
        END;
    END IF;


    --------------------------------------------------------------------------
    -- Optional physical hierarchy.
    --------------------------------------------------------------------------

    v_space_id := NULL;

    IF v_location_mode = 'USE_EXISTING_SPACE' THEN
        SELECT
            sp.id,
            f.id,
            b.id
        INTO
            v_space_id,
            v_floor_id,
            v_building_id
        FROM metadata.spaces sp
        JOIN metadata.floors f
          ON f.id = sp.floor_id
        JOIN metadata.buildings b
          ON b.id = f.building_id
        WHERE sp.id = v_existing_space_id
          AND sp.organization_id = v_organization_id
          AND b.site_id = v_site_id;

        IF v_space_id IS NULL THEN
            RAISE EXCEPTION
                'Existing space % was not found in organization % and site %',
                v_existing_space_id,
                v_organization_code,
                v_site_code;
        END IF;

    ELSIF v_location_mode = 'CREATE_LOCATION' THEN
        INSERT INTO metadata.buildings
        (
            organization_id,
            site_id,
            name,
            code
        )
        VALUES
        (
            v_organization_id,
            v_site_id,
            v_building_name,
            v_building_code
        )
        ON CONFLICT (site_id, code)
        DO UPDATE SET
            organization_id = EXCLUDED.organization_id,
            name            = EXCLUDED.name,
            updated_at      = now()
        RETURNING id
        INTO v_building_id;

        INSERT INTO metadata.floors
        (
            organization_id,
            building_id,
            name,
            code
        )
        VALUES
        (
            v_organization_id,
            v_building_id,
            v_floor_name,
            v_floor_code
        )
        ON CONFLICT (building_id, code)
        DO UPDATE SET
            organization_id = EXCLUDED.organization_id,
            name            = EXCLUDED.name,
            updated_at      = now()
        RETURNING id
        INTO v_floor_id;

        INSERT INTO metadata.spaces
        (
            organization_id,
            floor_id,
            name,
            code
        )
        VALUES
        (
            v_organization_id,
            v_floor_id,
            v_space_name,
            v_space_code
        )
        ON CONFLICT (floor_id, code)
        DO UPDATE SET
            organization_id = EXCLUDED.organization_id,
            name            = EXCLUDED.name,
            updated_at      = now()
        RETURNING id
        INTO v_space_id;
    END IF;


    --------------------------------------------------------------------------
    -- Gateway selection or creation.
    --
    -- CREATE_NEW:
    --   Resolves or creates the gateway model, then inserts a new gateway.
    --   The resolved physical space is assigned to gateway.space_id.
    --
    -- USE_EXISTING:
    --   Validates that the selected gateway belongs to the resolved
    --   organization and site. Existing gateway attributes are preserved.
    --------------------------------------------------------------------------

    IF v_gateway_mode = 'USE_EXISTING' THEN

        SELECT
            g.id,
            g.name,
            g.external_id,
            g.gateway_model_id
        INTO
            v_gateway_id,
            v_gateway_name,
            v_gateway_external_id,
            v_gateway_model_id
        FROM metadata.gateways g
        WHERE g.id = v_existing_gateway_id
          AND g.organization_id = v_organization_id
          AND g.site_id = v_site_id;

        IF v_gateway_id IS NULL THEN
            RAISE EXCEPTION
                'Existing gateway % was not found under organization % and site %',
                v_existing_gateway_id,
                v_organization_id,
                v_site_id;
        END IF;

    ELSE

        ----------------------------------------------------------------------
        -- Gateway model resolution.
        ----------------------------------------------------------------------

        SELECT gm.id
        INTO v_gateway_model_id
        FROM metadata.gateway_models gm
        WHERE lower(COALESCE(gm.vendor, '')) =
              lower(v_gateway_vendor)
          AND lower(gm.model) =
              lower(v_gateway_model)
        ORDER BY gm.created_at, gm.id
        LIMIT 1;

        IF v_gateway_model_id IS NULL THEN
            INSERT INTO metadata.gateway_models
            (
                vendor,
                model,
                protocol
            )
            VALUES
            (
                v_gateway_vendor,
                v_gateway_model,
                v_gateway_protocol
            )
            RETURNING id
            INTO v_gateway_model_id;
        END IF;

        BEGIN
            INSERT INTO metadata.gateways
            (
                organization_id,
                site_id,
                gateway_model_id,
                name,
                external_id,
                space_id
            )
            VALUES
            (
                v_organization_id,
                v_site_id,
                v_gateway_model_id,
                v_gateway_name,
                v_gateway_external_id,
                v_space_id
            )
            RETURNING id
            INTO v_gateway_id;

        EXCEPTION
            WHEN unique_violation THEN
                RAISE EXCEPTION
                    'Gateway external ID % already exists under organization %; use USE_EXISTING instead',
                    v_gateway_external_id,
                    v_organization_id;
        END;
    END IF;


    --------------------------------------------------------------------------
    -- Device selection or creation.
    --
    -- CREATE_NEW:
    --   Resolves the controlled category, relationship compatibility,
    --   device model, and active compatible profile before inserting.
    --
    -- USE_EXISTING:
    --   Validates that the selected device belongs to the resolved
    --   organization and gateway. Existing device attributes are preserved.
    --------------------------------------------------------------------------

    IF v_device_mode = 'USE_EXISTING' THEN

        SELECT
            d.id,
            d.name,
            d.external_id,
            d.device_model_id,
            d.firmware_version,
            d.protocol,
            d.profile_id,
            dm.device_category_id,
            dc.name,
            dp.profile_code
        INTO
            v_device_id,
            v_device_name,
            v_device_external_id,
            v_device_model_id,
            v_device_firmware_version,
            v_device_protocol,
            v_profile_id,
            v_device_category_id,
            v_device_category_name,
            v_profile_code
        FROM metadata.devices d
        LEFT JOIN metadata.device_models dm
          ON dm.id = d.device_model_id
        LEFT JOIN config.device_categories dc
          ON dc.id = dm.device_category_id
        LEFT JOIN config.device_profiles dp
          ON dp.id = d.profile_id
        WHERE d.id = v_existing_device_id
          AND d.organization_id = v_organization_id
          AND d.gateway_id = v_gateway_id;

        IF v_device_id IS NULL THEN
            RAISE EXCEPTION
                'Existing device % was not found under organization % and gateway %',
                v_existing_device_id,
                v_organization_id,
                v_gateway_id;
        END IF;

        IF v_device_category_id IS NULL
           OR v_device_category_name IS NULL
        THEN
            RAISE EXCEPTION
                'Existing device % does not have a controlled device category',
                v_existing_device_id;
        END IF;

        IF v_profile_id IS NULL
           OR v_profile_code IS NULL
        THEN
            RAISE EXCEPTION
                'Existing device % does not have an active onboarding profile',
                v_existing_device_id;
        END IF;

    ELSE

        ----------------------------------------------------------------------
        -- Controlled device category.
        ----------------------------------------------------------------------

        IF v_device_category_id IS NOT NULL THEN
            SELECT
                dc.id,
                dc.name
            INTO
                v_device_category_id,
                v_device_category_name
            FROM config.device_categories dc
            WHERE dc.id = v_device_category_id;
        ELSE
            SELECT
                dc.id,
                dc.name
            INTO
                v_device_category_id,
                v_device_category_name
            FROM config.device_categories dc
            WHERE lower(dc.name) = lower(v_device_type)
            ORDER BY dc.created_at, dc.id
            LIMIT 1;
        END IF;

        IF v_device_category_id IS NULL THEN
            RAISE EXCEPTION
                'Controlled device category was not found';
        END IF;

        -- Keep the legacy text value synchronized during the transition.
        v_device_type := v_device_category_name;


        ----------------------------------------------------------------------
        -- Controlled category-to-asset relationship compatibility.
        ----------------------------------------------------------------------

        IF v_device_category_name = 'Energy Meter' THEN
            IF v_relationship_type NOT IN
            (
                'PRIMARY_METER',
                'SECONDARY_METER',
                'SECONDARY_METER'
            )
            THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Environmental Sensor' THEN
            IF v_relationship_type NOT IN
            (
                'TEMPERATURE_SENSOR',
                'HUMIDITY_SENSOR'
            )
            THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Temperature Sensor' THEN
            IF v_relationship_type <> 'TEMPERATURE_SENSOR' THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Flow Meter' THEN
            IF v_relationship_type <> 'FLOW_SENSOR' THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Pressure Sensor' THEN
            IF v_relationship_type <> 'PRESSURE_SENSOR' THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Digital Input Module' THEN
            IF v_relationship_type NOT IN
            (
                'STATUS_INPUT',
                'RUN_STATUS',
                'FAULT_STATUS'
            )
            THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'BMS Controller' THEN
            IF v_relationship_type <> 'CONTROLLER' THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'PLC' THEN
            IF v_relationship_type NOT IN
            (
                'CONTROLLER',
                'STATUS_INPUT',
                'RUN_STATUS',
                'FAULT_STATUS'
            )
            THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Gateway' THEN
            RAISE EXCEPTION
                'Device category Gateway cannot be attached directly to an asset';

        ELSE
            RAISE EXCEPTION
                'No asset relationship rules are configured for device category %',
                v_device_category_name;
        END IF;


        ----------------------------------------------------------------------
        -- Device model.
        ----------------------------------------------------------------------

        SELECT
            dm.id,
            dm.device_category_id
        INTO
            v_device_model_id,
            v_existing_model_category_id
        FROM metadata.device_models dm
        WHERE lower(COALESCE(dm.vendor, '')) =
              lower(v_device_model_vendor)
          AND lower(dm.model) =
              lower(v_device_model)
        ORDER BY dm.created_at, dm.id
        LIMIT 1;

        IF v_device_model_id IS NULL THEN
            INSERT INTO metadata.device_models
            (
                vendor,
                model,
                device_type,
                device_category_id
            )
            VALUES
            (
                v_device_model_vendor,
                v_device_model,
                v_device_type,
                v_device_category_id
            )
            RETURNING id
            INTO v_device_model_id;
        ELSE
            IF v_existing_model_category_id <> v_device_category_id THEN
                RAISE EXCEPTION
                    'Device model % / % already belongs to a different category',
                    v_device_model_vendor,
                    v_device_model;
            END IF;

            UPDATE metadata.device_models
            SET device_type = v_device_category_name
            WHERE id = v_device_model_id
              AND device_type IS DISTINCT FROM v_device_category_name;
        END IF;


        ----------------------------------------------------------------------
        -- Active payload profile.
        ----------------------------------------------------------------------

        SELECT dp.id
        INTO v_profile_id
        FROM config.device_profiles dp
        WHERE dp.profile_code = v_profile_code
          AND dp.is_active = TRUE;

        IF v_profile_id IS NULL THEN
            RAISE EXCEPTION
                'Active device profile not found: %',
                v_profile_code;
        END IF;

        IF NOT EXISTS
        (
            SELECT 1
            FROM config.device_profile_categories dpc
            WHERE dpc.profile_id = v_profile_id
              AND dpc.device_category_id = v_device_category_id
        )
        THEN
            RAISE EXCEPTION
                'Device profile % is not compatible with device category %',
                v_profile_code,
                v_device_category_name;
        END IF;


        ----------------------------------------------------------------------
        -- Insert new device.
        ----------------------------------------------------------------------

        BEGIN
            INSERT INTO metadata.devices
            (
                organization_id,
                gateway_id,
                device_model_id,
                name,
                external_id,
                serial_number,
                firmware_version,
                protocol,
                profile_id
            )
            VALUES
            (
                v_organization_id,
                v_gateway_id,
                v_device_model_id,
                v_device_name,
                v_device_external_id,
                NULL,
                v_device_firmware_version,
                v_device_protocol,
                v_profile_id
            )
            RETURNING id
            INTO v_device_id;

        EXCEPTION
            WHEN unique_violation THEN
                RAISE EXCEPTION
                    'Device external ID % already exists under organization %; use USE_EXISTING instead',
                    v_device_external_id,
                    v_organization_id;
        END;
    END IF;


    --------------------------------------------------------------------------
    -- Validate relationship compatibility for both new and existing devices.
    --------------------------------------------------------------------------

    IF v_device_category_name = 'Energy Meter' THEN
        IF v_relationship_type NOT IN
        (
            'PRIMARY_METER',
            'SECONDARY_METER',
            'SECONDARY_METER'
        )
        THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Environmental Sensor' THEN
        IF v_relationship_type NOT IN
        (
            'TEMPERATURE_SENSOR',
            'HUMIDITY_SENSOR'
        )
        THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Temperature Sensor' THEN
        IF v_relationship_type <> 'TEMPERATURE_SENSOR' THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Flow Meter' THEN
        IF v_relationship_type <> 'FLOW_SENSOR' THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Pressure Sensor' THEN
        IF v_relationship_type <> 'PRESSURE_SENSOR' THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Digital Input Module' THEN
        IF v_relationship_type NOT IN
        (
            'STATUS_INPUT',
            'RUN_STATUS',
            'FAULT_STATUS'
        )
        THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'BMS Controller' THEN
        IF v_relationship_type <> 'CONTROLLER' THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'PLC' THEN
        IF v_relationship_type NOT IN
        (
            'CONTROLLER',
            'STATUS_INPUT',
            'RUN_STATUS',
            'FAULT_STATUS'
        )
        THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Gateway' THEN
        RAISE EXCEPTION
            'Device category Gateway cannot be attached directly to an asset';

    ELSE
        RAISE EXCEPTION
            'No asset relationship rules are configured for device category %',
            v_device_category_name;
    END IF;


    --------------------------------------------------------------------------
    -- External device identifier.
    --
    -- CREATE_NEW:
    --   Creates the required external identifier only when it is not already
    --   owned by another device.
    --
    -- USE_EXISTING:
    --   Preserves all identifiers. Optional supplied values are verification
    --   inputs only and must already belong to the selected device.
    --------------------------------------------------------------------------

    IF v_device_mode = 'CREATE_NEW' THEN

        SELECT di.device_id
        INTO v_existing_identifier_device_id
        FROM metadata.device_identifiers di
        WHERE di.identifier_type = v_identifier_type
          AND
          (
              CASE
                  WHEN v_identifier_type = 'MQTT_UID'
                  THEN lower(di.identifier_value)
                  ELSE di.identifier_value
              END
          ) = v_identifier_value
        ORDER BY di.created_at, di.id
        LIMIT 1;

        IF v_existing_identifier_device_id IS NOT NULL THEN
            RAISE EXCEPTION
                'Identifier %:% is already assigned to device %',
                v_identifier_type,
                v_identifier_value,
                v_existing_identifier_device_id;
        END IF;

        INSERT INTO metadata.device_identifiers
        (
            device_id,
            identifier_type,
            identifier_value
        )
        VALUES
        (
            v_device_id,
            v_identifier_type,
            v_identifier_value
        );

    ELSIF v_identifier_type IS NOT NULL THEN

        SELECT di.device_id
        INTO v_existing_identifier_device_id
        FROM metadata.device_identifiers di
        WHERE di.identifier_type = v_identifier_type
          AND
          (
              CASE
                  WHEN v_identifier_type = 'MQTT_UID'
                  THEN lower(di.identifier_value)
                  ELSE di.identifier_value
              END
          ) = v_identifier_value
        ORDER BY di.created_at, di.id
        LIMIT 1;

        IF v_existing_identifier_device_id IS NULL THEN
            RAISE EXCEPTION
                'Identifier %:% does not exist for the selected device',
                v_identifier_type,
                v_identifier_value;
        END IF;

        IF v_existing_identifier_device_id <> v_device_id THEN
            RAISE EXCEPTION
                'Identifier %:% belongs to device %, not selected device %',
                v_identifier_type,
                v_identifier_value,
                v_existing_identifier_device_id,
                v_device_id;
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Asset selection or creation.
    --------------------------------------------------------------------------

    IF v_asset_mode = 'USE_EXISTING' THEN
        SELECT
            a.id,
            a.name,
            a.asset_type_id
        INTO
            v_asset_id,
            v_asset_name,
            v_asset_type_id
        FROM metadata.assets a
        WHERE a.id = v_existing_asset_id
          AND a.organization_id = v_organization_id
          AND a.site_id = v_site_id;

        IF v_asset_id IS NULL THEN
            RAISE EXCEPTION
                'Existing asset % was not found in organization % and site %',
                v_existing_asset_id,
                v_organization_code,
                v_site_code;
        END IF;

    ELSE
        SELECT a.id
        INTO v_asset_id
        FROM metadata.assets a
        WHERE a.organization_id = v_organization_id
          AND a.site_id = v_site_id
          AND a.parent_asset_id IS NULL
          AND a.name = v_asset_name
          AND a.space_id IS NOT DISTINCT FROM v_space_id
        ORDER BY a.created_at, a.id
        LIMIT 1;

        IF v_asset_id IS NULL THEN
            INSERT INTO metadata.assets
            (
                organization_id,
                site_id,
                asset_type_id,
                parent_asset_id,
                name,
                manufacturer,
                model,
                serial_number,
                status,
                metadata,
                building_id,
                floor_id,
                space_id
            )
            VALUES
            (
                v_organization_id,
                v_site_id,
                v_asset_type_id,
                NULL,
                v_asset_name,
                NULL,
                NULL,
                NULL,
                'active',
                v_asset_metadata,
                v_building_id,
                v_floor_id,
                v_space_id
            )
            RETURNING id
            INTO v_asset_id;
        ELSE
            UPDATE metadata.assets
            SET
                asset_type_id = v_asset_type_id,
                status        = 'active',
                metadata      = v_asset_metadata,
                building_id   = v_building_id,
                floor_id      = v_floor_id,
                space_id      = v_space_id,
                updated_at    = now()
            WHERE id = v_asset_id;
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Asset-device relationship.
    --
    -- The canonical partial unique index allows a device to be PRIMARY_METER
    -- for at most one asset.
    --------------------------------------------------------------------------

    IF v_relationship_type = 'PRIMARY_METER' THEN
        SELECT ad.asset_id
        INTO v_existing_primary_asset_id
        FROM metadata.asset_devices ad
        WHERE ad.device_id = v_device_id
          AND ad.relationship_type = 'PRIMARY_METER'
        ORDER BY ad.created_at, ad.id
        LIMIT 1;

        IF v_existing_primary_asset_id IS NOT NULL
           AND v_existing_primary_asset_id <> v_asset_id
        THEN
            RAISE EXCEPTION
                'Device % is already PRIMARY_METER for asset %',
                v_device_id,
                v_existing_primary_asset_id;
        END IF;

        IF EXISTS
        (
            SELECT 1
            FROM metadata.asset_devices ad
            WHERE ad.asset_id = v_asset_id
              AND ad.relationship_type = 'PRIMARY_METER'
              AND ad.device_id <> v_device_id
        )
        THEN
            RAISE EXCEPTION
                'Asset % already has a different PRIMARY_METER',
                v_asset_id;
        END IF;
    END IF;

    INSERT INTO metadata.asset_devices
    (
        asset_id,
        device_id,
        relationship_type
    )
    VALUES
    (
        v_asset_id,
        v_device_id,
        v_relationship_type
    )
    ON CONFLICT
        (asset_id, device_id, relationship_type)
    DO NOTHING;


    --------------------------------------------------------------------------
    -- Optional Grafana organization mapping.
    --
    -- Reject both forms of cross-tenant reassignment:
    --
    --   1. EMS organization already mapped to a different Grafana org.
    --   2. Grafana org already mapped to a different EMS organization.
    --------------------------------------------------------------------------

    IF v_grafana_org_id IS NOT NULL THEN
        SELECT gom.grafana_org_id
        INTO v_existing_grafana_org_id
        FROM metadata.grafana_organization_map gom
        WHERE gom.organization_id = v_organization_id;

        IF v_existing_grafana_org_id IS NOT NULL
           AND v_existing_grafana_org_id <> v_grafana_org_id
        THEN
            RAISE EXCEPTION
                'EMS organization % is already mapped to Grafana org %',
                v_organization_id,
                v_existing_grafana_org_id;
        END IF;

        SELECT gom.organization_id
        INTO v_existing_grafana_org_owner
        FROM metadata.grafana_organization_map gom
        WHERE gom.grafana_org_id = v_grafana_org_id;

        IF v_existing_grafana_org_owner IS NOT NULL
           AND v_existing_grafana_org_owner <> v_organization_id
        THEN
            RAISE EXCEPTION
                'Grafana org % is already mapped to EMS organization %',
                v_grafana_org_id,
                v_existing_grafana_org_owner;
        END IF;

        INSERT INTO metadata.grafana_organization_map
        (
            grafana_org_id,
            organization_id,
            is_active
        )
        VALUES
        (
            v_grafana_org_id,
            v_organization_id,
            TRUE
        )
        ON CONFLICT (grafana_org_id)
        DO UPDATE SET
            organization_id = EXCLUDED.organization_id,
            is_active        = TRUE,
            updated_at       = now();
    END IF;


    --------------------------------------------------------------------------
    -- Build result and audit successful completion.
    --------------------------------------------------------------------------

    v_result :=
        jsonb_build_object
        (
            'organization_id',  v_organization_id,
            'organization_code', v_organization_code,
            'site_id',          v_site_id,
            'site_code',        v_site_code,
            'location_mode',    v_location_mode,
            'building_id',      v_building_id,
            'floor_id',         v_floor_id,
            'space_id',         v_space_id,
            'gateway_model_id', v_gateway_model_id,
            'gateway_id',       v_gateway_id,
            'device_model_id',  v_device_model_id,
            'device_category_id', v_device_category_id,
            'device_category_name', v_device_category_name,
            'profile_id',       v_profile_id,
            'profile_code',     v_profile_code,
            'device_id',        v_device_id,
            'device_external_id', v_device_external_id,
            'identifier_type',  v_identifier_type,
            'identifier_value', v_identifier_value,
            'asset_mode',       v_asset_mode,
            'asset_id',         v_asset_id,
            'asset_name',       v_asset_name,
            'relationship_type', v_relationship_type,
            'grafana_org_id',   v_grafana_org_id
        );

    INSERT INTO admin.onboarding_audit
    (
        requested_by,
        request_payload,
        result_payload
    )
    VALUES
    (
        COALESCE(NULLIF(btrim(p_requested_by), ''), current_user),
        p_request,
        v_result
    );

    RETURN v_result;
END;
$function$;

ALTER FUNCTION admin.onboard_energy_asset_legacy_upsert(JSONB, TEXT)
    OWNER TO ems_admin;

REVOKE ALL ON FUNCTION
    admin.onboard_energy_asset_legacy_upsert(JSONB, TEXT)
    FROM PUBLIC;

GRANT EXECUTE ON FUNCTION
    admin.onboard_energy_asset_legacy_upsert(JSONB, TEXT)
    TO ems_app;


-- ====================================================================
-- Historical migration: 141_asset_external_identity.sql
-- ====================================================================

-- Migration 141
-- Add a stable, site-scoped external identity for assets.
--
-- Display names remain non-unique. external_id is the machine identifier.
-- When omitted, PostgreSQL generates a unique value from the asset name.


ALTER TABLE metadata.assets
    ADD COLUMN IF NOT EXISTS external_id TEXT;

CREATE OR REPLACE FUNCTION metadata.generate_asset_external_id()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO pg_catalog, metadata
AS $function$
DECLARE
    v_base      TEXT;
    v_candidate TEXT;
    v_suffix    INTEGER := 1;
BEGIN
    IF NULLIF(btrim(NEW.external_id), '') IS NOT NULL THEN
        NEW.external_id := upper(btrim(NEW.external_id));
        RETURN NEW;
    END IF;

    v_base := upper(
        trim(
            both '_' FROM
            regexp_replace(
                COALESCE(NULLIF(btrim(NEW.name), ''), 'ASSET'),
                '[^A-Za-z0-9]+',
                '_',
                'g'
            )
        )
    );

    IF v_base = '' THEN
        v_base := 'ASSET';
    END IF;

    v_base := left(v_base, 100);

    -- Serialize generation for the same organization/site/base combination.
    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            NEW.organization_id::text
            || ':'
            || NEW.site_id::text
            || ':'
            || v_base,
            0
        )
    );

    v_candidate := v_base;

    WHILE EXISTS
    (
        SELECT 1
        FROM metadata.assets AS existing_asset
        WHERE existing_asset.organization_id = NEW.organization_id
          AND existing_asset.site_id = NEW.site_id
          AND upper(btrim(existing_asset.external_id))
              = upper(btrim(v_candidate))
          AND existing_asset.id IS DISTINCT FROM NEW.id
    )
    LOOP
        v_suffix := v_suffix + 1;

        v_candidate :=
            left(
                v_base,
                100 - length(v_suffix::text) - 1
            )
            || '_'
            || v_suffix::text;
    END LOOP;

    NEW.external_id := v_candidate;

    RETURN NEW;
END;
$function$;

ALTER FUNCTION metadata.generate_asset_external_id()
    OWNER TO ems_admin;

DROP TRIGGER IF EXISTS trg_generate_asset_external_id
    ON metadata.assets;

CREATE TRIGGER trg_generate_asset_external_id
BEFORE INSERT OR UPDATE OF name, external_id, organization_id, site_id
ON metadata.assets
FOR EACH ROW
EXECUTE FUNCTION metadata.generate_asset_external_id();

-- Backfill existing rows through the same trigger logic.
UPDATE metadata.assets
SET external_id = NULL
WHERE NULLIF(btrim(external_id), '') IS NULL;

ALTER TABLE metadata.assets
    ALTER COLUMN external_id SET NOT NULL;

ALTER TABLE metadata.assets
    DROP CONSTRAINT IF EXISTS assets_external_id_format_chk;

ALTER TABLE metadata.assets
    ADD CONSTRAINT assets_external_id_format_chk
    CHECK
    (
        external_id ~ '^[A-Z0-9][A-Z0-9_]*$'
        AND length(external_id) <= 100
    );

CREATE UNIQUE INDEX IF NOT EXISTS assets_org_site_external_id_ci_uq
    ON metadata.assets
    (
        organization_id,
        site_id,
        upper(btrim(external_id))
    );

COMMENT ON COLUMN metadata.assets.external_id IS
    'Stable system identity unique within organization and site; generated from name when omitted.';

COMMENT ON FUNCTION metadata.generate_asset_external_id() IS
    'Generates a site-scoped asset external ID while allowing duplicate asset names.';


-- ====================================================================
-- Historical migration: 142_onboarding_asset_external_identity.sql
-- ====================================================================

-- Migration 142
-- Carry Asset External ID through onboarding and use it as machine identity.
--
-- A selected or newly created space requires its matching floor and building.
-- The previous onboarding writer passed only space_id to metadata.assets.


CREATE OR REPLACE FUNCTION admin.onboard_energy_asset_legacy_upsert(p_request jsonb, p_requested_by text DEFAULT CURRENT_USER)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'admin', 'metadata', 'config'
AS $function$
DECLARE
    v_organization_mode        TEXT;
    v_existing_organization_id UUID;
    v_organization_name        TEXT;
    v_organization_code        TEXT;
    v_organization_description TEXT;

    v_site_mode                TEXT;
    v_existing_site_id         UUID;
    v_site_name                TEXT;
    v_site_code                TEXT;
    v_site_timezone            TEXT;
    v_site_address             JSONB;

    v_location_mode            TEXT;
    v_existing_space_id        UUID;

    v_building_name            TEXT;
    v_building_code            TEXT;
    v_building_id              UUID;

    v_floor_name               TEXT;
    v_floor_code               TEXT;
    v_floor_id                 UUID;

    v_space_name               TEXT;
    v_space_code               TEXT;
    v_space_id                 UUID;

    v_gateway_mode             TEXT;
    v_existing_gateway_id      UUID;
    v_gateway_name             TEXT;
    v_gateway_external_id      TEXT;
    v_gateway_vendor           TEXT;
    v_gateway_model            TEXT;
    v_gateway_protocol         TEXT;

    v_device_mode              TEXT;
    v_existing_device_id       UUID;
    v_device_name              TEXT;
    v_device_external_id       TEXT;
    v_device_model_vendor      TEXT;
    v_device_model             TEXT;

    -- device_type is retained temporarily for backward compatibility.
    v_device_type              TEXT;
    v_device_category_id       UUID;
    v_device_category_name     TEXT;
    v_existing_model_category_id UUID;

    v_device_firmware_version  TEXT;
    v_device_protocol          TEXT;
    v_profile_code             TEXT;

    v_identifier_type          TEXT;
    v_identifier_value         TEXT;

    v_asset_mode               TEXT;
    v_existing_asset_id        UUID;
    v_asset_name               TEXT;
    v_asset_external_id        TEXT;
    v_asset_type_id            UUID;
    v_relationship_type        TEXT;
    v_asset_metadata           JSONB;

    v_grafana_org_id           BIGINT;

    v_organization_id          UUID;
    v_site_id                  UUID;
    v_gateway_model_id         UUID;
    v_gateway_id               UUID;
    v_device_model_id          UUID;
    v_profile_id               UUID;
    v_device_id                UUID;
    v_asset_id                 UUID;

    v_existing_identifier_device_id UUID;
    v_existing_primary_asset_id     UUID;
    v_existing_grafana_org_id       BIGINT;
    v_existing_grafana_org_owner    UUID;

    v_result                    JSONB;
BEGIN
    --------------------------------------------------------------------------
    -- Validate request container.
    --------------------------------------------------------------------------

    IF p_request IS NULL
       OR jsonb_typeof(p_request) <> 'object'
    THEN
        RAISE EXCEPTION
            'Onboarding request must be a JSON object';
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize organization fields.
    --------------------------------------------------------------------------

    v_organization_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(
                    btrim(
                        p_request #>> '{organization,mode}'
                    ),
                    ''
                ),
                'CREATE_NEW'
            )
        );

    IF v_organization_mode NOT IN
    (
        'CREATE_NEW',
        'USE_EXISTING'
    )
    THEN
        RAISE EXCEPTION
            'organization.mode must be CREATE_NEW or USE_EXISTING';
    END IF;

    BEGIN
        v_existing_organization_id :=
            NULLIF
            (
                btrim(
                    p_request #>>
                    '{organization,existing_organization_id}'
                ),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'organization.existing_organization_id must be a valid UUID';
    END;

    v_organization_name :=
        NULLIF(
            btrim(
                p_request #>> '{organization,name}'
            ),
            ''
        );

    v_organization_code :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{organization,code}'
                ),
                ''
            )
        );

    v_organization_description :=
        NULLIF
        (
            btrim(
                p_request #>> '{organization,description}'
            ),
            ''
        );

    IF v_organization_mode = 'CREATE_NEW' THEN
        IF v_organization_name IS NULL THEN
            RAISE EXCEPTION
                'organization.name is required for CREATE_NEW';
        END IF;

        IF v_organization_code IS NULL THEN
            RAISE EXCEPTION
                'organization.code is required for CREATE_NEW';
        END IF;

        IF v_organization_code !~ '^[A-Z0-9_]+$' THEN
            RAISE EXCEPTION
                'organization.code must contain only A-Z, 0-9, and underscore';
        END IF;

    ELSE
        IF v_existing_organization_id IS NULL THEN
            RAISE EXCEPTION
                'organization.existing_organization_id is required for USE_EXISTING';
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize site fields.
    --------------------------------------------------------------------------

    v_site_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(
                    btrim(
                        p_request #>> '{site,mode}'
                    ),
                    ''
                ),
                'CREATE_NEW'
            )
        );

    IF v_site_mode NOT IN
    (
        'CREATE_NEW',
        'USE_EXISTING'
    )
    THEN
        RAISE EXCEPTION
            'site.mode must be CREATE_NEW or USE_EXISTING';
    END IF;

    BEGIN
        v_existing_site_id :=
            NULLIF
            (
                btrim(
                    p_request #>>
                    '{site,existing_site_id}'
                ),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'site.existing_site_id must be a valid UUID';
    END;

    v_site_name :=
        NULLIF(
            btrim(
                p_request #>> '{site,name}'
            ),
            ''
        );

    v_site_code :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{site,code}'
                ),
                ''
            )
        );

    v_site_timezone :=
        COALESCE
        (
            NULLIF(
                btrim(
                    p_request #>> '{site,timezone}'
                ),
                ''
            ),
            'Asia/Kolkata'
        );

    v_site_address :=
        COALESCE(
            p_request #> '{site,address}',
            '{}'::JSONB
        );

    IF v_site_mode = 'CREATE_NEW' THEN
        IF v_site_name IS NULL THEN
            RAISE EXCEPTION
                'site.name is required for CREATE_NEW';
        END IF;

        IF v_site_code IS NULL THEN
            RAISE EXCEPTION
                'site.code is required for CREATE_NEW';
        END IF;

        IF v_site_code !~ '^[A-Z0-9_]+$' THEN
            RAISE EXCEPTION
                'site.code must contain only A-Z, 0-9, and underscore';
        END IF;

        IF jsonb_typeof(v_site_address) <> 'object' THEN
            RAISE EXCEPTION
                'site.address must be a JSON object';
        END IF;

        IF NOT EXISTS
        (
            SELECT 1
            FROM pg_timezone_names
            WHERE name = v_site_timezone
        )
        THEN
            RAISE EXCEPTION
                'Unknown IANA timezone: %',
                v_site_timezone;
        END IF;

    ELSE
        IF v_existing_site_id IS NULL THEN
            RAISE EXCEPTION
                'site.existing_site_id is required for USE_EXISTING';
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize optional physical-location fields.
    --------------------------------------------------------------------------

    v_location_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(btrim(p_request #>> '{location,mode}'), ''),
                'SITE_ONLY'
            )
        );

    IF v_location_mode NOT IN
    (
        'SITE_ONLY',
        'CREATE_LOCATION',
        'USE_EXISTING_SPACE'
    )
    THEN
        RAISE EXCEPTION
            'location.mode must be SITE_ONLY, CREATE_LOCATION, or USE_EXISTING_SPACE';
    END IF;

    BEGIN
        v_existing_space_id :=
            NULLIF(
                btrim(p_request #>> '{location,existing_space_id}'),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'location.existing_space_id must be a valid UUID';
    END;

    v_building_name :=
        NULLIF(btrim(p_request #>> '{location,building_name}'), '');

    v_building_code :=
        upper(NULLIF(btrim(p_request #>> '{location,building_code}'), ''));

    v_floor_name :=
        NULLIF(btrim(p_request #>> '{location,floor_name}'), '');

    v_floor_code :=
        upper(NULLIF(btrim(p_request #>> '{location,floor_code}'), ''));

    v_space_name :=
        NULLIF(btrim(p_request #>> '{location,space_name}'), '');

    v_space_code :=
        upper(NULLIF(btrim(p_request #>> '{location,space_code}'), ''));

    IF v_location_mode = 'CREATE_LOCATION' THEN
        IF v_building_name IS NULL OR v_building_code IS NULL THEN
            RAISE EXCEPTION
                'location building name and code are required for CREATE_LOCATION';
        END IF;

        IF v_floor_name IS NULL OR v_floor_code IS NULL THEN
            RAISE EXCEPTION
                'location floor name and code are required for CREATE_LOCATION';
        END IF;

        IF v_space_name IS NULL OR v_space_code IS NULL THEN
            RAISE EXCEPTION
                'location space name and code are required for CREATE_LOCATION';
        END IF;

        IF v_building_code !~ '^[A-Z][A-Z0-9_]*$' THEN
            RAISE EXCEPTION
                'location.building_code must contain only A-Z, 0-9, and underscore';
        END IF;

        IF v_floor_code !~ '^[A-Z][A-Z0-9_]*$' THEN
            RAISE EXCEPTION
                'location.floor_code must contain only A-Z, 0-9, and underscore';
        END IF;

        IF v_space_code !~ '^[A-Z][A-Z0-9_]*$' THEN
            RAISE EXCEPTION
                'location.space_code must contain only A-Z, 0-9, and underscore';
        END IF;

    ELSIF v_location_mode = 'USE_EXISTING_SPACE' THEN
        IF v_existing_space_id IS NULL THEN
            RAISE EXCEPTION
                'location.existing_space_id is required for USE_EXISTING_SPACE';
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize gateway fields.
    --------------------------------------------------------------------------

    v_gateway_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(
                    btrim(
                        p_request #>> '{gateway,mode}'
                    ),
                    ''
                ),
                'CREATE_NEW'
            )
        );

    IF v_gateway_mode NOT IN
    (
        'CREATE_NEW',
        'USE_EXISTING'
    )
    THEN
        RAISE EXCEPTION
            'gateway.mode must be CREATE_NEW or USE_EXISTING';
    END IF;

    BEGIN
        v_existing_gateway_id :=
            NULLIF
            (
                btrim(
                    p_request #>>
                    '{gateway,existing_gateway_id}'
                ),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'gateway.existing_gateway_id must be a valid UUID';
    END;

    v_gateway_name :=
        NULLIF(
            btrim(
                p_request #>> '{gateway,name}'
            ),
            ''
        );

    v_gateway_external_id :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{gateway,external_id}'
                ),
                ''
            )
        );

    v_gateway_vendor :=
        NULLIF(
            btrim(
                p_request #>> '{gateway,vendor}'
            ),
            ''
        );

    v_gateway_model :=
        NULLIF(
            btrim(
                p_request #>> '{gateway,model}'
            ),
            ''
        );

    v_gateway_protocol :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{gateway,protocol}'
                ),
                ''
            )
        );

    IF v_gateway_mode = 'CREATE_NEW' THEN
        IF v_gateway_name IS NULL THEN
            RAISE EXCEPTION
                'gateway.name is required for CREATE_NEW';
        END IF;

        IF v_gateway_external_id IS NULL THEN
            RAISE EXCEPTION
                'gateway.external_id is required for CREATE_NEW';
        END IF;

        IF v_gateway_vendor IS NULL THEN
            RAISE EXCEPTION
                'gateway.vendor is required for CREATE_NEW';
        END IF;

        IF v_gateway_model IS NULL THEN
            RAISE EXCEPTION
                'gateway.model is required for CREATE_NEW';
        END IF;

        IF v_gateway_protocol IS NULL THEN
            RAISE EXCEPTION
                'gateway.protocol is required for CREATE_NEW';
        END IF;

    ELSE
        IF v_existing_gateway_id IS NULL THEN
            RAISE EXCEPTION
                'gateway.existing_gateway_id is required for USE_EXISTING';
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize device fields.
    --------------------------------------------------------------------------

    v_device_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(
                    btrim(
                        p_request #>> '{device,mode}'
                    ),
                    ''
                ),
                'CREATE_NEW'
            )
        );

    IF v_device_mode NOT IN
    (
        'CREATE_NEW',
        'USE_EXISTING'
    )
    THEN
        RAISE EXCEPTION
            'device.mode must be CREATE_NEW or USE_EXISTING';
    END IF;

    BEGIN
        v_existing_device_id :=
            NULLIF
            (
                btrim(
                    p_request #>>
                    '{device,existing_device_id}'
                ),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'device.existing_device_id must be a valid UUID';
    END;

    v_device_name :=
        NULLIF(
            btrim(
                p_request #>> '{device,name}'
            ),
            ''
        );

    v_device_external_id :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{device,external_id}'
                ),
                ''
            )
        );

    v_device_model_vendor :=
        NULLIF(
            btrim(
                p_request #>> '{device,model_vendor}'
            ),
            ''
        );

    v_device_model :=
        NULLIF(
            btrim(
                p_request #>> '{device,model}'
            ),
            ''
        );

    v_device_type :=
        NULLIF(
            btrim(
                p_request #>> '{device,device_type}'
            ),
            ''
        );

    BEGIN
        v_device_category_id :=
            NULLIF
            (
                btrim(
                    p_request #>>
                    '{device,device_category_id}'
                ),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'device.device_category_id must be a valid UUID';
    END;

    v_device_firmware_version :=
        NULLIF(
            btrim(
                p_request #>> '{device,firmware_version}'
            ),
            ''
        );

    v_device_protocol :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{device,protocol}'
                ),
                ''
            )
        );

    v_profile_code :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{device,profile_code}'
                ),
                ''
            )
        );

    IF v_device_mode = 'CREATE_NEW' THEN
        IF v_device_name IS NULL THEN
            RAISE EXCEPTION
                'device.name is required for CREATE_NEW';
        END IF;

        IF v_device_external_id IS NULL THEN
            RAISE EXCEPTION
                'device.external_id is required for CREATE_NEW';
        END IF;

        IF v_device_model_vendor IS NULL THEN
            RAISE EXCEPTION
                'device.model_vendor is required for CREATE_NEW';
        END IF;

        IF v_device_model IS NULL THEN
            RAISE EXCEPTION
                'device.model is required for CREATE_NEW';
        END IF;

        IF v_device_category_id IS NULL
           AND v_device_type IS NULL
        THEN
            RAISE EXCEPTION
                'device.device_category_id is required for CREATE_NEW';
        END IF;

        IF v_device_protocol IS NULL THEN
            RAISE EXCEPTION
                'device.protocol is required for CREATE_NEW';
        END IF;

        IF v_profile_code IS NULL THEN
            RAISE EXCEPTION
                'device.profile_code is required for CREATE_NEW';
        END IF;

    ELSE
        IF v_existing_device_id IS NULL THEN
            RAISE EXCEPTION
                'device.existing_device_id is required for USE_EXISTING';
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize external identifier fields.
    --
    -- CREATE_NEW device:
    --   Identifier type and value are mandatory.
    --
    -- USE_EXISTING device:
    --   Identifier fields are optional. When supplied, they are used only
    --   to verify an existing identifier already belongs to the selected
    --   device. They are never created, changed, or transferred.
    --------------------------------------------------------------------------

    v_identifier_type :=
        upper
        (
            NULLIF
            (
                btrim(
                    p_request #>> '{identifier,type}'
                ),
                ''
            )
        );

    v_identifier_value :=
        NULLIF
        (
            btrim(
                p_request #>> '{identifier,value}'
            ),
            ''
        );

    IF
    (
        v_identifier_type IS NULL
        AND v_identifier_value IS NOT NULL
    )
    OR
    (
        v_identifier_type IS NOT NULL
        AND v_identifier_value IS NULL
    )
    THEN
        RAISE EXCEPTION
            'identifier.type and identifier.value must be supplied together';
    END IF;

    IF v_device_mode = 'CREATE_NEW' THEN
        IF v_identifier_type IS NULL THEN
            RAISE EXCEPTION
                'identifier.type is required for a new device';
        END IF;

        IF v_identifier_value IS NULL THEN
            RAISE EXCEPTION
                'identifier.value is required for a new device';
        END IF;
    END IF;

    IF v_identifier_type = 'MQTT_UID' THEN
        v_identifier_value := lower(v_identifier_value);
    END IF;


    --------------------------------------------------------------------------
    -- Extract and normalize asset fields.
    --------------------------------------------------------------------------

    v_asset_mode :=
        upper
        (
            COALESCE
            (
                NULLIF(btrim(p_request #>> '{asset,mode}'), ''),
                'CREATE_NEW'
            )
        );

    IF v_asset_mode NOT IN ('CREATE_NEW', 'USE_EXISTING') THEN
        RAISE EXCEPTION
            'asset.mode must be CREATE_NEW or USE_EXISTING';
    END IF;

    BEGIN
        v_existing_asset_id :=
            NULLIF(
                btrim(p_request #>> '{asset,existing_asset_id}'),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'asset.existing_asset_id must be a valid UUID';
    END;

    v_asset_name :=
        NULLIF(btrim(p_request #>> '{asset,name}'), '');

    v_asset_external_id :=
        upper(
            NULLIF(
                btrim(
                    p_request #>> '{asset,external_id}'
                ),
                ''
            )
        );

    BEGIN
        v_asset_type_id :=
            NULLIF(
                btrim(p_request #>> '{asset,asset_type_id}'),
                ''
            )::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION 'asset.asset_type_id must be a valid UUID';
    END;

    v_relationship_type :=
        upper
        (
            COALESCE
            (
                NULLIF
                (
                    btrim
                    (
                        p_request #>> '{asset,relationship_type}'
                    ),
                    ''
                ),
                'PRIMARY_METER'
            )
        );

    v_asset_metadata :=
        COALESCE(p_request #> '{asset,metadata}', '{}'::JSONB);

    IF v_asset_mode = 'CREATE_NEW' THEN
        IF v_asset_name IS NULL THEN
            RAISE EXCEPTION
                'asset.name is required for CREATE_NEW';
        END IF;

        IF v_asset_external_id IS NULL THEN
            RAISE EXCEPTION
                'asset.external_id is required for CREATE_NEW';
        END IF;

        IF length(v_asset_external_id) > 100
           OR v_asset_external_id !~ '^[A-Z0-9][A-Z0-9_]*$'
        THEN
            RAISE EXCEPTION
                'asset.external_id must contain only uppercase letters, numbers, and underscores';
        END IF;

        IF v_asset_type_id IS NULL THEN
            RAISE EXCEPTION
                'asset.asset_type_id is required for CREATE_NEW';
        END IF;

        IF NOT EXISTS
        (
            SELECT 1
            FROM metadata.asset_types at
            WHERE at.id = v_asset_type_id
        )
        THEN
            RAISE EXCEPTION
                'Unknown asset type UUID: %',
                v_asset_type_id;
        END IF;
    ELSE
        IF v_existing_asset_id IS NULL THEN
            RAISE EXCEPTION
                'asset.existing_asset_id is required for USE_EXISTING';
        END IF;
    END IF;

    IF jsonb_typeof(v_asset_metadata) <> 'object' THEN
        RAISE EXCEPTION 'asset.metadata must be a JSON object';
    END IF;


    --------------------------------------------------------------------------
    -- Optional Grafana organization ID.
    --------------------------------------------------------------------------

    BEGIN
        v_grafana_org_id :=
            NULLIF(p_request ->> 'grafana_org_id', '')::BIGINT;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION 'grafana_org_id must be a positive integer';
    END;

    IF v_grafana_org_id IS NOT NULL
       AND v_grafana_org_id <= 0
    THEN
        RAISE EXCEPTION 'grafana_org_id must be greater than zero';
    END IF;


    --------------------------------------------------------------------------
    -- Organization selection or creation.
    --
    -- CREATE_NEW:
    --   Inserts a genuinely new organization and rejects an existing code.
    --
    -- USE_EXISTING:
    --   Loads the selected active organization without modifying it.
    --------------------------------------------------------------------------

    IF v_organization_mode = 'USE_EXISTING' THEN

        -- Serialize concurrent operations against the same organization UUID.
        PERFORM pg_advisory_xact_lock
        (
            hashtext(v_existing_organization_id::TEXT)
        );

        SELECT
            o.id,
            o.name,
            o.code,
            o.description
        INTO
            v_organization_id,
            v_organization_name,
            v_organization_code,
            v_organization_description
        FROM metadata.organizations o
        WHERE o.id = v_existing_organization_id
          AND o.is_active = TRUE;

        IF v_organization_id IS NULL THEN
            RAISE EXCEPTION
                'Existing active organization % was not found',
                v_existing_organization_id;
        END IF;

    ELSE

        -- Serialize concurrent creation attempts using the organization code.
        PERFORM pg_advisory_xact_lock
        (
            hashtext(v_organization_code)
        );

        BEGIN
            INSERT INTO metadata.organizations
            (
                name,
                code,
                description,
                is_active
            )
            VALUES
            (
                v_organization_name,
                v_organization_code,
                v_organization_description,
                TRUE
            )
            RETURNING id
            INTO v_organization_id;

        EXCEPTION
            WHEN unique_violation THEN
                RAISE EXCEPTION
                    'Organization code % already exists; use USE_EXISTING instead',
                    v_organization_code;
        END;
    END IF;


    --------------------------------------------------------------------------
    -- Site selection or creation.
    --
    -- CREATE_NEW:
    --   Inserts a new site under the resolved organization.
    --
    -- USE_EXISTING:
    --   Validates that the selected active site belongs to the resolved
    --   organization and preserves all stored site attributes.
    --------------------------------------------------------------------------

    IF v_site_mode = 'USE_EXISTING' THEN

        SELECT
            s.id,
            s.name,
            s.code,
            s.timezone,
            s.address
        INTO
            v_site_id,
            v_site_name,
            v_site_code,
            v_site_timezone,
            v_site_address
        FROM metadata.sites s
        WHERE s.id = v_existing_site_id
          AND s.organization_id = v_organization_id
          AND s.is_active = TRUE;

        IF v_site_id IS NULL THEN
            RAISE EXCEPTION
                'Existing active site % was not found under organization %',
                v_existing_site_id,
                v_organization_id;
        END IF;

    ELSE

        BEGIN
            INSERT INTO metadata.sites
            (
                organization_id,
                name,
                code,
                timezone,
                address,
                is_active
            )
            VALUES
            (
                v_organization_id,
                v_site_name,
                v_site_code,
                v_site_timezone,
                v_site_address,
                TRUE
            )
            RETURNING id
            INTO v_site_id;

        EXCEPTION
            WHEN unique_violation THEN
                RAISE EXCEPTION
                    'Site code % already exists under organization %; use USE_EXISTING instead',
                    v_site_code,
                    v_organization_id;
        END;
    END IF;


    --------------------------------------------------------------------------
    -- Optional physical hierarchy.
    --------------------------------------------------------------------------

    v_space_id := NULL;

    IF v_location_mode = 'USE_EXISTING_SPACE' THEN
        SELECT
            sp.id,
            f.id,
            b.id
        INTO
            v_space_id,
            v_floor_id,
            v_building_id
        FROM metadata.spaces sp
        JOIN metadata.floors f
          ON f.id = sp.floor_id
        JOIN metadata.buildings b
          ON b.id = f.building_id
        WHERE sp.id = v_existing_space_id
          AND sp.organization_id = v_organization_id
          AND b.site_id = v_site_id;

        IF v_space_id IS NULL THEN
            RAISE EXCEPTION
                'Existing space % was not found in organization % and site %',
                v_existing_space_id,
                v_organization_code,
                v_site_code;
        END IF;

    ELSIF v_location_mode = 'CREATE_LOCATION' THEN
        INSERT INTO metadata.buildings
        (
            organization_id,
            site_id,
            name,
            code
        )
        VALUES
        (
            v_organization_id,
            v_site_id,
            v_building_name,
            v_building_code
        )
        ON CONFLICT (site_id, code)
        DO UPDATE SET
            organization_id = EXCLUDED.organization_id,
            name            = EXCLUDED.name,
            updated_at      = now()
        RETURNING id
        INTO v_building_id;

        INSERT INTO metadata.floors
        (
            organization_id,
            building_id,
            name,
            code
        )
        VALUES
        (
            v_organization_id,
            v_building_id,
            v_floor_name,
            v_floor_code
        )
        ON CONFLICT (building_id, code)
        DO UPDATE SET
            organization_id = EXCLUDED.organization_id,
            name            = EXCLUDED.name,
            updated_at      = now()
        RETURNING id
        INTO v_floor_id;

        INSERT INTO metadata.spaces
        (
            organization_id,
            floor_id,
            name,
            code
        )
        VALUES
        (
            v_organization_id,
            v_floor_id,
            v_space_name,
            v_space_code
        )
        ON CONFLICT (floor_id, code)
        DO UPDATE SET
            organization_id = EXCLUDED.organization_id,
            name            = EXCLUDED.name,
            updated_at      = now()
        RETURNING id
        INTO v_space_id;
    END IF;


    --------------------------------------------------------------------------
    -- Gateway selection or creation.
    --
    -- CREATE_NEW:
    --   Resolves or creates the gateway model, then inserts a new gateway.
    --   The resolved physical space is assigned to gateway.space_id.
    --
    -- USE_EXISTING:
    --   Validates that the selected gateway belongs to the resolved
    --   organization and site. Existing gateway attributes are preserved.
    --------------------------------------------------------------------------

    IF v_gateway_mode = 'USE_EXISTING' THEN

        SELECT
            g.id,
            g.name,
            g.external_id,
            g.gateway_model_id
        INTO
            v_gateway_id,
            v_gateway_name,
            v_gateway_external_id,
            v_gateway_model_id
        FROM metadata.gateways g
        WHERE g.id = v_existing_gateway_id
          AND g.organization_id = v_organization_id
          AND g.site_id = v_site_id;

        IF v_gateway_id IS NULL THEN
            RAISE EXCEPTION
                'Existing gateway % was not found under organization % and site %',
                v_existing_gateway_id,
                v_organization_id,
                v_site_id;
        END IF;

    ELSE

        ----------------------------------------------------------------------
        -- Gateway model resolution.
        ----------------------------------------------------------------------

        SELECT gm.id
        INTO v_gateway_model_id
        FROM metadata.gateway_models gm
        WHERE lower(COALESCE(gm.vendor, '')) =
              lower(v_gateway_vendor)
          AND lower(gm.model) =
              lower(v_gateway_model)
        ORDER BY gm.created_at, gm.id
        LIMIT 1;

        IF v_gateway_model_id IS NULL THEN
            INSERT INTO metadata.gateway_models
            (
                vendor,
                model,
                protocol
            )
            VALUES
            (
                v_gateway_vendor,
                v_gateway_model,
                v_gateway_protocol
            )
            RETURNING id
            INTO v_gateway_model_id;
        END IF;

        BEGIN
            INSERT INTO metadata.gateways
            (
                organization_id,
                site_id,
                gateway_model_id,
                name,
                external_id,
                space_id
            )
            VALUES
            (
                v_organization_id,
                v_site_id,
                v_gateway_model_id,
                v_gateway_name,
                v_gateway_external_id,
                v_space_id
            )
            RETURNING id
            INTO v_gateway_id;

        EXCEPTION
            WHEN unique_violation THEN
                RAISE EXCEPTION
                    'Gateway external ID % already exists under organization %; use USE_EXISTING instead',
                    v_gateway_external_id,
                    v_organization_id;
        END;
    END IF;


    --------------------------------------------------------------------------
    -- Device selection or creation.
    --
    -- CREATE_NEW:
    --   Resolves the controlled category, relationship compatibility,
    --   device model, and active compatible profile before inserting.
    --
    -- USE_EXISTING:
    --   Validates that the selected device belongs to the resolved
    --   organization and gateway. Existing device attributes are preserved.
    --------------------------------------------------------------------------

    IF v_device_mode = 'USE_EXISTING' THEN

        SELECT
            d.id,
            d.name,
            d.external_id,
            d.device_model_id,
            d.firmware_version,
            d.protocol,
            d.profile_id,
            dm.device_category_id,
            dc.name,
            dp.profile_code
        INTO
            v_device_id,
            v_device_name,
            v_device_external_id,
            v_device_model_id,
            v_device_firmware_version,
            v_device_protocol,
            v_profile_id,
            v_device_category_id,
            v_device_category_name,
            v_profile_code
        FROM metadata.devices d
        LEFT JOIN metadata.device_models dm
          ON dm.id = d.device_model_id
        LEFT JOIN config.device_categories dc
          ON dc.id = dm.device_category_id
        LEFT JOIN config.device_profiles dp
          ON dp.id = d.profile_id
        WHERE d.id = v_existing_device_id
          AND d.organization_id = v_organization_id
          AND d.gateway_id = v_gateway_id;

        IF v_device_id IS NULL THEN
            RAISE EXCEPTION
                'Existing device % was not found under organization % and gateway %',
                v_existing_device_id,
                v_organization_id,
                v_gateway_id;
        END IF;

        IF v_device_category_id IS NULL
           OR v_device_category_name IS NULL
        THEN
            RAISE EXCEPTION
                'Existing device % does not have a controlled device category',
                v_existing_device_id;
        END IF;

        IF v_profile_id IS NULL
           OR v_profile_code IS NULL
        THEN
            RAISE EXCEPTION
                'Existing device % does not have an active onboarding profile',
                v_existing_device_id;
        END IF;

    ELSE

        ----------------------------------------------------------------------
        -- Controlled device category.
        ----------------------------------------------------------------------

        IF v_device_category_id IS NOT NULL THEN
            SELECT
                dc.id,
                dc.name
            INTO
                v_device_category_id,
                v_device_category_name
            FROM config.device_categories dc
            WHERE dc.id = v_device_category_id;
        ELSE
            SELECT
                dc.id,
                dc.name
            INTO
                v_device_category_id,
                v_device_category_name
            FROM config.device_categories dc
            WHERE lower(dc.name) = lower(v_device_type)
            ORDER BY dc.created_at, dc.id
            LIMIT 1;
        END IF;

        IF v_device_category_id IS NULL THEN
            RAISE EXCEPTION
                'Controlled device category was not found';
        END IF;

        -- Keep the legacy text value synchronized during the transition.
        v_device_type := v_device_category_name;


        ----------------------------------------------------------------------
        -- Controlled category-to-asset relationship compatibility.
        ----------------------------------------------------------------------

        IF v_device_category_name = 'Energy Meter' THEN
            IF v_relationship_type NOT IN
            (
                'PRIMARY_METER',
                'SECONDARY_METER',
                'SECONDARY_METER'
            )
            THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Environmental Sensor' THEN
            IF v_relationship_type NOT IN
            (
                'TEMPERATURE_SENSOR',
                'HUMIDITY_SENSOR'
            )
            THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Temperature Sensor' THEN
            IF v_relationship_type <> 'TEMPERATURE_SENSOR' THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Flow Meter' THEN
            IF v_relationship_type <> 'FLOW_SENSOR' THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Pressure Sensor' THEN
            IF v_relationship_type <> 'PRESSURE_SENSOR' THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Digital Input Module' THEN
            IF v_relationship_type NOT IN
            (
                'STATUS_INPUT',
                'RUN_STATUS',
                'FAULT_STATUS'
            )
            THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'BMS Controller' THEN
            IF v_relationship_type <> 'CONTROLLER' THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'PLC' THEN
            IF v_relationship_type NOT IN
            (
                'CONTROLLER',
                'STATUS_INPUT',
                'RUN_STATUS',
                'FAULT_STATUS'
            )
            THEN
                RAISE EXCEPTION
                    'Relationship % is not valid for device category %',
                    v_relationship_type,
                    v_device_category_name;
            END IF;

        ELSIF v_device_category_name = 'Gateway' THEN
            RAISE EXCEPTION
                'Device category Gateway cannot be attached directly to an asset';

        ELSE
            RAISE EXCEPTION
                'No asset relationship rules are configured for device category %',
                v_device_category_name;
        END IF;


        ----------------------------------------------------------------------
        -- Device model.
        ----------------------------------------------------------------------

        SELECT
            dm.id,
            dm.device_category_id
        INTO
            v_device_model_id,
            v_existing_model_category_id
        FROM metadata.device_models dm
        WHERE lower(COALESCE(dm.vendor, '')) =
              lower(v_device_model_vendor)
          AND lower(dm.model) =
              lower(v_device_model)
        ORDER BY dm.created_at, dm.id
        LIMIT 1;

        IF v_device_model_id IS NULL THEN
            INSERT INTO metadata.device_models
            (
                vendor,
                model,
                device_type,
                device_category_id
            )
            VALUES
            (
                v_device_model_vendor,
                v_device_model,
                v_device_type,
                v_device_category_id
            )
            RETURNING id
            INTO v_device_model_id;
        ELSE
            IF v_existing_model_category_id <> v_device_category_id THEN
                RAISE EXCEPTION
                    'Device model % / % already belongs to a different category',
                    v_device_model_vendor,
                    v_device_model;
            END IF;

            UPDATE metadata.device_models
            SET device_type = v_device_category_name
            WHERE id = v_device_model_id
              AND device_type IS DISTINCT FROM v_device_category_name;
        END IF;


        ----------------------------------------------------------------------
        -- Active payload profile.
        ----------------------------------------------------------------------

        SELECT dp.id
        INTO v_profile_id
        FROM config.device_profiles dp
        WHERE dp.profile_code = v_profile_code
          AND dp.is_active = TRUE;

        IF v_profile_id IS NULL THEN
            RAISE EXCEPTION
                'Active device profile not found: %',
                v_profile_code;
        END IF;

        IF NOT EXISTS
        (
            SELECT 1
            FROM config.device_profile_categories dpc
            WHERE dpc.profile_id = v_profile_id
              AND dpc.device_category_id = v_device_category_id
        )
        THEN
            RAISE EXCEPTION
                'Device profile % is not compatible with device category %',
                v_profile_code,
                v_device_category_name;
        END IF;


        ----------------------------------------------------------------------
        -- Insert new device.
        ----------------------------------------------------------------------

        BEGIN
            INSERT INTO metadata.devices
            (
                organization_id,
                gateway_id,
                device_model_id,
                name,
                external_id,
                serial_number,
                firmware_version,
                protocol,
                profile_id
            )
            VALUES
            (
                v_organization_id,
                v_gateway_id,
                v_device_model_id,
                v_device_name,
                v_device_external_id,
                NULL,
                v_device_firmware_version,
                v_device_protocol,
                v_profile_id
            )
            RETURNING id
            INTO v_device_id;

        EXCEPTION
            WHEN unique_violation THEN
                RAISE EXCEPTION
                    'Device external ID % already exists under organization %; use USE_EXISTING instead',
                    v_device_external_id,
                    v_organization_id;
        END;
    END IF;


    --------------------------------------------------------------------------
    -- Validate relationship compatibility for both new and existing devices.
    --------------------------------------------------------------------------

    IF v_device_category_name = 'Energy Meter' THEN
        IF v_relationship_type NOT IN
        (
            'PRIMARY_METER',
            'SECONDARY_METER',
            'SECONDARY_METER'
        )
        THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Environmental Sensor' THEN
        IF v_relationship_type NOT IN
        (
            'TEMPERATURE_SENSOR',
            'HUMIDITY_SENSOR'
        )
        THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Temperature Sensor' THEN
        IF v_relationship_type <> 'TEMPERATURE_SENSOR' THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Flow Meter' THEN
        IF v_relationship_type <> 'FLOW_SENSOR' THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Pressure Sensor' THEN
        IF v_relationship_type <> 'PRESSURE_SENSOR' THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Digital Input Module' THEN
        IF v_relationship_type NOT IN
        (
            'STATUS_INPUT',
            'RUN_STATUS',
            'FAULT_STATUS'
        )
        THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'BMS Controller' THEN
        IF v_relationship_type <> 'CONTROLLER' THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'PLC' THEN
        IF v_relationship_type NOT IN
        (
            'CONTROLLER',
            'STATUS_INPUT',
            'RUN_STATUS',
            'FAULT_STATUS'
        )
        THEN
            RAISE EXCEPTION
                'Relationship % is not valid for device category %',
                v_relationship_type,
                v_device_category_name;
        END IF;

    ELSIF v_device_category_name = 'Gateway' THEN
        RAISE EXCEPTION
            'Device category Gateway cannot be attached directly to an asset';

    ELSE
        RAISE EXCEPTION
            'No asset relationship rules are configured for device category %',
            v_device_category_name;
    END IF;


    --------------------------------------------------------------------------
    -- External device identifier.
    --
    -- CREATE_NEW:
    --   Creates the required external identifier only when it is not already
    --   owned by another device.
    --
    -- USE_EXISTING:
    --   Preserves all identifiers. Optional supplied values are verification
    --   inputs only and must already belong to the selected device.
    --------------------------------------------------------------------------

    IF v_device_mode = 'CREATE_NEW' THEN

        SELECT di.device_id
        INTO v_existing_identifier_device_id
        FROM metadata.device_identifiers di
        WHERE di.identifier_type = v_identifier_type
          AND
          (
              CASE
                  WHEN v_identifier_type = 'MQTT_UID'
                  THEN lower(di.identifier_value)
                  ELSE di.identifier_value
              END
          ) = v_identifier_value
        ORDER BY di.created_at, di.id
        LIMIT 1;

        IF v_existing_identifier_device_id IS NOT NULL THEN
            RAISE EXCEPTION
                'Identifier %:% is already assigned to device %',
                v_identifier_type,
                v_identifier_value,
                v_existing_identifier_device_id;
        END IF;

        INSERT INTO metadata.device_identifiers
        (
            device_id,
            identifier_type,
            identifier_value
        )
        VALUES
        (
            v_device_id,
            v_identifier_type,
            v_identifier_value
        );

    ELSIF v_identifier_type IS NOT NULL THEN

        SELECT di.device_id
        INTO v_existing_identifier_device_id
        FROM metadata.device_identifiers di
        WHERE di.identifier_type = v_identifier_type
          AND
          (
              CASE
                  WHEN v_identifier_type = 'MQTT_UID'
                  THEN lower(di.identifier_value)
                  ELSE di.identifier_value
              END
          ) = v_identifier_value
        ORDER BY di.created_at, di.id
        LIMIT 1;

        IF v_existing_identifier_device_id IS NULL THEN
            RAISE EXCEPTION
                'Identifier %:% does not exist for the selected device',
                v_identifier_type,
                v_identifier_value;
        END IF;

        IF v_existing_identifier_device_id <> v_device_id THEN
            RAISE EXCEPTION
                'Identifier %:% belongs to device %, not selected device %',
                v_identifier_type,
                v_identifier_value,
                v_existing_identifier_device_id,
                v_device_id;
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Asset selection or creation.
    --------------------------------------------------------------------------

    IF v_asset_mode = 'USE_EXISTING' THEN
        SELECT
            a.id,
            a.name,
            a.external_id,
            a.asset_type_id
        INTO
            v_asset_id,
            v_asset_name,
            v_asset_external_id,
            v_asset_type_id
        FROM metadata.assets a
        WHERE a.id = v_existing_asset_id
          AND a.organization_id = v_organization_id
          AND a.site_id = v_site_id;

        IF v_asset_id IS NULL THEN
            RAISE EXCEPTION
                'Existing asset % was not found in organization % and site %',
                v_existing_asset_id,
                v_organization_code,
                v_site_code;
        END IF;

    ELSE
        SELECT a.id
        INTO v_asset_id
        FROM metadata.assets a
        WHERE a.organization_id = v_organization_id
          AND a.site_id = v_site_id
          AND upper(btrim(a.external_id))
              = upper(btrim(v_asset_external_id))
        ORDER BY a.created_at, a.id
        LIMIT 1;

        IF v_asset_id IS NULL THEN
            INSERT INTO metadata.assets
            (
                organization_id,
                site_id,
                asset_type_id,
                parent_asset_id,
                name,
                external_id,
                manufacturer,
                model,
                serial_number,
                status,
                metadata,
                building_id,
                floor_id,
                space_id
            )
            VALUES
            (
                v_organization_id,
                v_site_id,
                v_asset_type_id,
                NULL,
                v_asset_name,
                v_asset_external_id,
                NULL,
                NULL,
                NULL,
                'active',
                v_asset_metadata,
                v_building_id,
                v_floor_id,
                v_space_id
            )
            RETURNING id
            INTO v_asset_id;
        ELSE
            UPDATE metadata.assets
            SET
                asset_type_id = v_asset_type_id,
                external_id   = v_asset_external_id,
                status        = 'active',
                metadata      = v_asset_metadata,
                building_id   = v_building_id,
                floor_id      = v_floor_id,
                space_id      = v_space_id,
                updated_at    = now()
            WHERE id = v_asset_id;
        END IF;
    END IF;


    --------------------------------------------------------------------------
    -- Asset-device relationship.
    --
    -- The canonical partial unique index allows a device to be PRIMARY_METER
    -- for at most one asset.
    --------------------------------------------------------------------------

    IF v_relationship_type = 'PRIMARY_METER' THEN
        SELECT ad.asset_id
        INTO v_existing_primary_asset_id
        FROM metadata.asset_devices ad
        WHERE ad.device_id = v_device_id
          AND ad.relationship_type = 'PRIMARY_METER'
        ORDER BY ad.created_at, ad.id
        LIMIT 1;

        IF v_existing_primary_asset_id IS NOT NULL
           AND v_existing_primary_asset_id <> v_asset_id
        THEN
            RAISE EXCEPTION
                'Device % is already PRIMARY_METER for asset %',
                v_device_id,
                v_existing_primary_asset_id;
        END IF;

        IF EXISTS
        (
            SELECT 1
            FROM metadata.asset_devices ad
            WHERE ad.asset_id = v_asset_id
              AND ad.relationship_type = 'PRIMARY_METER'
              AND ad.device_id <> v_device_id
        )
        THEN
            RAISE EXCEPTION
                'Asset % already has a different PRIMARY_METER',
                v_asset_id;
        END IF;
    END IF;

    INSERT INTO metadata.asset_devices
    (
        asset_id,
        device_id,
        relationship_type
    )
    VALUES
    (
        v_asset_id,
        v_device_id,
        v_relationship_type
    )
    ON CONFLICT
        (asset_id, device_id, relationship_type)
    DO NOTHING;


    --------------------------------------------------------------------------
    -- Optional Grafana organization mapping.
    --
    -- Reject both forms of cross-tenant reassignment:
    --
    --   1. EMS organization already mapped to a different Grafana org.
    --   2. Grafana org already mapped to a different EMS organization.
    --------------------------------------------------------------------------

    IF v_grafana_org_id IS NOT NULL THEN
        SELECT gom.grafana_org_id
        INTO v_existing_grafana_org_id
        FROM metadata.grafana_organization_map gom
        WHERE gom.organization_id = v_organization_id;

        IF v_existing_grafana_org_id IS NOT NULL
           AND v_existing_grafana_org_id <> v_grafana_org_id
        THEN
            RAISE EXCEPTION
                'EMS organization % is already mapped to Grafana org %',
                v_organization_id,
                v_existing_grafana_org_id;
        END IF;

        SELECT gom.organization_id
        INTO v_existing_grafana_org_owner
        FROM metadata.grafana_organization_map gom
        WHERE gom.grafana_org_id = v_grafana_org_id;

        IF v_existing_grafana_org_owner IS NOT NULL
           AND v_existing_grafana_org_owner <> v_organization_id
        THEN
            RAISE EXCEPTION
                'Grafana org % is already mapped to EMS organization %',
                v_grafana_org_id,
                v_existing_grafana_org_owner;
        END IF;

        INSERT INTO metadata.grafana_organization_map
        (
            grafana_org_id,
            organization_id,
            is_active
        )
        VALUES
        (
            v_grafana_org_id,
            v_organization_id,
            TRUE
        )
        ON CONFLICT (grafana_org_id)
        DO UPDATE SET
            organization_id = EXCLUDED.organization_id,
            is_active        = TRUE,
            updated_at       = now();
    END IF;


    --------------------------------------------------------------------------
    -- Build result and audit successful completion.
    --------------------------------------------------------------------------

    v_result :=
        jsonb_build_object
        (
            'organization_id',  v_organization_id,
            'organization_code', v_organization_code,
            'site_id',          v_site_id,
            'site_code',        v_site_code,
            'location_mode',    v_location_mode,
            'building_id',      v_building_id,
            'floor_id',         v_floor_id,
            'space_id',         v_space_id,
            'gateway_model_id', v_gateway_model_id,
            'gateway_id',       v_gateway_id,
            'device_model_id',  v_device_model_id,
            'device_category_id', v_device_category_id,
            'device_category_name', v_device_category_name,
            'profile_id',       v_profile_id,
            'profile_code',     v_profile_code,
            'device_id',        v_device_id,
            'device_external_id', v_device_external_id,
            'identifier_type',  v_identifier_type,
            'identifier_value', v_identifier_value,
            'asset_mode',       v_asset_mode,
            'asset_id',         v_asset_id,
            'asset_name',       v_asset_name,
            'relationship_type', v_relationship_type,
            'grafana_org_id',   v_grafana_org_id
        );

    INSERT INTO admin.onboarding_audit
    (
        requested_by,
        request_payload,
        result_payload
    )
    VALUES
    (
        COALESCE(NULLIF(btrim(p_requested_by), ''), current_user),
        p_request,
        v_result
    );

    RETURN v_result;
END;
$function$;

ALTER FUNCTION admin.onboard_energy_asset_legacy_upsert(JSONB, TEXT)
    OWNER TO ems_admin;

REVOKE ALL ON FUNCTION
    admin.onboard_energy_asset_legacy_upsert(JSONB, TEXT)
    FROM PUBLIC;

GRANT EXECUTE ON FUNCTION
    admin.onboard_energy_asset_legacy_upsert(JSONB, TEXT)
    TO ems_app;


-- ====================================================================
-- Historical migration: 143_scoped_identifier_recommendations.sql
-- ====================================================================

-- Migration 143
-- Allow duplicate Asset display names and provide scoped identifier
-- recommendations for onboarding.
--
-- Display names are descriptive labels and may repeat.
-- Codes and external IDs remain the stable machine identities.


DROP INDEX IF EXISTS metadata.uq_assets_root_name;
DROP INDEX IF EXISTS metadata.uq_assets_child_name;

CREATE OR REPLACE FUNCTION admin.recommend_available_identifier(
    p_entity_type TEXT,
    p_base_value TEXT,
    p_organization_id UUID DEFAULT NULL,
    p_site_id UUID DEFAULT NULL,
    p_building_id UUID DEFAULT NULL,
    p_floor_id UUID DEFAULT NULL,
    p_exclude_id UUID DEFAULT NULL
)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO pg_catalog, admin, metadata
AS $function$
DECLARE
    v_entity_type TEXT;
    v_base        TEXT;
    v_candidate   TEXT;
    v_suffix      INTEGER := 1;
    v_exists      BOOLEAN;
BEGIN
    v_entity_type := upper(btrim(coalesce(p_entity_type, '')));

    v_base := upper(
        trim(
            both '_' FROM
            regexp_replace(
                coalesce(nullif(btrim(p_base_value), ''), 'ITEM'),
                '[^A-Za-z0-9]+',
                '_',
                'g'
            )
        )
    );

    IF v_base = '' THEN
        v_base := 'ITEM';
    END IF;

    v_base := left(v_base, 100);
    v_candidate := v_base;

    IF v_entity_type NOT IN
    (
        'BUILDING',
        'FLOOR',
        'SPACE',
        'GATEWAY',
        'DEVICE',
        'ASSET'
    )
    THEN
        RAISE EXCEPTION
            'Unsupported identifier entity type: %',
            p_entity_type
            USING ERRCODE = '22023';
    END IF;

    LOOP
        v_exists :=
            CASE v_entity_type
                WHEN 'BUILDING' THEN EXISTS
                (
                    SELECT 1
                    FROM metadata.buildings b
                    WHERE b.site_id = p_site_id
                      AND upper(btrim(b.code))
                          = upper(btrim(v_candidate))
                      AND b.id IS DISTINCT FROM p_exclude_id
                )

                WHEN 'FLOOR' THEN EXISTS
                (
                    SELECT 1
                    FROM metadata.floors f
                    WHERE f.building_id = p_building_id
                      AND upper(btrim(f.code))
                          = upper(btrim(v_candidate))
                      AND f.id IS DISTINCT FROM p_exclude_id
                )

                WHEN 'SPACE' THEN EXISTS
                (
                    SELECT 1
                    FROM metadata.spaces s
                    WHERE s.floor_id = p_floor_id
                      AND upper(btrim(s.code))
                          = upper(btrim(v_candidate))
                      AND s.id IS DISTINCT FROM p_exclude_id
                )

                WHEN 'GATEWAY' THEN EXISTS
                (
                    SELECT 1
                    FROM metadata.gateways g
                    WHERE g.organization_id = p_organization_id
                      AND upper(btrim(g.external_id))
                          = upper(btrim(v_candidate))
                      AND g.id IS DISTINCT FROM p_exclude_id
                )

                WHEN 'DEVICE' THEN EXISTS
                (
                    SELECT 1
                    FROM metadata.devices d
                    WHERE d.organization_id = p_organization_id
                      AND upper(btrim(d.external_id))
                          = upper(btrim(v_candidate))
                      AND d.id IS DISTINCT FROM p_exclude_id
                )

                WHEN 'ASSET' THEN EXISTS
                (
                    SELECT 1
                    FROM metadata.assets a
                    WHERE a.organization_id = p_organization_id
                      AND a.site_id = p_site_id
                      AND upper(btrim(a.external_id))
                          = upper(btrim(v_candidate))
                      AND a.id IS DISTINCT FROM p_exclude_id
                )

                ELSE FALSE
            END;

        EXIT WHEN NOT v_exists;

        v_suffix := v_suffix + 1;

        v_candidate :=
            left(
                v_base,
                100 - length(v_suffix::text) - 1
            )
            || '_'
            || v_suffix::text;
    END LOOP;

    RETURN v_candidate;
END;
$function$;

