-- Migration 163
-- Align the strict onboarding wrapper with the established system-generated
-- identifier contract. Gateway, device, and asset external IDs are resolved by
-- the canonical writer through admin.recommend_available_identifier(). Building
-- codes are adjusted before the writer is called. Human display-name conflicts
-- and physical telemetry identifier conflicts remain strict.

CREATE OR REPLACE FUNCTION admin.onboard_energy_asset(
    p_request jsonb,
    p_requested_by text DEFAULT CURRENT_USER
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, admin, metadata, config
AS $$
DECLARE
    v_org_mode text := upper(coalesce(nullif(btrim(p_request #>> '{organization,mode}'), ''), 'CREATE_NEW'));
    v_site_mode text := upper(coalesce(nullif(btrim(p_request #>> '{site,mode}'), ''), 'CREATE_NEW'));
    v_location_mode text := upper(coalesce(nullif(btrim(p_request #>> '{location,mode}'), ''), 'SITE_ONLY'));
    v_gateway_mode text := upper(coalesce(nullif(btrim(p_request #>> '{gateway,mode}'), ''), 'CREATE_NEW'));
    v_device_mode text := upper(coalesce(nullif(btrim(p_request #>> '{device,mode}'), ''), 'CREATE_NEW'));
    v_asset_mode text := upper(coalesce(nullif(btrim(p_request #>> '{asset,mode}'), ''), 'CREATE_NEW'));

    v_org_id uuid;
    v_site_id uuid;
    v_building_id uuid;
    v_floor_id uuid;
    v_gateway_id uuid;
    v_device_id uuid;
    v_asset_id uuid;

    v_org_name text := nullif(btrim(p_request #>> '{organization,name}'), '');
    v_org_code text := upper(nullif(btrim(p_request #>> '{organization,code}'), ''));
    v_site_name text := nullif(btrim(p_request #>> '{site,name}'), '');
    v_site_code text := upper(nullif(btrim(p_request #>> '{site,code}'), ''));
    v_building_name text := nullif(btrim(p_request #>> '{location,building_name}'), '');
    v_building_code text := upper(nullif(btrim(p_request #>> '{location,building_code}'), ''));
    v_floor_name text := nullif(btrim(p_request #>> '{location,floor_name}'), '');
    v_floor_code text := upper(nullif(btrim(p_request #>> '{location,floor_code}'), ''));
    v_space_name text := nullif(btrim(p_request #>> '{location,space_name}'), '');
    v_space_code text := upper(nullif(btrim(p_request #>> '{location,space_code}'), ''));
    v_gateway_external_id text := upper(nullif(btrim(p_request #>> '{gateway,external_id}'), ''));
    v_device_external_id text := upper(nullif(btrim(p_request #>> '{device,external_id}'), ''));
    v_identifier_type text := upper(nullif(btrim(p_request #>> '{device,identifier,type}'), ''));
    v_identifier_value text := nullif(btrim(p_request #>> '{device,identifier,value}'), '');
    v_asset_name text := nullif(btrim(p_request #>> '{asset,name}'), '');
    v_relationship_type text := upper(nullif(btrim(p_request #>> '{asset,relationship_type}'), ''));
    v_result jsonb;
BEGIN
    IF p_request IS NULL OR jsonb_typeof(p_request) <> 'object' THEN
        RAISE EXCEPTION 'Onboarding request must be a JSON object'
            USING ERRCODE = '22023';
    END IF;

    BEGIN
        v_org_id := nullif(coalesce(
            p_request #>> '{organization,id}',
            p_request #>> '{organization,existing_organization_id}'
        ), '')::uuid;
        v_site_id := nullif(coalesce(
            p_request #>> '{site,id}',
            p_request #>> '{site,existing_site_id}'
        ), '')::uuid;
        v_gateway_id := nullif(coalesce(
            p_request #>> '{gateway,id}',
            p_request #>> '{gateway,existing_gateway_id}'
        ), '')::uuid;
        v_device_id := nullif(coalesce(
            p_request #>> '{device,id}',
            p_request #>> '{device,existing_device_id}'
        ), '')::uuid;
        v_asset_id := nullif(coalesce(
            p_request #>> '{asset,id}',
            p_request #>> '{asset,existing_asset_id}'
        ), '')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'One or more selected records are invalid.'
            USING ERRCODE = '22023';
    END;

    -- Serialize competing interactive creates by natural identity. This closes
    -- the race between duplicate preflight and the existing writer.
    IF v_org_mode = 'CREATE_NEW' THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('onboarding:org:code:' || coalesce(v_org_code, ''), 0));
        PERFORM pg_advisory_xact_lock(hashtextextended('onboarding:org:name:' || lower(coalesce(v_org_name, '')), 0));

        IF EXISTS (SELECT 1 FROM metadata.organizations o WHERE upper(btrim(o.code)) = v_org_code) THEN
            RAISE EXCEPTION 'An organization with code % already exists. Choose Use existing organization.', v_org_code
                USING ERRCODE = '23505', CONSTRAINT = 'onboarding_organization_code_unique';
        END IF;
        IF EXISTS (SELECT 1 FROM metadata.organizations o WHERE lower(btrim(o.name)) = lower(v_org_name)) THEN
            RAISE EXCEPTION 'An organization named % already exists. Choose Use existing organization.', v_org_name
                USING ERRCODE = '23505', CONSTRAINT = 'onboarding_organization_name_unique';
        END IF;
    ELSIF v_org_id IS NULL THEN
        RAISE EXCEPTION 'Select an existing organization.' USING ERRCODE = '22023';
    END IF;

    IF v_site_mode = 'CREATE_NEW' AND v_org_mode = 'USE_EXISTING' THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('onboarding:site:code:' || v_org_id::text || ':' || coalesce(v_site_code, ''), 0));
        PERFORM pg_advisory_xact_lock(hashtextextended('onboarding:site:name:' || v_org_id::text || ':' || lower(coalesce(v_site_name, '')), 0));
        IF EXISTS (SELECT 1 FROM metadata.sites s WHERE s.organization_id = v_org_id AND upper(btrim(s.code)) = v_site_code) THEN
            RAISE EXCEPTION 'A site with code % already exists in this organization. Choose Use existing site.', v_site_code
                USING ERRCODE = '23505', CONSTRAINT = 'onboarding_site_code_unique';
        END IF;
        IF EXISTS (SELECT 1 FROM metadata.sites s WHERE s.organization_id = v_org_id AND lower(btrim(s.name)) = lower(v_site_name)) THEN
            RAISE EXCEPTION 'A site named % already exists in this organization. Choose Use existing site.', v_site_name
                USING ERRCODE = '23505', CONSTRAINT = 'onboarding_site_name_unique';
        END IF;
    ELSIF v_site_mode = 'USE_EXISTING' AND v_site_id IS NULL THEN
        RAISE EXCEPTION 'Select an existing site.' USING ERRCODE = '22023';
    END IF;

    IF v_location_mode = 'CREATE_LOCATION' AND v_site_mode = 'USE_EXISTING' THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('onboarding:building:code:' || v_site_id::text || ':' || coalesce(v_building_code, ''), 0));
        -- Building codes are system-generated identifiers. Resolve a collision
        -- instead of rejecting the onboarding transaction. Duplicate display
        -- names remain a deliberate USE_EXISTING decision below.
        v_building_code := admin.recommend_available_identifier(
            'BUILDING',
            v_building_code,
            v_org_id,
            v_site_id,
            NULL,
            NULL,
            NULL
        );
        p_request := jsonb_set(
            p_request,
            '{location,building_code}',
            to_jsonb(v_building_code),
            true
        );
        IF EXISTS (SELECT 1 FROM metadata.buildings b WHERE b.site_id = v_site_id AND lower(btrim(b.name)) = lower(v_building_name)) THEN
            RAISE EXCEPTION 'A building named % already exists at this site. Choose the existing location.', v_building_name
                USING ERRCODE = '23505', CONSTRAINT = 'onboarding_building_name_unique';
        END IF;
    END IF;

    IF v_gateway_mode = 'CREATE_NEW' AND v_org_mode = 'USE_EXISTING' THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('onboarding:gateway:external:' || v_org_id::text || ':' || coalesce(v_gateway_external_id, ''), 0));
        -- Gateway external IDs are system-generated by the canonical writer.
        -- The writer resolves collisions with recommend_available_identifier().
        -- Keep the advisory lock so competing creates serialize safely.
    ELSIF v_gateway_mode = 'USE_EXISTING' AND v_gateway_id IS NULL THEN
        RAISE EXCEPTION 'Select an existing gateway.' USING ERRCODE = '22023';
    END IF;

    IF v_device_mode = 'CREATE_NEW' THEN
        IF v_org_mode = 'USE_EXISTING' THEN
            PERFORM pg_advisory_xact_lock(hashtextextended('onboarding:device:external:' || v_org_id::text || ':' || coalesce(v_device_external_id, ''), 0));
            -- Device external IDs are system-generated by the canonical writer.
            -- The writer resolves collisions with recommend_available_identifier().
            -- Device telemetry identifiers remain strict and are checked below.
        END IF;

        PERFORM pg_advisory_xact_lock(hashtextextended('onboarding:device:identifier:' || coalesce(v_identifier_type, '') || ':' || lower(coalesce(v_identifier_value, '')), 0));
        IF EXISTS (
            SELECT 1 FROM metadata.device_identifiers di
            WHERE upper(di.identifier_type) = v_identifier_type
              AND CASE WHEN v_identifier_type = 'MQTT_UID'
                       THEN lower(di.identifier_value) = lower(v_identifier_value)
                       ELSE di.identifier_value = v_identifier_value END
        ) THEN
            RAISE EXCEPTION 'Device identifier %:% already exists. Choose the existing device.', v_identifier_type, v_identifier_value
                USING ERRCODE = '23505', CONSTRAINT = 'onboarding_device_identifier_unique';
        END IF;
    ELSIF v_device_id IS NULL THEN
        RAISE EXCEPTION 'Select an existing device.' USING ERRCODE = '22023';
    END IF;

    IF v_asset_mode = 'CREATE_NEW' AND v_org_mode = 'USE_EXISTING' AND v_site_mode = 'USE_EXISTING' THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('onboarding:asset:name:' || v_org_id::text || ':' || v_site_id::text || ':' || lower(coalesce(v_asset_name, '')), 0));
        IF EXISTS (
            SELECT 1 FROM metadata.assets a
            WHERE a.organization_id = v_org_id
              AND a.site_id = v_site_id
              AND a.parent_asset_id IS NULL
              AND lower(btrim(a.name)) = lower(v_asset_name)
        ) THEN
            RAISE EXCEPTION 'An asset named % already exists at this site. Choose Use existing asset.', v_asset_name
                USING ERRCODE = '23505', CONSTRAINT = 'onboarding_asset_name_unique';
        END IF;
    ELSIF v_asset_mode = 'USE_EXISTING' AND v_asset_id IS NULL THEN
        RAISE EXCEPTION 'Select an existing asset.' USING ERRCODE = '22023';
    END IF;

    IF v_asset_mode = 'USE_EXISTING' AND v_device_mode = 'USE_EXISTING' AND EXISTS (
        SELECT 1 FROM metadata.asset_devices ad
        WHERE ad.asset_id = v_asset_id
          AND ad.device_id = v_device_id
          AND ad.relationship_type = v_relationship_type
    ) THEN
        RAISE EXCEPTION 'This device already has the selected relationship with this asset.'
            USING ERRCODE = '23505', CONSTRAINT = 'onboarding_asset_device_relationship_unique';
    END IF;

    v_result := admin.onboard_energy_asset_legacy_upsert(p_request, p_requested_by);

    RETURN v_result || jsonb_build_object(
        'entity_outcomes', jsonb_build_object(
            'organization', CASE WHEN v_org_mode = 'CREATE_NEW' THEN 'CREATED' ELSE 'USED_EXISTING' END,
            'site', CASE WHEN v_site_mode = 'CREATE_NEW' THEN 'CREATED' ELSE 'USED_EXISTING' END,
            'location', CASE WHEN v_location_mode = 'CREATE_LOCATION' THEN 'CREATED'
                             WHEN v_location_mode = 'USE_EXISTING_SPACE' THEN 'USED_EXISTING'
                             ELSE 'SITE_ONLY' END,
            'gateway', CASE WHEN v_gateway_mode = 'CREATE_NEW' THEN 'CREATED' ELSE 'USED_EXISTING' END,
            'device', CASE WHEN v_device_mode = 'CREATE_NEW' THEN 'CREATED' ELSE 'USED_EXISTING' END,
            'asset', CASE WHEN v_asset_mode = 'CREATE_NEW' THEN 'CREATED' ELSE 'USED_EXISTING' END
        )
    );
END;
$$;


ALTER FUNCTION admin.onboard_energy_asset(jsonb,text) OWNER TO ems_admin;
REVOKE ALL ON FUNCTION admin.onboard_energy_asset(jsonb,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION admin.onboard_energy_asset(jsonb,text) TO ems_app;

COMMENT ON FUNCTION admin.onboard_energy_asset(jsonb,text) IS
    'Strict atomic onboarding contract: rejects duplicate human/telemetry identity while automatically resolving collisions in system-generated codes and external IDs.';


-- ====================================================================
-- Historical migration: 164_gateway_connectivity_from_assigned_device_telemetry.sql
-- ====================================================================

-- Gateway connectivity from either explicit device-status events or recent normalized telemetry.
-- A gateway is considered seen when any assigned device has produced mapped telemetry.

CREATE OR REPLACE VIEW analytics.v_gateway_connectivity
WITH (security_barrier = TRUE)
AS
WITH status_seen AS (
    SELECT
        ds.gateway_id,
        max(coalesce(ds.last_successful_communication, ds.source_timestamp, ds.received_at)) AS last_seen_at
    FROM telemetry.device_status ds
    WHERE ds.gateway_id IS NOT NULL
    GROUP BY ds.gateway_id
), telemetry_seen AS (
    SELECT
        d.gateway_id,
        max(coalesce(np.platform_received_at, np.created_at)) AS last_seen_at
    FROM metadata.devices d
    JOIN telemetry.normalized_points np
      ON np.device_id = d.id
    WHERE d.gateway_id IS NOT NULL
    GROUP BY d.gateway_id
)
SELECT
    g.id AS gateway_id,
    ss.last_seen_at AS status_last_seen_at,
    ts.last_seen_at AS telemetry_last_seen_at,
    greatest(ss.last_seen_at, ts.last_seen_at) AS last_seen_at,
    CASE
        WHEN ss.last_seen_at IS NULL AND ts.last_seen_at IS NULL THEN NULL
        WHEN ts.last_seen_at IS NULL THEN 'DEVICE_STATUS'
        WHEN ss.last_seen_at IS NULL THEN 'NORMALIZED_TELEMETRY'
        WHEN ts.last_seen_at >= ss.last_seen_at THEN 'NORMALIZED_TELEMETRY'
        ELSE 'DEVICE_STATUS'
    END AS last_seen_source
FROM metadata.gateways g
LEFT JOIN status_seen ss ON ss.gateway_id = g.id
LEFT JOIN telemetry_seen ts ON ts.gateway_id = g.id;

COMMENT ON VIEW analytics.v_gateway_connectivity IS
'Canonical gateway last-seen evidence from explicit device-status events or mapped normalized telemetry received from assigned devices.';

ALTER VIEW analytics.v_gateway_connectivity OWNER TO ems_admin;
REVOKE ALL ON analytics.v_gateway_connectivity FROM PUBLIC;
GRANT SELECT ON analytics.v_gateway_connectivity TO ems_app, ems_readonly, grafana_reader;

CREATE OR REPLACE VIEW analytics.v_commissioning_readiness
WITH (security_barrier = TRUE)
AS
WITH asset_readiness AS (
    SELECT
        'ASSET'::text AS entity_type,
        a.id AS entity_id,
        a.organization_id,
        a.site_id,
        a.name AS entity_name,
        a.lifecycle_status,
        CASE
            WHEN a.lifecycle_status = 'ACTIVE' THEN 'COMMISSIONED'
            WHEN a.lifecycle_status = 'COMMISSIONING' THEN 'IN_PROGRESS'
            WHEN a.lifecycle_status = 'DECOMMISSIONED' THEN 'FAILED'
            WHEN c.coverage_status IN ('MISSING_DIRECT_METER', 'UNKNOWN_POLICY') THEN 'BLOCKED'
            ELSE 'READY'
        END AS commissioning_status,
        (
            a.lifecycle_status <> 'DECOMMISSIONED'
            AND (
                a.lifecycle_status = 'ACTIVE'
                OR a.metering_requirement IN ('NOT_REQUIRED', 'DESCENDANT_COVERAGE_ALLOWED')
                OR (
                    a.metering_requirement = 'DIRECT_METER_REQUIRED'
                    AND c.coverage_status = 'CONFIGURED'
                )
            )
        ) AS is_ready,
        ARRAY_REMOVE(ARRAY[
            CASE WHEN a.lifecycle_status = 'DECOMMISSIONED' THEN 'ASSET_DECOMMISSIONED' END,
            CASE WHEN a.metering_requirement IS NULL THEN 'METERING_POLICY_MISSING' END,
            CASE
                WHEN a.metering_requirement = 'DIRECT_METER_REQUIRED'
                 AND c.coverage_status IS DISTINCT FROM 'CONFIGURED'
                THEN 'QUALIFYING_PRIMARY_METER_REQUIRED'
            END
        ], NULL)::text[] AS blocking_reason_codes,
        ARRAY_REMOVE(ARRAY[
            CASE
                WHEN a.metering_requirement = 'DESCENDANT_COVERAGE_ALLOWED'
                 AND c.coverage_status IN ('NO_REQUIRED_DESCENDANTS', 'PARTIALLY_CONFIGURED', 'MISSING_DESCENDANT_COVERAGE')
                THEN c.coverage_status
            END
        ], NULL)::text[] AS warning_reason_codes
    FROM metadata.assets a
    LEFT JOIN analytics.v_asset_meter_coverage_configuration c
      ON c.asset_id = a.id
),
gateway_last_seen AS (
    SELECT gateway_id, last_seen_at
    FROM analytics.v_gateway_connectivity
),
gateway_readiness AS (
    SELECT
        'GATEWAY'::text AS entity_type,
        g.id AS entity_id,
        g.organization_id,
        g.site_id,
        g.name AS entity_name,
        g.lifecycle_status,
        CASE
            WHEN g.lifecycle_status = 'ACTIVE' THEN 'COMMISSIONED'
            WHEN g.lifecycle_status = 'COMMISSIONING' THEN 'IN_PROGRESS'
            WHEN g.lifecycle_status = 'DECOMMISSIONED' THEN 'FAILED'
            WHEN nullif(btrim(g.external_id), '') IS NULL OR g.gateway_model_id IS NULL THEN 'BLOCKED'
            WHEN gls.last_seen_at IS NULL THEN 'BLOCKED'
            WHEN gls.last_seen_at < now() - make_interval(secs => gcp.online_threshold_seconds) THEN 'BLOCKED'
            ELSE 'READY'
        END AS commissioning_status,
        (
            g.lifecycle_status = 'ACTIVE'
            OR (
                g.lifecycle_status <> 'DECOMMISSIONED'
                AND nullif(btrim(g.external_id), '') IS NOT NULL
                AND g.gateway_model_id IS NOT NULL
                AND gls.last_seen_at >= now() - make_interval(secs => gcp.online_threshold_seconds)
            )
        ) AS is_ready,
        ARRAY_REMOVE(ARRAY[
            CASE WHEN g.lifecycle_status = 'DECOMMISSIONED' THEN 'GATEWAY_DECOMMISSIONED' END,
            CASE WHEN nullif(btrim(g.external_id), '') IS NULL THEN 'GATEWAY_IDENTITY_MISSING' END,
            CASE WHEN g.gateway_model_id IS NULL THEN 'GATEWAY_MODEL_MISSING' END,
            CASE WHEN g.lifecycle_status <> 'ACTIVE' AND gls.last_seen_at IS NULL THEN 'GATEWAY_NEVER_SEEN' END,
            CASE WHEN g.lifecycle_status <> 'ACTIVE' AND gls.last_seen_at IS NOT NULL AND gls.last_seen_at < now() - make_interval(secs => gcp.online_threshold_seconds) THEN 'GATEWAY_CONNECTIVITY_OFFLINE' END
        ], NULL)::text[] AS blocking_reason_codes,
        ARRAY_REMOVE(ARRAY[
            CASE WHEN g.lifecycle_status = 'ACTIVE' AND gls.last_seen_at IS NULL THEN 'GATEWAY_CURRENTLY_NEVER_SEEN' END,
            CASE WHEN g.lifecycle_status = 'ACTIVE' AND gls.last_seen_at IS NOT NULL AND gls.last_seen_at < now() - make_interval(secs => gcp.online_threshold_seconds) THEN 'GATEWAY_CURRENTLY_OFFLINE' END
        ], NULL)::text[] AS warning_reason_codes
    FROM metadata.gateways g
    CROSS JOIN config.gateway_connectivity_policy gcp
    LEFT JOIN gateway_last_seen gls ON gls.gateway_id = g.id
),
device_required_points AS (
    SELECT
        d.id AS device_id,
        count(DISTINCT pfm.logical_point_id) FILTER (WHERE pfm.is_required) AS required_point_count,
        count(DISTINCT np.logical_point_id) FILTER (
            WHERE pfm.is_required
              AND np.logical_point_id IS NOT NULL
        ) AS validated_required_point_count
    FROM metadata.devices d
    LEFT JOIN config.profile_field_mapping pfm
      ON pfm.profile_id = d.profile_id
    LEFT JOIN telemetry.normalized_points np
      ON np.device_id = d.id
     AND np.logical_point_id = pfm.logical_point_id
     AND coalesce(np.quality_code, 'GOOD') NOT IN ('INVALID', 'REJECTED')
     AND (np.numeric_value IS NOT NULL OR nullif(btrim(np.raw_value), '') IS NOT NULL)
    GROUP BY d.id
),
device_readiness AS (
    SELECT
        'DEVICE'::text AS entity_type,
        d.id AS entity_id,
        d.organization_id,
        g.site_id,
        d.name AS entity_name,
        d.lifecycle_status,
        CASE
            WHEN d.lifecycle_status = 'ACTIVE' THEN 'COMMISSIONED'
            WHEN d.lifecycle_status = 'COMMISSIONING' THEN 'IN_PROGRESS'
            WHEN d.lifecycle_status = 'DECOMMISSIONED' THEN 'FAILED'
            WHEN d.gateway_id IS NULL OR d.device_model_id IS NULL OR d.profile_id IS NULL THEN 'BLOCKED'
            WHEN NOT EXISTS (
                SELECT 1
                FROM config.device_profile_categories dpc
                JOIN metadata.device_models dm ON dm.id = d.device_model_id
                WHERE dpc.profile_id = d.profile_id
                  AND dpc.device_category_id = dm.device_category_id
            ) THEN 'BLOCKED'
            WHEN drp.validated_required_point_count < drp.required_point_count THEN 'BLOCKED'
            WHEN d.operational_policy = 'ASSET_ASSIGNED'
             AND NOT EXISTS (
                SELECT 1 FROM metadata.asset_devices ad WHERE ad.device_id = d.id
             ) THEN 'BLOCKED'
            ELSE 'READY'
        END AS commissioning_status,
        (
            d.lifecycle_status = 'ACTIVE'
            OR (
                d.lifecycle_status <> 'DECOMMISSIONED'
                AND d.gateway_id IS NOT NULL
                AND d.device_model_id IS NOT NULL
                AND d.profile_id IS NOT NULL
                AND EXISTS (
                    SELECT 1
                    FROM config.device_profile_categories dpc
                    JOIN metadata.device_models dm ON dm.id = d.device_model_id
                    WHERE dpc.profile_id = d.profile_id
                      AND dpc.device_category_id = dm.device_category_id
                )
                AND drp.validated_required_point_count = drp.required_point_count
                AND (
                    d.operational_policy <> 'ASSET_ASSIGNED'
                    OR EXISTS (
                        SELECT 1 FROM metadata.asset_devices ad WHERE ad.device_id = d.id
                    )
                )
            )
        ) AS is_ready,
        ARRAY_REMOVE(ARRAY[
            CASE WHEN d.lifecycle_status = 'DECOMMISSIONED' THEN 'DEVICE_DECOMMISSIONED' END,
            CASE WHEN d.gateway_id IS NULL THEN 'GATEWAY_REQUIRED' END,
            CASE WHEN d.device_model_id IS NULL THEN 'DEVICE_MODEL_REQUIRED' END,
            CASE WHEN d.profile_id IS NULL THEN 'DEVICE_PROFILE_REQUIRED' END,
            CASE
                WHEN d.device_model_id IS NOT NULL
                 AND d.profile_id IS NOT NULL
                 AND NOT EXISTS (
                    SELECT 1
                    FROM config.device_profile_categories dpc
                    JOIN metadata.device_models dm ON dm.id = d.device_model_id
                    WHERE dpc.profile_id = d.profile_id
                      AND dpc.device_category_id = dm.device_category_id
                 )
                THEN 'PROFILE_CATEGORY_INCOMPATIBLE'
            END,
            CASE
                WHEN coalesce(drp.required_point_count, 0) > 0
                 AND drp.validated_required_point_count < drp.required_point_count
                THEN 'REQUIRED_TELEMETRY_POINTS_NOT_VALIDATED'
            END,
            CASE
                WHEN d.operational_policy = 'ASSET_ASSIGNED'
                 AND NOT EXISTS (SELECT 1 FROM metadata.asset_devices ad WHERE ad.device_id = d.id)
                THEN 'ASSET_ASSIGNMENT_REQUIRED_BY_POLICY'
            END
        ], NULL)::text[] AS blocking_reason_codes,
        ARRAY[]::text[] AS warning_reason_codes
    FROM metadata.devices d
    LEFT JOIN metadata.gateways g ON g.id = d.gateway_id
    LEFT JOIN device_required_points drp ON drp.device_id = d.id
)
SELECT * FROM asset_readiness
UNION ALL
SELECT * FROM gateway_readiness
UNION ALL
SELECT * FROM device_readiness;



CREATE OR REPLACE FUNCTION admin.get_gateway_workspace
(
    p_actor_portal_user_id BIGINT,
    p_gateway_id UUID
)
RETURNS JSONB
LANGUAGE SQL
SECURITY DEFINER
STABLE
SET search_path TO pg_catalog, admin, analytics, metadata, telemetry, config
AS $function$
WITH gateway_row AS (
    SELECT
        g.id AS gateway_id,
        g.organization_id,
        o.code AS organization_code,
        o.name AS organization_name,
        g.site_id,
        s.code AS site_code,
        s.name AS site_name,
        g.building_id,
        b.name AS building_name,
        g.floor_id,
        f.name AS floor_name,
        g.space_id,
        sp.name AS space_name,
        g.gateway_model_id,
        gm.vendor AS gateway_vendor,
        gm.model AS gateway_model,
        gm.protocol AS gateway_protocol,
        g.name AS gateway_name,
        g.external_id,
        g.lifecycle_status,
        g.created_at,
        (SELECT count(*) FROM metadata.devices d WHERE d.gateway_id=g.id) AS device_count,
        (SELECT gc.last_seen_at
           FROM analytics.v_gateway_connectivity gc WHERE gc.gateway_id=g.id) AS last_seen_at,
        (SELECT online_threshold_seconds FROM config.gateway_connectivity_policy WHERE policy_id=1) AS threshold
    FROM metadata.gateways g
    JOIN metadata.organizations o ON o.id=g.organization_id
    JOIN metadata.sites s ON s.id=g.site_id
    LEFT JOIN metadata.gateway_models gm ON gm.id=g.gateway_model_id
    LEFT JOIN metadata.buildings b ON b.id=g.building_id
    LEFT JOIN metadata.floors f ON f.id=g.floor_id
    LEFT JOIN metadata.spaces sp ON sp.id=g.space_id
    WHERE g.id=p_gateway_id
      AND admin.portal_user_can_access_site(p_actor_portal_user_id,g.site_id)
)
SELECT jsonb_build_object(
    'gateway_id',gateway_id,'organization_id',organization_id,
    'organization_code',organization_code,'organization_name',organization_name,
    'site_id',site_id,'site_code',site_code,'site_name',site_name,
    'building_id',building_id,'building_name',building_name,
    'floor_id',floor_id,'floor_name',floor_name,'space_id',space_id,'space_name',space_name,
    'gateway_model_id',gateway_model_id,'gateway_vendor',gateway_vendor,
    'gateway_model',gateway_model,'gateway_protocol',gateway_protocol,
    'gateway_name',gateway_name,'external_id',external_id,
    'lifecycle_status',lifecycle_status,'created_at',created_at,
    'device_count',device_count,'last_seen_at',last_seen_at,
    'connectivity_status',CASE WHEN last_seen_at IS NULL THEN 'NEVER_SEEN'
      WHEN last_seen_at >= now()-make_interval(secs=>threshold) THEN 'ONLINE' ELSE 'OFFLINE' END
)
FROM gateway_row;
$function$;


DROP FUNCTION IF EXISTS admin.list_accessible_gateways(BIGINT);
CREATE FUNCTION admin.list_accessible_gateways(p_actor_portal_user_id BIGINT)
RETURNS TABLE(
    organization_id UUID, organization_code TEXT, organization_name TEXT,
    site_id UUID, site_code TEXT, site_name TEXT,
    gateway_id UUID, gateway_name TEXT, external_id TEXT,
    gateway_model_id UUID, gateway_vendor TEXT, gateway_model TEXT, gateway_protocol TEXT,
    building_id UUID, building_name TEXT, floor_id UUID, floor_name TEXT,
    space_id UUID, space_name TEXT, location_path TEXT,
    lifecycle_status TEXT, connectivity_status TEXT, last_seen_at TIMESTAMPTZ,
    online_threshold_seconds INTEGER, device_count BIGINT
)
LANGUAGE SQL STABLE SECURITY DEFINER
SET search_path TO pg_catalog, admin, analytics, metadata, telemetry, config
AS $function$
WITH policy AS (
    SELECT online_threshold_seconds FROM config.gateway_connectivity_policy WHERE policy_id=1
), last_seen AS (
    SELECT gateway_id,last_seen_at
    FROM analytics.v_gateway_connectivity
)
SELECT g.organization_id,o.code,o.name,g.site_id,s.code,s.name,
       g.id,g.name,g.external_id,g.gateway_model_id,gm.vendor,gm.model,gm.protocol,
       g.building_id,b.name,g.floor_id,f.name,g.space_id,sp.name,
       concat_ws(' / ',o.name,s.name,b.name,f.name,sp.name),
       g.lifecycle_status,
       CASE WHEN ls.last_seen_at IS NULL THEN 'NEVER_SEEN'
            WHEN ls.last_seen_at>=now()-make_interval(secs=>p.online_threshold_seconds) THEN 'ONLINE'
            ELSE 'OFFLINE' END,
       ls.last_seen_at,p.online_threshold_seconds,
       (SELECT count(*) FROM metadata.devices d WHERE d.gateway_id=g.id)
FROM metadata.gateways g
JOIN metadata.organizations o ON o.id=g.organization_id
JOIN metadata.sites s ON s.id=g.site_id
LEFT JOIN metadata.gateway_models gm ON gm.id=g.gateway_model_id
LEFT JOIN metadata.buildings b ON b.id=g.building_id
LEFT JOIN metadata.floors f ON f.id=g.floor_id
LEFT JOIN metadata.spaces sp ON sp.id=g.space_id
CROSS JOIN policy p
LEFT JOIN last_seen ls ON ls.gateway_id=g.id
WHERE admin.portal_user_can_access_site(p_actor_portal_user_id,g.site_id)
ORDER BY o.name,s.name,b.name,f.name,sp.name,g.name,g.lifecycle_status;
$function$;



COMMENT ON VIEW analytics.v_commissioning_readiness IS
'Declarative tenant-scoped readiness for assets, gateways, and devices. Gateway connectivity accepts explicit device-status events or recent mapped telemetry from assigned devices.';

-- Keep ownership and execution boundaries unchanged.
ALTER FUNCTION admin.get_gateway_workspace(BIGINT,UUID) OWNER TO ems_admin;
ALTER FUNCTION admin.list_accessible_gateways(BIGINT) OWNER TO ems_admin;
REVOKE ALL ON FUNCTION admin.get_gateway_workspace(BIGINT,UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION admin.list_accessible_gateways(BIGINT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION admin.get_gateway_workspace(BIGINT,UUID) TO ems_app;
GRANT EXECUTE ON FUNCTION admin.list_accessible_gateways(BIGINT) TO ems_app;


-- ====================================================================
-- Historical migration: 165_expand_environment_sensor_profile_and_storage.sql
-- ====================================================================

-- ============================================================================
-- Migration 165: expand environmental sensor profile and storage contract
--
-- Confirmed payload semantics:
--   T1    temperature (degC)
--   RH    relative humidity (%)
--   LL    illuminance (lux)
--   PIR   raw PIR activity value
--   PIR_t seconds since most recent PIR event
--   dis1  pulse/digital input 1 raw numeric value (semantics not over-claimed)
--   ain1..ain4 external sensor input raw numeric values
--   Vbat  battery voltage (V)
--   Stat  vendor device status code
--
-- uid/did/ts remain routing and timestamp fields and are not persisted as
-- dedicated columns in telemetry.environment_measurements.
-- ============================================================================


-- --------------------------------------------------------------------------
-- 1. Engineering unit and logical points.
-- --------------------------------------------------------------------------
INSERT INTO config.engineering_units(symbol, description)
VALUES ('s', 'Seconds')
ON CONFLICT (symbol) DO UPDATE SET description = EXCLUDED.description;

INSERT INTO metadata.logical_points(name, description, unit_id, data_type)
SELECT 'OCCUPANCY_SECONDS_SINCE_LAST_PIR_EVENT',
       'Elapsed seconds since the most recent PIR occupancy event.',
       eu.id,
       'numeric'
FROM config.engineering_units eu
WHERE eu.symbol = 's'
ON CONFLICT (name) DO UPDATE
SET description = EXCLUDED.description,
    unit_id = EXCLUDED.unit_id,
    data_type = EXCLUDED.data_type;

INSERT INTO metadata.logical_points(name, description, unit_id, data_type)
VALUES
('PULSE_INPUT_1_RAW', 'Raw numeric value reported by pulse/digital input 1; counter/state semantics are device-configuration dependent.', NULL, 'numeric'),
('EXTERNAL_SENSOR_INPUT_1_RAW', 'Raw numeric value reported by external sensor input 1.', NULL, 'numeric'),
('EXTERNAL_SENSOR_INPUT_2_RAW', 'Raw numeric value reported by external sensor input 2.', NULL, 'numeric'),
('EXTERNAL_SENSOR_INPUT_3_RAW', 'Raw numeric value reported by external sensor input 3.', NULL, 'numeric'),
('EXTERNAL_SENSOR_INPUT_4_RAW', 'Raw numeric value reported by external sensor input 4.', NULL, 'numeric'),
('DEVICE_STATUS_CODE', 'Vendor-reported numeric device status code.', NULL, 'numeric')
ON CONFLICT (name) DO UPDATE
SET description = EXCLUDED.description,
    unit_id = EXCLUDED.unit_id,
    data_type = EXCLUDED.data_type;

-- --------------------------------------------------------------------------
-- 2. Expand ENVIRONMENT_SENSOR_AIRSENSE_V1 profile mappings.
--    All measurement mappings remain optional.
-- --------------------------------------------------------------------------
DO $$
DECLARE
    v_profile_id UUID;
BEGIN
    SELECT id INTO v_profile_id
    FROM config.device_profiles
    WHERE profile_code = 'ENVIRONMENT_SENSOR_AIRSENSE_V1';

    IF v_profile_id IS NULL THEN
        RAISE EXCEPTION 'ENVIRONMENT_SENSOR_AIRSENSE_V1 profile not found';
    END IF;

    UPDATE config.device_profiles
    SET description = 'Generic optional-field profile for temperature, humidity, illuminance, PIR activity, seconds since last PIR event, pulse input, four external sensor inputs, battery voltage, and device status code.',
        updated_at = now()
    WHERE id = v_profile_id;

    INSERT INTO config.profile_field_mapping
        (profile_id, raw_field_name, logical_point_id, json_path,
         transform_expression, is_required, display_order)
    SELECT v_profile_id, m.raw_field_name, lp.id, NULL, NULL, FALSE, m.display_order
    FROM (VALUES
        ('PIR_t', 'OCCUPANCY_SECONDS_SINCE_LAST_PIR_EVENT', 50),
        ('dis1',  'PULSE_INPUT_1_RAW',                         60),
        ('ain1',  'EXTERNAL_SENSOR_INPUT_1_RAW',               70),
        ('ain2',  'EXTERNAL_SENSOR_INPUT_2_RAW',               80),
        ('ain3',  'EXTERNAL_SENSOR_INPUT_3_RAW',               90),
        ('ain4',  'EXTERNAL_SENSOR_INPUT_4_RAW',              100),
        ('Stat',  'DEVICE_STATUS_CODE',                       120)
    ) AS m(raw_field_name, logical_point_name, display_order)
    JOIN metadata.logical_points lp
      ON lp.name = m.logical_point_name
    ON CONFLICT (profile_id, raw_field_name) DO UPDATE
    SET logical_point_id = EXCLUDED.logical_point_id,
        json_path = EXCLUDED.json_path,
        transform_expression = EXCLUDED.transform_expression,
        is_required = FALSE,
        display_order = EXCLUDED.display_order;

    -- Keep the existing Vbat mapping after the new input fields in display order.
    UPDATE config.profile_field_mapping
    SET display_order = 110,
        is_required = FALSE
    WHERE profile_id = v_profile_id
      AND raw_field_name = 'Vbat';

    IF (
        SELECT count(*)
        FROM config.profile_field_mapping pfm
        WHERE pfm.profile_id = v_profile_id
          AND pfm.raw_field_name IN
              ('T1','RH','LL','PIR','PIR_t','dis1','ain1','ain2','ain3','ain4','Vbat','Stat')
          AND pfm.is_required = FALSE
    ) <> 12 THEN
        RAISE EXCEPTION 'Expected 12 optional environment profile mappings';
    END IF;
END;
$$;

-- --------------------------------------------------------------------------
-- 3. Extend destination table. Identity/lineage columns remain mandatory;
--    every measurement column remains nullable.
-- --------------------------------------------------------------------------
ALTER TABLE telemetry.environment_measurements
    ADD COLUMN IF NOT EXISTS seconds_since_last_pir_event INTEGER,
    ADD COLUMN IF NOT EXISTS pulse_input_1_raw DOUBLE PRECISION,
    ADD COLUMN IF NOT EXISTS external_input_1_raw DOUBLE PRECISION,
    ADD COLUMN IF NOT EXISTS external_input_2_raw DOUBLE PRECISION,
    ADD COLUMN IF NOT EXISTS external_input_3_raw DOUBLE PRECISION,
    ADD COLUMN IF NOT EXISTS external_input_4_raw DOUBLE PRECISION,
    ADD COLUMN IF NOT EXISTS device_status_code INTEGER;

COMMENT ON COLUMN telemetry.environment_measurements.seconds_since_last_pir_event IS
'Elapsed whole seconds since the most recent PIR event, mapped from PIR_t.';
COMMENT ON COLUMN telemetry.environment_measurements.pulse_input_1_raw IS
'Raw numeric value from dis1. Counter/state semantics depend on device configuration.';
COMMENT ON COLUMN telemetry.environment_measurements.external_input_1_raw IS 'Raw numeric external sensor input ain1.';
COMMENT ON COLUMN telemetry.environment_measurements.external_input_2_raw IS 'Raw numeric external sensor input ain2.';
COMMENT ON COLUMN telemetry.environment_measurements.external_input_3_raw IS 'Raw numeric external sensor input ain3.';
COMMENT ON COLUMN telemetry.environment_measurements.external_input_4_raw IS 'Raw numeric external sensor input ain4.';
COMMENT ON COLUMN telemetry.environment_measurements.device_status_code IS 'Vendor-reported numeric device status code mapped from Stat.';

-- --------------------------------------------------------------------------
-- 4. Full-resolution environment routing from normalized points.
--    No uid/did columns are introduced.
-- --------------------------------------------------------------------------
-- PostgreSQL cannot change an existing view column type through CREATE OR REPLACE.
-- Drop the closed-bucket route first because it depends on the full-resolution view,
-- then recreate both views with the intentional DOUBLE PRECISION contract.
DROP VIEW IF EXISTS telemetry.v_environment_measurements_route;
DROP VIEW IF EXISTS telemetry.v_environment_measurements_full_resolution;

CREATE VIEW telemetry.v_environment_measurements_full_resolution AS
SELECT
    MAX(np.platform_received_at) AS received_at,
    np.event_time AS source_timestamp,
    np.organization_id,
    np.site_id,
    np.gateway_id,
    np.device_id,
    NULL::UUID AS asset_id,
    NULL::SMALLINT AS measurement_interval_seconds,
    NULL::SMALLINT AS quality_code,
    FALSE AS is_estimated,
    MAX(np.numeric_value) FILTER (WHERE np.logical_point = 'ENV_TEMPERATURE')::DOUBLE PRECISION AS temperature_c,
    MAX(np.numeric_value) FILTER (WHERE np.logical_point = 'ENV_RELATIVE_HUMIDITY')::DOUBLE PRECISION AS humidity_percent,
    NULL::DOUBLE PRECISION AS pressure_hpa,
    NULL::DOUBLE PRECISION AS co2_ppm,
    NULL::DOUBLE PRECISION AS voc_ppb,
    MAX(np.numeric_value) FILTER (WHERE np.logical_point IN ('BATTERY_VOLTAGE','DEVICE_BATTERY_VOLTAGE'))::DOUBLE PRECISION AS battery_voltage_v,
    NULL::DOUBLE PRECISION AS signal_strength_dbm,
    MAX(np.numeric_value) FILTER (WHERE np.logical_point = 'ENV_ILLUMINANCE_LUX')::DOUBLE PRECISION AS illuminance_lux,
    MAX(np.numeric_value) FILTER (WHERE np.logical_point = 'OCCUPANCY_ACTIVITY')::DOUBLE PRECISION AS occupancy_activity,
    NULL::BIGINT AS raw_archive_id,
    ROUND(MAX(np.numeric_value) FILTER (WHERE np.logical_point = 'OCCUPANCY_SECONDS_SINCE_LAST_PIR_EVENT'))::INTEGER AS seconds_since_last_pir_event,
    MAX(np.numeric_value) FILTER (WHERE np.logical_point = 'PULSE_INPUT_1_RAW')::DOUBLE PRECISION AS pulse_input_1_raw,
    MAX(np.numeric_value) FILTER (WHERE np.logical_point = 'EXTERNAL_SENSOR_INPUT_1_RAW')::DOUBLE PRECISION AS external_input_1_raw,
    MAX(np.numeric_value) FILTER (WHERE np.logical_point = 'EXTERNAL_SENSOR_INPUT_2_RAW')::DOUBLE PRECISION AS external_input_2_raw,
    MAX(np.numeric_value) FILTER (WHERE np.logical_point = 'EXTERNAL_SENSOR_INPUT_3_RAW')::DOUBLE PRECISION AS external_input_3_raw,
    MAX(np.numeric_value) FILTER (WHERE np.logical_point = 'EXTERNAL_SENSOR_INPUT_4_RAW')::DOUBLE PRECISION AS external_input_4_raw,
    ROUND(MAX(np.numeric_value) FILTER (WHERE np.logical_point = 'DEVICE_STATUS_CODE'))::INTEGER AS device_status_code
FROM telemetry.normalized_points np
JOIN metadata.devices d ON d.id = np.device_id
JOIN config.device_profiles dp ON dp.id = d.profile_id
WHERE dp.profile_code = 'ENVIRONMENT_SENSOR_AIRSENSE_V1'
  AND np.logical_point IN
  (
      'ENV_TEMPERATURE','ENV_RELATIVE_HUMIDITY','ENV_ILLUMINANCE_LUX',
      'OCCUPANCY_ACTIVITY','OCCUPANCY_SECONDS_SINCE_LAST_PIR_EVENT',
      'PULSE_INPUT_1_RAW','EXTERNAL_SENSOR_INPUT_1_RAW','EXTERNAL_SENSOR_INPUT_2_RAW',
      'EXTERNAL_SENSOR_INPUT_3_RAW','EXTERNAL_SENSOR_INPUT_4_RAW',
      'DEVICE_BATTERY_VOLTAGE','BATTERY_VOLTAGE','DEVICE_STATUS_CODE'
  )
GROUP BY np.event_time, np.organization_id, np.site_id, np.gateway_id, np.device_id;

COMMENT ON VIEW telemetry.v_environment_measurements_full_resolution IS
'Full-resolution environmental readings pivoted from normalized points for ENVIRONMENT_SENSOR_AIRSENSE_V1; uid/did remain routing fields only.';

-- --------------------------------------------------------------------------
-- 5. Rebuild closed-bucket route with all optional fields.
-- --------------------------------------------------------------------------
CREATE VIEW telemetry.v_environment_measurements_route AS
WITH resolved AS
(
    SELECT r.*, b.policy_id, b.capture_interval_seconds,
           b.late_arrival_tolerance_seconds, b.bucket_start
    FROM telemetry.v_environment_measurements_full_resolution r
    CROSS JOIN LATERAL telemetry.resolve_site_capture_bucket
        (r.site_id, COALESCE(r.source_timestamp, r.received_at)) AS b
),
ranked AS
(
    SELECT resolved.*,
           row_number() OVER
           (
             PARTITION BY resolved.device_id, resolved.policy_id, resolved.bucket_start
             ORDER BY COALESCE(resolved.source_timestamp,resolved.received_at) DESC,
                      resolved.received_at DESC NULLS LAST
           ) AS sample_rank
    FROM resolved
)
SELECT
    ranked.bucket_start,
    ranked.received_at,
    ranked.source_timestamp,
    ranked.organization_id,
    ranked.site_id,
    ranked.gateway_id,
    ranked.device_id,
    ranked.asset_id,
    COALESCE(ranked.capture_interval_seconds, ranked.measurement_interval_seconds) AS measurement_interval_seconds,
    ranked.quality_code,
    ranked.is_estimated,
    ranked.temperature_c,
    ranked.humidity_percent,
    ranked.pressure_hpa,
    ranked.co2_ppm,
    ranked.voc_ppb,
    ranked.battery_voltage_v,
    ranked.signal_strength_dbm,
    ranked.illuminance_lux,
    ranked.occupancy_activity,
    ranked.raw_archive_id,
    ranked.seconds_since_last_pir_event,
    ranked.pulse_input_1_raw,
    ranked.external_input_1_raw,
    ranked.external_input_2_raw,
    ranked.external_input_3_raw,
    ranked.external_input_4_raw,
    ranked.device_status_code
FROM ranked
WHERE ranked.sample_rank = 1
  AND ranked.bucket_start + make_interval(secs => COALESCE(ranked.capture_interval_seconds,1)) <= clock_timestamp();

COMMENT ON VIEW telemetry.v_environment_measurements_route IS
'Closed-bucket environmental route with optional AirSense PIR timer, pulse input, four external inputs, battery and status fields.';

-- --------------------------------------------------------------------------
-- 6. Planner-safe incremental environment loader.
--    Uses UPDATE + INSERT instead of correlated ON CONFLICT subplans.
-- --------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE telemetry.load_environment_measurements_incremental
(
    p_overlap INTERVAL DEFAULT INTERVAL '15 minutes'
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_pipeline_name CONSTANT TEXT := 'environment_measurements';
    v_previous_checkpoint TIMESTAMPTZ;
    v_window_start TIMESTAMPTZ;
    v_window_end TIMESTAMPTZ;
    v_updated BIGINT := 0;
    v_inserted BIGINT := 0;
    v_lock_acquired BOOLEAN;
    v_now TIMESTAMPTZ := clock_timestamp();
BEGIN
    IF p_overlap IS NULL OR p_overlap < INTERVAL '0 seconds' THEN
        RAISE EXCEPTION 'p_overlap must be zero or positive';
    END IF;

    SELECT pg_try_advisory_xact_lock(hashtextextended('telemetry.load_environment_measurements_incremental',0))
    INTO v_lock_acquired;
    IF NOT v_lock_acquired THEN
        UPDATE telemetry.pipeline_state
        SET last_status='SKIPPED_LOCKED', last_error=NULL, updated_at=now()
        WHERE pipeline_name=v_pipeline_name;
        RETURN;
    END IF;

    SELECT last_received_at INTO v_previous_checkpoint
    FROM telemetry.pipeline_state
    WHERE pipeline_name=v_pipeline_name
    FOR UPDATE;

    UPDATE telemetry.pipeline_state
    SET last_started_at=clock_timestamp(), last_status='RUNNING', last_error=NULL, updated_at=now()
    WHERE pipeline_name=v_pipeline_name;

    SELECT max(created_at) INTO v_window_end FROM telemetry.normalized_points;
    IF v_window_end IS NULL THEN
        UPDATE telemetry.pipeline_state
        SET last_completed_at=clock_timestamp(), last_inserted_rows=0,
            last_status='NO_SOURCE_DATA', updated_at=now()
        WHERE pipeline_name=v_pipeline_name;
        RETURN;
    END IF;

    SELECT GREATEST
    (
        p_overlap,
        make_interval(secs => COALESCE(max(late_arrival_tolerance_seconds),900))
    ) INTO p_overlap
    FROM config.telemetry_capture_policies
    WHERE is_enabled;

    v_window_start := CASE WHEN v_previous_checkpoint IS NULL
                           THEN '-infinity'::TIMESTAMPTZ
                           ELSE v_previous_checkpoint - p_overlap END;

    CREATE TEMP TABLE tmp_environment_candidates ON COMMIT DROP AS
    WITH affected AS
    (
        SELECT DISTINCT b.bucket_start, np.device_id
        FROM telemetry.normalized_points np
        CROSS JOIN LATERAL telemetry.resolve_site_capture_bucket
            (np.site_id, np.event_time) AS b
        WHERE np.created_at > v_window_start
          AND np.created_at <= v_window_end
          AND np.logical_point IN
          (
              'ENV_TEMPERATURE','ENV_RELATIVE_HUMIDITY','ENV_ILLUMINANCE_LUX',
              'OCCUPANCY_ACTIVITY','OCCUPANCY_SECONDS_SINCE_LAST_PIR_EVENT',
              'PULSE_INPUT_1_RAW','EXTERNAL_SENSOR_INPUT_1_RAW','EXTERNAL_SENSOR_INPUT_2_RAW',
              'EXTERNAL_SENSOR_INPUT_3_RAW','EXTERNAL_SENSOR_INPUT_4_RAW',
              'DEVICE_BATTERY_VOLTAGE','BATTERY_VOLTAGE','DEVICE_STATUS_CODE'
          )
    )
    SELECT r.*,
           r.bucket_start
             + make_interval(secs => b.capture_interval_seconds)
             + make_interval(secs => b.late_arrival_tolerance_seconds) AS correction_deadline
    FROM telemetry.v_environment_measurements_route r
    JOIN affected a
      ON a.bucket_start=r.bucket_start AND a.device_id=r.device_id
    CROSS JOIN LATERAL telemetry.resolve_site_capture_bucket
      (r.site_id, COALESCE(r.source_timestamp,r.received_at)) AS b;

    CREATE UNIQUE INDEX ON tmp_environment_candidates(bucket_start,device_id);

    UPDATE telemetry.environment_measurements t
    SET received_at=s.received_at,
        source_timestamp=s.source_timestamp,
        organization_id=s.organization_id,
        site_id=s.site_id,
        gateway_id=s.gateway_id,
        asset_id=COALESCE(s.asset_id,t.asset_id),
        measurement_interval_seconds=s.measurement_interval_seconds,
        quality_code=COALESCE(s.quality_code,t.quality_code),
        is_estimated=COALESCE(s.is_estimated,t.is_estimated),
        temperature_c=COALESCE(s.temperature_c,t.temperature_c),
        humidity_percent=COALESCE(s.humidity_percent,t.humidity_percent),
        pressure_hpa=COALESCE(s.pressure_hpa,t.pressure_hpa),
        co2_ppm=COALESCE(s.co2_ppm,t.co2_ppm),
        voc_ppb=COALESCE(s.voc_ppb,t.voc_ppb),
        battery_voltage_v=COALESCE(s.battery_voltage_v,t.battery_voltage_v),
        signal_strength_dbm=COALESCE(s.signal_strength_dbm,t.signal_strength_dbm),
        illuminance_lux=COALESCE(s.illuminance_lux,t.illuminance_lux),
        occupancy_activity=COALESCE(s.occupancy_activity,t.occupancy_activity),
        raw_archive_id=COALESCE(s.raw_archive_id,t.raw_archive_id),
        seconds_since_last_pir_event=COALESCE(s.seconds_since_last_pir_event,t.seconds_since_last_pir_event),
        pulse_input_1_raw=COALESCE(s.pulse_input_1_raw,t.pulse_input_1_raw),
        external_input_1_raw=COALESCE(s.external_input_1_raw,t.external_input_1_raw),
        external_input_2_raw=COALESCE(s.external_input_2_raw,t.external_input_2_raw),
        external_input_3_raw=COALESCE(s.external_input_3_raw,t.external_input_3_raw),
        external_input_4_raw=COALESCE(s.external_input_4_raw,t.external_input_4_raw),
        device_status_code=COALESCE(s.device_status_code,t.device_status_code)
    FROM tmp_environment_candidates s
    WHERE t.bucket_start=s.bucket_start
      AND t.device_id=s.device_id
      AND COALESCE(s.source_timestamp,s.received_at) >
          COALESCE(t.source_timestamp,t.received_at,'-infinity'::TIMESTAMPTZ)
      AND v_now <= s.correction_deadline;
    GET DIAGNOSTICS v_updated = ROW_COUNT;

    INSERT INTO telemetry.environment_measurements
    (
      bucket_start, received_at, source_timestamp,
      organization_id, site_id, gateway_id, device_id, asset_id,
      measurement_interval_seconds, quality_code, is_estimated,
      temperature_c, humidity_percent, pressure_hpa, co2_ppm, voc_ppb,
      battery_voltage_v, signal_strength_dbm, illuminance_lux, occupancy_activity,
      raw_archive_id, seconds_since_last_pir_event, pulse_input_1_raw,
      external_input_1_raw, external_input_2_raw, external_input_3_raw,
      external_input_4_raw, device_status_code
    )
    SELECT
      s.bucket_start, s.received_at, s.source_timestamp,
      s.organization_id, s.site_id, s.gateway_id, s.device_id, s.asset_id,
      s.measurement_interval_seconds, s.quality_code, s.is_estimated,
      s.temperature_c, s.humidity_percent, s.pressure_hpa, s.co2_ppm, s.voc_ppb,
      s.battery_voltage_v, s.signal_strength_dbm, s.illuminance_lux, s.occupancy_activity,
      s.raw_archive_id, s.seconds_since_last_pir_event, s.pulse_input_1_raw,
      s.external_input_1_raw, s.external_input_2_raw, s.external_input_3_raw,
      s.external_input_4_raw, s.device_status_code
    FROM tmp_environment_candidates s
    ON CONFLICT (bucket_start,device_id) WHERE device_id IS NOT NULL DO NOTHING;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;

    UPDATE telemetry.pipeline_state
    SET last_received_at=v_window_end,
        last_completed_at=clock_timestamp(),
        last_inserted_rows=v_updated+v_inserted,
        last_status='SUCCESS', last_error=NULL, updated_at=now()
    WHERE pipeline_name=v_pipeline_name;

    RAISE NOTICE 'Environment routing succeeded: window=(%, %], updated=%, inserted=%',
      v_window_start, v_window_end, v_updated, v_inserted;
EXCEPTION WHEN OTHERS THEN
    UPDATE telemetry.pipeline_state
    SET last_completed_at=clock_timestamp(), last_inserted_rows=0,
        last_status='FAILED', last_error=SQLSTATE || ': ' || SQLERRM, updated_at=now()
    WHERE pipeline_name=v_pipeline_name;
    RAISE;
END;
$$;

-- --------------------------------------------------------------------------
-- 7. Append the new fields to the latest-reading analytics view.
-- --------------------------------------------------------------------------
CREATE OR REPLACE VIEW analytics.v_environment_latest
WITH (security_barrier = TRUE) AS
SELECT DISTINCT ON (gom.grafana_org_id, em.device_id)
    gom.grafana_org_id,
    em.organization_id,
    em.site_id,
    em.gateway_id,
    em.device_id,
    em.asset_id,
    s.code AS site_code,
    s.name AS site_name,
    d.external_id,
    d.name AS device_name,
    d.serial_number,
    dp.profile_code,
    dp.profile_name,
    em.received_at,
    em.source_timestamp,
    em.temperature_c,
    em.humidity_percent,
    em.pressure_hpa,
    em.co2_ppm,
    em.voc_ppb,
    em.illuminance_lux,
    em.occupancy_activity,
    em.battery_voltage_v,
    em.signal_strength_dbm,
    em.measurement_interval_seconds,
    em.quality_code,
    em.is_estimated,
    EXTRACT(EPOCH FROM (now() - COALESCE(em.received_at,em.source_timestamp)))::BIGINT AS data_age_seconds,
    em.seconds_since_last_pir_event,
    em.pulse_input_1_raw,
    em.external_input_1_raw,
    em.external_input_2_raw,
    em.external_input_3_raw,
    em.external_input_4_raw,
    em.device_status_code
FROM metadata.grafana_organization_map gom
JOIN telemetry.environment_measurements em ON em.organization_id=gom.organization_id
JOIN metadata.devices d ON d.id=em.device_id
LEFT JOIN metadata.sites s ON s.id=em.site_id
LEFT JOIN config.device_profiles dp ON dp.id=d.profile_id
WHERE gom.is_active=TRUE
ORDER BY gom.grafana_org_id, em.device_id, em.bucket_start DESC, em.id DESC;

COMMENT ON VIEW analytics.v_environment_latest IS
'Newest environmental measurement per tenant/device including PIR timer, pulse input, external inputs, battery and status code.';

GRANT SELECT ON telemetry.v_environment_measurements_full_resolution,
                telemetry.v_environment_measurements_route
TO ems_readonly, grafana_reader;
GRANT SELECT ON analytics.v_environment_latest TO ems_readonly, grafana_reader;


-- ====================================================================
-- Historical migration: 166_device_tab_system_generated_external_id.sql
-- ====================================================================

-- Migration 166
-- Align direct Device Administration creation with onboarding-generated ID behavior.
-- External IDs are generated/resolved by the database; physical telemetry UID
-- conflicts remain hard failures.

CREATE OR REPLACE FUNCTION admin.create_device(
    p_actor_portal_user_id BIGINT,
    p_gateway_id UUID,
    p_name TEXT,
    p_external_id TEXT,
    p_device_category_id UUID,
    p_device_model_id UUID,
    p_profile_id UUID,
    p_protocol TEXT,
    p_lifecycle_status TEXT,
    p_firmware_version TEXT,
    p_serial_number TEXT,
    p_use_gateway_location BOOLEAN,
    p_building_id UUID,
    p_floor_id UUID,
    p_space_id UUID,
    p_identifier_type TEXT,
    p_identifier_value TEXT,
    p_operational_policy TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO pg_catalog, admin, metadata, config
AS $function$
DECLARE
    v_actor_username TEXT;
    v_gateway metadata.gateways%ROWTYPE;
    v_name TEXT := btrim(p_name);
    v_external_id TEXT := upper(btrim(p_external_id));
    v_protocol TEXT := upper(btrim(p_protocol));
    v_lifecycle TEXT := upper(btrim(p_lifecycle_status));
    v_firmware TEXT := nullif(btrim(p_firmware_version),'');
    v_serial TEXT := nullif(btrim(p_serial_number),'');
    v_identifier_type TEXT := upper(btrim(p_identifier_type));
    v_identifier_value TEXT := lower(btrim(p_identifier_value));
    v_policy TEXT := upper(btrim(p_operational_policy));
    v_location_mode TEXT := CASE WHEN p_use_gateway_location THEN 'GATEWAY' ELSE 'DEVICE' END;
    v_building UUID := CASE WHEN p_use_gateway_location THEN NULL ELSE p_building_id END;
    v_floor UUID := CASE WHEN p_use_gateway_location THEN NULL ELSE p_floor_id END;
    v_space UUID := CASE WHEN p_use_gateway_location THEN NULL ELSE p_space_id END;
    v_device_id UUID;
    v_audit_id UUID := gen_random_uuid();
    v_result JSONB;
BEGIN
    SELECT pu.username INTO v_actor_username
    FROM admin.portal_users pu
    WHERE pu.portal_user_id=p_actor_portal_user_id AND pu.is_active;
    IF NOT FOUND OR NOT admin.portal_user_has_permission(
        p_actor_portal_user_id,'device.manage'
    ) THEN
        RAISE EXCEPTION 'Portal actor is not authorized to create devices.'
            USING ERRCODE='42501';
    END IF;

    SELECT * INTO v_gateway FROM metadata.gateways WHERE id=p_gateway_id;
    IF NOT FOUND OR v_gateway.lifecycle_status='DECOMMISSIONED' THEN
        RAISE EXCEPTION 'Select an available gateway.' USING ERRCODE='22023';
    END IF;
    IF NOT admin.portal_user_can_access_site(p_actor_portal_user_id,v_gateway.site_id) THEN
        RAISE EXCEPTION 'Portal actor cannot access the gateway site.' USING ERRCODE='42501';
    END IF;

    IF v_name IS NULL OR v_name='' OR length(v_name)>200 THEN
        RAISE EXCEPTION 'Device name is required and must not exceed 200 characters.' USING ERRCODE='22023';
    END IF;
    -- Device external IDs are system-managed. Accept the submitted value as a
    -- preferred base, fall back to the device name, normalize it, and resolve
    -- organization-scoped conflicts atomically in the database.
    v_external_id := admin.recommend_available_identifier(
        'DEVICE',
        coalesce(nullif(v_external_id, ''), v_name),
        v_gateway.organization_id,
        NULL,
        NULL,
        NULL,
        NULL
    );
    IF v_protocol NOT IN ('MQTT','MODBUS TCP','MODBUS RTU','BACNET IP','BACNET MS/TP','OPC-UA','HTTP API') THEN
        RAISE EXCEPTION 'Select a supported device communication protocol.' USING ERRCODE='22023';
    END IF;
    IF v_lifecycle NOT IN ('DISCOVERED','REGISTERED','UNASSIGNED','COMMISSIONING','INACTIVE','DECOMMISSIONED') THEN
        RAISE EXCEPTION 'Select a valid initial device lifecycle status.' USING ERRCODE='22023';
    END IF;
    IF v_policy NOT IN ('STANDALONE','ASSET_ASSIGNED') THEN
        RAISE EXCEPTION 'Select a valid operational policy.' USING ERRCODE='22023';
    END IF;
    IF length(coalesce(v_firmware,''))>100 OR length(coalesce(v_serial,''))>200 THEN
        RAISE EXCEPTION 'Firmware or serial number exceeds the supported length.' USING ERRCODE='22023';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM metadata.device_models dm
        WHERE dm.id=p_device_model_id AND dm.device_category_id=p_device_category_id
    ) THEN
        RAISE EXCEPTION 'Device model does not match the selected category.' USING ERRCODE='22023';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM config.device_profiles dp
        JOIN config.device_profile_categories dpc ON dpc.profile_id=dp.id
        WHERE dp.id=p_profile_id AND dp.is_active
          AND dpc.device_category_id=p_device_category_id
    ) THEN
        RAISE EXCEPTION 'Device profile is not compatible with the selected category.' USING ERRCODE='22023';
    END IF;
    IF v_identifier_type <> 'MQTT_UID' OR
       v_identifier_value !~ '^[0-9a-f]{2}(:[0-9a-f]{2}){7}$' THEN
        RAISE EXCEPTION 'MQTT UID must contain eight hexadecimal byte pairs separated by colons.' USING ERRCODE='22023';
    END IF;
    IF EXISTS (
        SELECT 1 FROM metadata.device_identifiers di
        WHERE upper(di.identifier_type)=v_identifier_type
          AND lower(di.identifier_value)=v_identifier_value
    ) THEN
        RAISE EXCEPTION 'This device identifier is already assigned.' USING ERRCODE='23505';
    END IF;

    IF v_floor IS NOT NULL AND v_building IS NULL THEN
        RAISE EXCEPTION 'A selected floor requires its building.' USING ERRCODE='22023';
    END IF;
    IF v_space IS NOT NULL AND v_floor IS NULL THEN
        RAISE EXCEPTION 'A selected space requires its floor.' USING ERRCODE='22023';
    END IF;
    IF v_building IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM metadata.buildings b
        WHERE b.id=v_building AND b.site_id=v_gateway.site_id
    ) THEN
        RAISE EXCEPTION 'Selected building is not in the gateway site.' USING ERRCODE='22023';
    END IF;
    IF v_floor IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM metadata.floors f
        JOIN metadata.buildings b ON b.id=f.building_id
        WHERE f.id=v_floor AND f.building_id=v_building AND b.site_id=v_gateway.site_id
    ) THEN
        RAISE EXCEPTION 'Selected floor is not in the selected building.' USING ERRCODE='22023';
    END IF;
    IF v_space IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM metadata.spaces sp WHERE sp.id=v_space AND sp.floor_id=v_floor
    ) THEN
        RAISE EXCEPTION 'Selected space is not in the selected floor.' USING ERRCODE='22023';
    END IF;

    INSERT INTO metadata.devices(
        organization_id,gateway_id,device_model_id,profile_id,name,external_id,
        serial_number,firmware_version,protocol,lifecycle_status,
        operational_policy,location_mode,building_id,floor_id,space_id
    ) VALUES (
        v_gateway.organization_id,p_gateway_id,p_device_model_id,p_profile_id,
        v_name,v_external_id,v_serial,v_firmware,v_protocol,v_lifecycle,
        v_policy,v_location_mode,v_building,v_floor,v_space
    ) RETURNING id INTO v_device_id;

    INSERT INTO metadata.device_identifiers(device_id,identifier_type,identifier_value)
    VALUES (v_device_id,v_identifier_type,v_identifier_value);

    v_result:=jsonb_build_object(
        'success',TRUE,'entity_type','DEVICE','entity_id',v_device_id,
        'device_id',v_device_id,'organization_id',v_gateway.organization_id,
        'site_id',v_gateway.site_id,'gateway_id',p_gateway_id,
        'device_name',v_name,'external_id',v_external_id,
        'device_category_id',p_device_category_id,'device_model_id',p_device_model_id,
        'profile_id',p_profile_id,'protocol',v_protocol,
        'identifier_type',v_identifier_type,'identifier_value',v_identifier_value,
        'operational_policy',v_policy,'location_mode',v_location_mode,
        'building_id',v_building,'floor_id',v_floor,'space_id',v_space,
        'lifecycle_status',v_lifecycle,'commissioning_status','NOT_STARTED',
        'validation_warnings','[]'::jsonb,'blocking_conditions','[]'::jsonb,
        'audit_transaction_id',v_audit_id
    );
    INSERT INTO admin.onboarding_audit(id,requested_by,request_payload,result_payload)
    VALUES (v_audit_id,v_actor_username,jsonb_build_object(
        'operation','CREATE_DEVICE','actor_portal_user_id',p_actor_portal_user_id,
        'gateway_id',p_gateway_id,'name',v_name,'external_id',v_external_id,
        'device_category_id',p_device_category_id,'device_model_id',p_device_model_id,
        'profile_id',p_profile_id,'protocol',v_protocol,'identifier_type',v_identifier_type,
        'identifier_value',v_identifier_value,'operational_policy',v_policy,
        'location_mode',v_location_mode,'building_id',v_building,
        'floor_id',v_floor,'space_id',v_space),v_result);
    RETURN v_result;
EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'A device external ID or telemetry identifier already exists.' USING ERRCODE='23505';
END;
$function$;


COMMENT ON FUNCTION admin.create_device(
    BIGINT,UUID,TEXT,TEXT,UUID,UUID,UUID,TEXT,TEXT,TEXT,TEXT,BOOLEAN,
    UUID,UUID,UUID,TEXT,TEXT,TEXT
) IS 'Creates a device atomically. Resolves organization-scoped device external ID conflicts while preserving strict uniqueness for physical telemetry identifiers.';


